#[cfg(windows)]
fn alignment_benchmark_accounting_job() -> Result<&'static AlignmentBenchmarkAccountingJob, String>
{
    let result =
        ALIGNMENT_BENCHMARK_ACCOUNTING_JOB.get_or_init(create_alignment_benchmark_accounting_job);
    result.as_ref().map_err(|error| error.clone())
}

#[cfg(windows)]
fn create_alignment_benchmark_accounting_job() -> Result<AlignmentBenchmarkAccountingJob, String> {
    use std::ptr::null;
    use windows_sys::Win32::{
        Foundation::CloseHandle,
        System::{
            JobObjects::{AssignProcessToJobObject, CreateJobObjectW},
            Threading::GetCurrentProcess,
        },
    };

    // SAFETY: null security attributes and name create a private, unnamed Job Object.
    let handle = unsafe { CreateJobObjectW(null(), null()) };
    if handle.is_null() {
        return Err("Windows benchmark accounting Job Object 创建失败。".to_string());
    }
    // The current process becomes the root member once for the application lifetime. Every
    // subsequently spawned media process inherits this job; process_supervision then assigns the
    // suspended child to its private kill-on-close job, forming a nested child job on Windows 8+.
    // SAFETY: handle is an owned job handle and GetCurrentProcess returns the current pseudo handle.
    if unsafe { AssignProcessToJobObject(handle, GetCurrentProcess()) } == 0 {
        // SAFETY: assignment failed, so closing the otherwise-unpublished owned handle is safe.
        unsafe { CloseHandle(handle) };
        return Err(
            "当前进程无法加入 Windows benchmark accounting Job Object；不能生成正式内存证据。"
                .to_string(),
        );
    }
    Ok(AlignmentBenchmarkAccountingJob {
        handle: handle as usize,
    })
}

#[cfg(windows)]
fn sample_windows_job_hierarchy_memory(
    job: &AlignmentBenchmarkAccountingJob,
) -> Result<ProcessTreeMemorySample, String> {
    const MAX_STABLE_MEMBERSHIP_ATTEMPTS: usize = 8;
    for _ in 0..MAX_STABLE_MEMBERSHIP_ATTEMPTS {
        let before = query_windows_job_process_ids(job)?;
        let Ok(working_set_bytes) = read_windows_process_working_sets(&before) else {
            continue;
        };
        let after = query_windows_job_process_ids(job)?;
        if before != after {
            continue;
        }
        let root_pid = std::process::id();
        if before.binary_search(&root_pid).is_err() {
            return Err("Windows benchmark Job Object 成员列表缺少应用根进程。".to_string());
        }
        return Ok(ProcessTreeMemorySample {
            working_set_bytes,
            descendants: before.into_iter().filter(|pid| *pid != root_pid).collect(),
        });
    }
    Err("Windows benchmark Job Object 成员在采样期间持续变化，覆盖不完整。".to_string())
}

#[cfg(windows)]
fn query_windows_job_process_ids(
    job: &AlignmentBenchmarkAccountingJob,
) -> Result<Vec<u32>, String> {
    use std::{mem::size_of, ptr::null_mut};
    use windows_sys::Win32::System::JobObjects::{
        JobObjectBasicProcessIdList, QueryInformationJobObject, JOBOBJECT_BASIC_PROCESS_ID_LIST,
    };

    const MAX_ACCOUNTING_JOB_PROCESSES: usize = 4_096;
    let buffer_bytes = size_of::<JOBOBJECT_BASIC_PROCESS_ID_LIST>()
        .checked_add((MAX_ACCOUNTING_JOB_PROCESSES - 1) * size_of::<usize>())
        .ok_or_else(|| "Windows Job Object PID 缓冲区大小溢出。".to_string())?;
    let word_count = buffer_bytes.div_ceil(size_of::<usize>());
    let mut buffer = vec![0_usize; word_count];
    // SAFETY: buffer is writable, suitably aligned for the documented structure and bounded to u32.
    let queried = unsafe {
        QueryInformationJobObject(
            job.raw(),
            JobObjectBasicProcessIdList,
            buffer.as_mut_ptr().cast(),
            buffer_bytes as u32,
            null_mut(),
        )
    };
    if queried == 0 {
        return Err("Windows benchmark Job Object 成员查询失败或超过 4096 个进程。".to_string());
    }
    // SAFETY: QueryInformationJobObject initialized the structure at the start of buffer.
    let list = unsafe { &*(buffer.as_ptr().cast::<JOBOBJECT_BASIC_PROCESS_ID_LIST>()) };
    let assigned = list.NumberOfAssignedProcesses as usize;
    let returned = list.NumberOfProcessIdsInList as usize;
    if assigned == 0 || assigned != returned || returned > MAX_ACCOUNTING_JOB_PROCESSES {
        return Err("Windows benchmark Job Object 成员列表不完整。".to_string());
    }
    // SAFETY: returned was validated against the allocated variable-length PID array.
    let process_ids = unsafe { std::slice::from_raw_parts(list.ProcessIdList.as_ptr(), returned) };
    let mut pids = process_ids
        .iter()
        .map(|raw_pid| {
            u32::try_from(*raw_pid)
                .map_err(|_| "Windows benchmark Job Object 返回了越界 PID。".to_string())
        })
        .collect::<Result<Vec<_>, _>>()?;
    pids.sort_unstable();
    if pids.windows(2).any(|pair| pair[0] == pair[1]) {
        return Err("Windows benchmark Job Object 返回了重复 PID。".to_string());
    }
    Ok(pids)
}

#[cfg(windows)]
fn read_windows_process_working_sets(process_ids: &[u32]) -> Result<u64, String> {
    use std::mem::size_of;
    use windows_sys::Win32::{
        Foundation::CloseHandle,
        System::{
            ProcessStatus::{GetProcessMemoryInfo, PROCESS_MEMORY_COUNTERS},
            Threading::{OpenProcess, PROCESS_QUERY_LIMITED_INFORMATION},
        },
    };

    let mut working_set_bytes = 0_u64;
    for pid in process_ids {
        // SAFETY: pid comes from the owned Job Object membership list; no handle is inherited.
        let process = unsafe { OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, *pid) };
        if process.is_null() {
            return Err("Windows benchmark Job Object 中至少一个成员无法打开。".to_string());
        }
        let mut counters = PROCESS_MEMORY_COUNTERS {
            cb: size_of::<PROCESS_MEMORY_COUNTERS>() as u32,
            ..PROCESS_MEMORY_COUNTERS::default()
        };
        // SAFETY: process is open and counters points to a writable structure of the given size.
        let read = unsafe {
            GetProcessMemoryInfo(
                process,
                &mut counters,
                size_of::<PROCESS_MEMORY_COUNTERS>() as u32,
            )
        };
        // SAFETY: process is an owned handle returned by OpenProcess.
        unsafe { CloseHandle(process) };
        if read == 0 {
            return Err("Windows benchmark Job Object 成员 working set 读取失败。".to_string());
        }
        working_set_bytes = working_set_bytes
            .checked_add(counters.WorkingSetSize as u64)
            .ok_or_else(|| "Windows benchmark Job Object working set 求和溢出。".to_string())?;
    }
    Ok(working_set_bytes)
}

#[cfg(test)]
fn align_audio_files_inner(
    request: AudioAlignmentRequest,
) -> Result<AudioAlignmentProposal, String> {
    let spectral_backend_request = resolve_audio_alignment_request_spectral_backend(&request)?;
    align_audio_files_inner_with_spectral_backend_request(request, spectral_backend_request)
}

fn align_audio_files_inner_with_spectral_backend_request(
    request: AudioAlignmentRequest,
    spectral_backend_request: SpectralBackendRequest,
) -> Result<AudioAlignmentProposal, String> {
    let mut update = |_progress: f64, _message: &str| Ok(());
    align_audio_files_with_progress_and_spectral_backend_request(
        request,
        spectral_backend_request,
        &mut update,
        None,
    )
}

fn align_audio_files_with_progress_and_spectral_backend_request<F>(
    request: AudioAlignmentRequest,
    spectral_backend_request: SpectralBackendRequest,
    update_progress: &mut F,
    cancel_flag: Option<&AtomicBool>,
) -> Result<AudioAlignmentProposal, String>
where
    F: FnMut(f64, &str) -> Result<(), String>,
{
    ensure_alignment_process_supervision_clean()?;
    let (options, toolchain) = create_pinned_audio_alignment_options_with_spectral_backend_request(
        &request,
        &spectral_backend_request,
    )?;
    align_audio_files_with_pinned_toolchain(
        request,
        &options,
        &toolchain,
        update_progress,
        cancel_flag,
    )
}

fn align_audio_files_with_pinned_toolchain<F>(
    request: AudioAlignmentRequest,
    options: &AudioAlignmentOptions,
    toolchain: &PinnedMediaToolchain,
    update_progress: &mut F,
    cancel_flag: Option<&AtomicBool>,
) -> Result<AudioAlignmentProposal, String>
where
    F: FnMut(f64, &str) -> Result<(), String>,
{
    ensure_alignment_process_supervision_clean()?;
    toolchain.verify_at_start()?;
    audio_alignment_toolchain_cache_identity(options)?;
    validate_media_input(&request.complete_path, "目标原片")?;
    validate_media_input(&request.source_path, "B 站参考")?;
    let _media_read_lease =
        acquire_alignment_media_read_lease(&request.source_path, &request.complete_path)?;
    let target_run_identity =
        probe_alignment_run_expected_identity(&request.complete_path, cancel_flag, "目标原片")?;
    let source_run_identity =
        probe_alignment_run_expected_identity(&request.source_path, cancel_flag, "B 站参考")?;
    let target_path = request.complete_path.clone();
    let source_path = request.source_path.clone();
    let result =
        align_audio_files_with_progress_impl(request, options, update_progress, cancel_flag);
    // A lower layer may deliberately downgrade ordinary evidence failures, but a process-tree
    // cleanup failure is never evidence. It invalidates the current run even if a fallback later
    // managed to construct a proposal.
    ensure_alignment_process_supervision_clean()?;
    toolchain.verify_at_finalization()?;
    if let Ok(proposal) = &result {
        verify_media_content_identity_after_tool_output(
            &source_path,
            Some(&source_run_identity),
            cancel_flag,
            "对齐结果最终复核",
        )?;
        verify_media_content_identity_after_tool_output(
            &target_path,
            Some(&target_run_identity),
            cancel_flag,
            "对齐结果最终复核",
        )?;
        verify_proposal_time_map_identities_match_run(
            proposal,
            &source_run_identity,
            &target_run_identity,
        )?;
    }
    result
}

fn align_audio_files_with_progress_impl<F>(
    request: AudioAlignmentRequest,
    options: &AudioAlignmentOptions,
    update_progress: &mut F,
    cancel_flag: Option<&AtomicBool>,
) -> Result<AudioAlignmentProposal, String>
where
    F: FnMut(f64, &str) -> Result<(), String>,
{
    check_cancelled(cancel_flag)?;
    benchmark_stage("validating", "校验输入与媒体时间线");
    update_progress(0.05, "正在校验本地媒体路径。")?;
    validate_media_input(&request.complete_path, "完整版")?;
    validate_media_input(&request.source_path, "当前视频")?;
    if options.localization_mode {
        return align_audio_files_v2_with_progress(
            &request,
            options,
            update_progress,
            cancel_flag,
            None,
        );
    }
    update_progress(0.08, "正在探测媒体展示时间线和可用音轨。")?;
    let complete_audio_input = probe_alignment_audio_input(
        &request.complete_path,
        "完整版",
        request.complete_audio_stream_index,
        options,
        cancel_flag,
    )?;
    check_cancelled(cancel_flag)?;
    let source_audio_input = probe_alignment_audio_input(
        &request.source_path,
        "当前视频",
        request.source_audio_stream_index,
        options,
        cancel_flag,
    )?;
    update_progress(0.10, "已确认媒体展示时间线、音轨和对齐参数。")?;
    check_cancelled(cancel_flag)?;
    benchmark_stage("extracting-complete", "提取目标原片音频特征");
    update_progress(0.12, "正在检查或提取完整版音频特征。")?;
    let complete_features = get_audio_features(
        &request.complete_path,
        "完整版",
        options,
        &complete_audio_input,
        cancel_flag,
    )?;
    update_progress(
        0.36,
        &format_audio_feature_cache_message("完整版", &complete_features),
    )?;
    check_cancelled(cancel_flag)?;
    benchmark_stage("extracting-source", "提取参考视频音频特征");
    update_progress(0.40, "正在检查或提取当前视频音频特征。")?;
    let source_features = get_audio_features(
        &request.source_path,
        "当前视频",
        options,
        &source_audio_input,
        cancel_flag,
    )?;
    update_progress(
        0.64,
        &format_audio_feature_cache_message("当前视频", &source_features),
    )?;
    check_cancelled(cancel_flag)?;
    let mut visual_features: Option<(CachedVisualFeatures, CachedVisualFeatures)> = None;
    let mut visual_error: Option<String> = None;
    if options.enable_visual_evidence {
        benchmark_stage("extracting-visual", "提取独立视觉证据");
        update_progress(0.68, "正在提取鲁棒视觉证据。")?;
        match (
            get_visual_features(
                &request.complete_path,
                "完整版",
                options,
                complete_audio_input.content_identity.as_ref(),
                cancel_flag,
            ),
            get_visual_features(
                &request.source_path,
                "当前视频",
                options,
                source_audio_input.content_identity.as_ref(),
                cancel_flag,
            ),
        ) {
            (Ok(complete_visual), Ok(source_visual)) => {
                update_progress(0.74, "鲁棒视觉证据提取完成。")?;
                visual_features = Some((complete_visual, source_visual));
            }
            (Err(error), _) | (_, Err(error)) => {
                propagate_alignment_process_cleanup(&error)?;
                if is_media_identity_guard_error(&error) || error == AUDIO_ALIGNMENT_CANCELLED {
                    return Err(error);
                }
                update_progress(0.74, "视觉证据不可用，继续音频时间映射。")?;
                visual_error = Some(error);
            }
        }
    } else {
        update_progress(0.74, "未启用视觉辅助，继续音频时间映射。")?;
    }
    check_cancelled(cancel_flag)?;
    update_progress(0.78, "正在生成稀疏音频指纹。")?;
    check_cancelled(cancel_flag)?;
    update_progress(0.84, "正在建立候选观测。")?;
    check_cancelled(cancel_flag)?;
    update_progress(0.89, "正在拟合时间映射。")?;
    check_cancelled(cancel_flag)?;
    let mut proposal = create_audio_alignment_proposal(
        &complete_features.frames,
        &source_features.frames,
        options,
    )?;
    update_progress(0.94, "正在精修候选版本差异。")?;
    check_cancelled(cancel_flag)?;
    apply_visual_evidence_to_proposal(&mut proposal, visual_features.as_ref(), visual_error);
    proposal.diagnostics.push(format!(
        "音频特征缓存：完整版{}，当前视频{}。",
        if complete_features.cache_hit {
            "命中"
        } else {
            "新提取"
        },
        if source_features.cache_hit {
            "命中"
        } else {
            "新提取"
        }
    ));
    proposal
        .diagnostics
        .push(format_alignment_audio_input_diagnostic(
            "完整版",
            &complete_audio_input,
        ));
    proposal
        .diagnostics
        .push(format_alignment_audio_input_diagnostic(
            "当前视频",
            &source_audio_input,
        ));
    if let Some((complete_visual, source_visual)) = &visual_features {
        proposal.diagnostics.push(format!(
            "视觉证据缓存：完整版{}，当前视频{}。",
            if complete_visual.cache_hit {
                "命中"
            } else {
                "新提取"
            },
            if source_visual.cache_hit {
                "命中"
            } else {
                "新提取"
            }
        ));
    }
    benchmark_stage("reporting", "生成对齐复核数据");
    update_progress(0.97, "正在生成对齐复核数据。")?;
    Ok(proposal)
}

fn v2_effective_alternative_margin(
    forced_global_margin: Option<f64>,
    pair_margin: f64,
    intrinsic_margin: f64,
) -> f64 {
    forced_global_margin
        .map(|global_margin| global_margin.min(intrinsic_margin))
        .unwrap_or_else(|| pair_margin.min(intrinsic_margin))
}

fn align_audio_files_v2_with_progress<F>(
    request: &AudioAlignmentRequest,
    options: &AudioAlignmentOptions,
    update_progress: &mut F,
    cancel_flag: Option<&AtomicBool>,
    prepared: Option<PreparedV2PairEvidence>,
) -> Result<AudioAlignmentProposal, String>
where
    F: FnMut(f64, &str) -> Result<(), String>,
{
    benchmark_stage("validating", "探测候选音轨与展示时间线");
    update_progress(0.08, "Alignment V2 正在探测展示时间线和候选音轨。")?;
    let target_inputs = if let Some(prepared) = prepared.as_ref() {
        prepared.target.inputs.clone()
    } else {
        match probe_alignment_audio_candidates(
            &request.complete_path,
            "目标原片",
            request.complete_audio_stream_index,
            options,
            cancel_flag,
        ) {
            Ok(inputs) => inputs,
            Err(error) => {
                update_progress(0.10, "目标音频不可比较，正在尝试独立视觉定位。")?;
                return try_v2_visual_fallback(
                    request,
                    options,
                    &format!("目标音频探测未通过：{}", truncate_visual_note(&error)),
                    vec![error],
                    cancel_flag,
                );
            }
        }
    };
    let source_inputs = if let Some(prepared) = prepared.as_ref() {
        prepared.source.inputs.clone()
    } else {
        match probe_alignment_audio_candidates(
            &request.source_path,
            "B 站参考",
            request.source_audio_stream_index,
            options,
            cancel_flag,
        ) {
            Ok(inputs) => inputs,
            Err(error) => {
                update_progress(0.10, "参考音频不可比较，正在尝试独立视觉定位。")?;
                return try_v2_visual_fallback(
                    request,
                    options,
                    &format!("参考音频探测未通过：{}", truncate_visual_note(&error)),
                    vec![error],
                    cancel_flag,
                );
            }
        }
    };
    if source_inputs.is_empty() || target_inputs.is_empty() {
        let reason = "没有可自动使用的非 commentary 音轨；如确需评论音轨，请显式选择全局流索引。";
        update_progress(0.70, "音频不可比，正在尝试独立视觉定位。")?;
        return try_v2_visual_fallback(
            request,
            options,
            reason,
            vec!["自动选轨只评估非 commentary 音轨。".to_string()],
            cancel_flag,
        );
    }
    // The request-local capability snapshot was resolved when options were created. Candidate
    // tracks and both media share it throughout cache lookup and extraction.
    let spectral_backend_request = if prepared.is_none() {
        Some(&options.spectral_backend_request)
    } else {
        None
    };
    let initial_retained_artifact_bytes = v2_prepared_retained_artifact_baseline(prepared.as_ref());
    // Ordinary source/target extraction is one transactional admission boundary. Plan both media
    // before the first FFmpeg decode, retain every prefetched hit Arc, and charge the target from
    // the source plan's conservative projected prefix.
    let ordinary_cache_plans = if let Some(backend_request) = spectral_backend_request {
        Some(plan_v2_ordinary_candidate_sets_cache_aware(
            &request.source_path,
            &request.complete_path,
            options,
            &source_inputs,
            &target_inputs,
            &backend_request.planned_backend_id,
            initial_retained_artifact_bytes,
        )?)
    } else {
        None
    };
    let (source_cache_plan, target_cache_plan) = match ordinary_cache_plans {
        Some(plans) => (Some(plans.source), Some(plans.target)),
        None => (None, None),
    };
    check_cancelled(cancel_flag)?;

    benchmark_stage("extracting-source", "提取参考音轨 landmark");
    update_progress(0.12, "正在为 B 站参考候选音轨提取 16 kHz landmark。")?;
    let mut extraction_notes = prepared
        .as_ref()
        .map(|prepared| {
            prepared
                .source
                .extraction_notes
                .iter()
                .chain(&prepared.target.extraction_notes)
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let mut retained_artifact_bytes = initial_retained_artifact_bytes;
    let source_landmarks = if let Some(prepared) = prepared.as_ref() {
        prepared.source.landmarks.clone()
    } else {
        let cache_plan = source_cache_plan.ok_or_else(|| {
            "blocked:resource-limit：普通 V2 source 缺少联合预建缓存计划。".to_string()
        })?;
        extract_v2_landmark_candidates(
            &request.source_path,
            "B 站参考",
            options,
            &source_inputs,
            cancel_flag,
            Some(cache_plan),
            None,
            &mut V2CandidateExtractionState {
                notes: &mut extraction_notes,
                retained_artifact_bytes: &mut retained_artifact_bytes,
                spectral_backend_request: spectral_backend_request
                    .expect("ordinary V2 preparation must resolve a spectral backend"),
            },
        )?
    };
    benchmark_stage("extracting-complete", "提取目标原片 landmark");
    update_progress(0.40, "正在为目标原片候选音轨提取 16 kHz landmark。")?;
    let target_landmarks = if let Some(prepared) = prepared.as_ref() {
        extraction_notes.push(
            "本 pair 复用批次级 distinct-media timeline、PTS 与 coarse artifact，并只对项目级 Top-K shortlist 选中的 affine 候选执行 fine。"
                .to_string(),
        );
        prepared.target.landmarks.clone()
    } else {
        let cache_plan = target_cache_plan.ok_or_else(|| {
            "blocked:resource-limit：普通 V2 target 缺少联合预建缓存计划。".to_string()
        })?;
        extract_v2_landmark_candidates(
            &request.complete_path,
            "目标原片",
            options,
            &target_inputs,
            cancel_flag,
            Some(cache_plan),
            None,
            &mut V2CandidateExtractionState {
                notes: &mut extraction_notes,
                retained_artifact_bytes: &mut retained_artifact_bytes,
                spectral_backend_request: spectral_backend_request
                    .expect("ordinary V2 preparation must resolve a spectral backend"),
            },
        )?
    };
    check_cancelled(cancel_flag)?;
    if source_landmarks.is_empty() || target_landmarks.is_empty() {
        let reason = "候选音轨未产生可用 landmark，不能据此断言存在或不存在内容段。";
        update_progress(0.70, "音频 landmark 不足，正在尝试独立视觉定位。")?;
        return try_v2_visual_fallback(request, options, reason, extraction_notes, cancel_flag);
    }

    benchmark_stage("matching", "比较音轨组合与 Top-K 仿射假设");
    update_progress(0.78, "正在比较合理音轨组合的 Top-K 仿射假设。")?;
    let affine_config = v2_affine_match_config();
    let (pair_candidates, alternatives, forced_global_margin) =
        if let Some(prepared) = prepared.as_ref() {
            extraction_notes.push(prepared.selected_coarse.global_diagnostic.clone());
            (
                vec![prepared.selected_coarse.candidate.clone()],
                prepared.selected_coarse.alternatives.clone(),
                Some(prepared.selected_coarse.global_margin),
            )
        } else {
            let coarse = collect_v2_pair_coarse_candidates(
                &source_inputs,
                &target_inputs,
                &source_landmarks,
                &target_landmarks,
                V2CoarseCandidateCollectionContext {
                    toolchain_cache_identity: audio_alignment_toolchain_cache_identity(options)?,
                    has_explicit_selection: request.source_audio_stream_index.is_some()
                        || request.complete_audio_stream_index.is_some(),
                    coarse_resident_baseline_bytes: retained_artifact_bytes,
                    cancel_flag,
                },
            )?;
            extraction_notes.extend(coarse.diagnostics);
            (coarse.candidates, coarse.alternatives, None)
        };
    let Some(mut best_pair) = pair_candidates.first().cloned() else {
        let reason = "合理的非 commentary 音轨组合之间没有共同音频证据。";
        extraction_notes.push(format!(
            "音频组合保留了 {} 个未形成主定位的候选分数。",
            alternatives.len()
        ));
        update_progress(0.82, "没有共同音频定位，正在尝试独立视觉定位。")?;
        return try_v2_visual_fallback(request, options, reason, extraction_notes, cancel_flag);
    };
    let pair_margin = pair_candidates
        .get(1)
        .map(|second| {
            ((best_pair.score - second.score) / best_pair.score.max(0.001)).clamp(0.0, 1.0)
        })
        .unwrap_or(1.0);
    drop(pair_candidates);
    if prepared.is_none() {
        retained_artifact_bytes = ensure_v2_active_artifact_budget(
            retained_artifact_bytes,
            v2_coarse_candidate_reserved_bytes(1_usize.saturating_add(alternatives.len()))?,
        )?;
    }
    let top1_top2_margin = v2_effective_alternative_margin(
        forced_global_margin,
        pair_margin,
        best_pair.intrinsic_margin,
    );
    // Batch selection cannot weaken the pair-local ambiguity gate. In particular, a 1x1 batch
    // must have exactly the same intrinsic-margin blocked semantics as ordinary single-pair V2.
    let minimum_alternative_margin = if prepared
        .as_ref()
        .is_some_and(|prepared| prepared.fine_frontier_evaluation)
    {
        0.0
    } else {
        ALIGNMENT_V2_MIN_TRACK_MARGIN
    };
    let selected_track_reason = format!(
        "landmark 内容评分选择 B 站参考音轨 #{} 与目标原片音轨 #{}；{} margin {:.3}。",
        best_pair.source_input.stream.stream_index,
        best_pair.target_input.stream.stream_index,
        if forced_global_margin.is_some() {
            "项目级 Top-K shortlist"
        } else {
            "Top1/Top2"
        },
        top1_top2_margin
    );
    extraction_notes.push(selected_track_reason.clone());
    extraction_notes.push(format_v2_decode_timeline_diagnostic(
        "B 站参考",
        &best_pair.source_input,
    ));
    extraction_notes.push(format_v2_decode_timeline_diagnostic(
        "目标原片",
        &best_pair.target_input,
    ));
    if top1_top2_margin < minimum_alternative_margin {
        extraction_notes.push(
            "Top1/Top2 候选过于接近；继续计算显式 spans 供复核，但最终质量将保持 blocked。"
                .to_string(),
        );
    }
    let source_landmark_artifact = source_landmarks
        .get(&best_pair.source_input.stream.stream_index)
        .ok_or_else(|| {
            "blocked:artifact-missing：所选 B 站参考音轨的粗定位制品已丢失。".to_string()
        })?;
    let target_landmark_artifact = target_landmarks
        .get(&best_pair.target_input.stream.stream_index)
        .ok_or_else(|| {
            "blocked:artifact-missing：所选目标原片音轨的粗定位制品已丢失。".to_string()
        })?;
    best_pair = materialize_v2_candidate_hypothesis(
        best_pair,
        source_landmark_artifact,
        target_landmark_artifact,
        &affine_config,
        retained_artifact_bytes,
        cancel_flag,
    )?;
    retained_artifact_bytes = ensure_v2_active_artifact_budget(
        retained_artifact_bytes,
        v2_materialized_anchor_resident_bytes(&best_pair.hypothesis)?,
    )?;
    if best_pair.temporal_coverage < ALIGNMENT_V2_MIN_TEMPORAL_COVERAGE
        || best_pair.hypothesis.inlier_count < affine_config.min_inliers
    {
        return Ok(create_blocked_v2_affine_proposal(
            "landmark 支持范围过短，不能把低分局部巧合解释为完整内容映射。",
            &best_pair,
            top1_top2_margin,
            alternatives,
            extraction_notes,
        ));
    }
    let fine_decode_plan = match plan_v2_selected_fine_decode(
        &best_pair,
        source_landmark_artifact,
        target_landmark_artifact,
    ) {
        Ok(plan) => plan,
        Err(error) => {
            extraction_notes.push(error);
            return Ok(create_blocked_v2_affine_proposal(
                "粗定位候选无法形成完整、有界的 affine 精解码窗口。",
                &best_pair,
                top1_top2_margin,
                alternatives,
                extraction_notes,
            ));
        }
    };
    let mut fine_active_artifact_bytes = retained_artifact_bytes;
    if let Some(plan) = fine_decode_plan {
        for (input, window) in [
            (&best_pair.source_input, plan.windows.source),
            (&best_pair.target_input, plan.windows.target),
        ] {
            if should_stream_v2_coarse_only(input) {
                let window_bytes = match v2_fine_window_artifact_upper_bound(window) {
                    Ok(bytes) => bytes,
                    Err(error) => {
                        extraction_notes.push(error);
                        return Ok(create_blocked_v2_affine_proposal(
                            "所选 affine 精解码窗口无法建立可信的活动内存上界。",
                            &best_pair,
                            top1_top2_margin,
                            alternatives,
                            extraction_notes,
                        ));
                    }
                };
                fine_active_artifact_bytes = match ensure_v2_active_artifact_budget(
                    fine_active_artifact_bytes,
                    window_bytes,
                ) {
                    Ok(bytes) => bytes,
                    Err(error) => {
                        extraction_notes.push(error);
                        return Ok(create_blocked_v2_affine_proposal(
                            "所选 affine 精解码窗口超过单次活动内存预算。",
                            &best_pair,
                            top1_top2_margin,
                            alternatives,
                            extraction_notes,
                        ));
                    }
                };
            }
        }
        extraction_notes.push(format!(
            "所选 affine 候选采用绝对 presentation 窗口精解码：参考 [{}，{}] ms，目标 [{}，{}] ms，自适应 guard {} ms；窗口包含完整目标逆投影与全部 coarse source support；本次活动制品上界 {} MiB。",
            plan.windows.source.start_ms,
            plan.windows.source.end_ms,
            plan.windows.target.start_ms,
            plan.windows.target.end_ms,
            plan.adaptive_guard_ms,
            fine_active_artifact_bytes.div_ceil(1024 * 1024)
        ));
    }
    let cuda_fine_transient_bytes = match v2_selected_fine_cuda_transient_upper_bound(
        source_landmark_artifact,
        target_landmark_artifact,
    ) {
        Ok(bytes) => bytes,
        Err(error) => {
            extraction_notes.push(error);
            return Ok(create_blocked_v2_affine_proposal(
                "所选候选无法建立连续、可信的 fine 声谱后端与显存上界。",
                &best_pair,
                top1_top2_margin,
                alternatives,
                extraction_notes,
            ));
        }
    };
    if cuda_fine_transient_bytes > 0 {
        let fine_extraction_peak_bytes = match ensure_v2_active_artifact_budget(
            fine_active_artifact_bytes,
            cuda_fine_transient_bytes,
        ) {
            Ok(bytes) => bytes,
            Err(error) => {
                extraction_notes.push(error);
                return Ok(create_blocked_v2_affine_proposal(
                    "所选候选的 CUDA fine 主机批次与 cuFFT 显存工作区超过单任务合计预算。",
                    &best_pair,
                    top1_top2_margin,
                    alternatives,
                    extraction_notes,
                ));
            }
        };
        extraction_notes.push(format!(
            "选中窗口 fine 声谱锁定 CUDA/cuFFT；4096 帧有界批次的 pageable host、device input/output 与最坏 cuFFT workspace 合计按 {} MiB 计入 1 GiB 活跃预算，阶段峰值 {} MiB。",
            cuda_fine_transient_bytes.div_ceil(1024 * 1024),
            fine_extraction_peak_bytes.div_ceil(1024 * 1024)
        ));
    }

    benchmark_stage("extracting-source", "解码参考音轨细粒度特征");
    update_progress(
        0.84,
        "已选择音轨，正在有界解码 PCM 并生成绝对时间轴 50 ms 细特征。",
    )?;
    let source_audio = match decode_v2_audio_for_selected_window(
        &request.source_path,
        "B 站参考",
        options,
        &best_pair.source_input,
        source_landmark_artifact,
        fine_decode_plan.map(|plan| plan.windows.source),
        cancel_flag,
    ) {
        Ok(audio) => audio,
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            if is_media_identity_guard_error(&error) || error == AUDIO_ALIGNMENT_CANCELLED {
                return Err(error);
            }
            extraction_notes.push(error);
            return Ok(create_blocked_v2_affine_proposal(
                "所选 B 站参考音轨无法进入细粒度对齐。",
                &best_pair,
                top1_top2_margin,
                alternatives,
                extraction_notes,
            ));
        }
    };
    benchmark_stage("extracting-complete", "解码目标原片细粒度特征");
    let target_audio = match decode_v2_audio_for_selected_window(
        &request.complete_path,
        "目标原片",
        options,
        &best_pair.target_input,
        target_landmark_artifact,
        fine_decode_plan.map(|plan| plan.windows.target),
        cancel_flag,
    ) {
        Ok(audio) => audio,
        Err(error) => {
            propagate_alignment_process_cleanup(&error)?;
            if is_media_identity_guard_error(&error) || error == AUDIO_ALIGNMENT_CANCELLED {
                return Err(error);
            }
            extraction_notes.push(error);
            return Ok(create_blocked_v2_affine_proposal(
                "所选目标原片音轨无法进入细粒度对齐。",
                &best_pair,
                top1_top2_margin,
                alternatives,
                extraction_notes,
            ));
        }
    };
    for (label, coarse_backend, fine_backend) in [
        (
            "B 站参考",
            &source_landmark_artifact.spectral_backend,
            &source_audio.fine_spectral_backend,
        ),
        (
            "目标原片",
            &target_landmark_artifact.spectral_backend,
            &target_audio.fine_spectral_backend,
        ),
    ] {
        extraction_notes.push(format!(
            "{label} fine 声谱后端 {}（由 coarse 后端 {} 连续锁定；{}）。",
            fine_backend.backend_id, coarse_backend.backend_id, fine_backend.backend_detail
        ));
        if let Some(reason) = &fine_backend.fallback_reason {
            extraction_notes.push(format!("{label} fine 声谱后端说明：{reason}"));
        }
    }
    if let Some(capture) = prepared
        .as_ref()
        .and_then(|prepared| prepared.fine_execution_capture.as_ref())
    {
        let source_decoded_sample_count = u64::try_from(source_audio.pcm.len())
            .map_err(|_| "source fine decoded sample count 无法表示。".to_string())?;
        let target_decoded_sample_count = u64::try_from(target_audio.pcm.len())
            .map_err(|_| "target fine decoded sample count 无法表示。".to_string())?;
        let mut capture = capture
            .lock()
            .map_err(|_| "fine execution runtime capture 锁已损坏。".to_string())?;
        *capture = Some(V2FineExecutionRuntimeCapture {
            source_fine_backend: source_audio.fine_spectral_backend.clone(),
            target_fine_backend: target_audio.fine_spectral_backend.clone(),
            source_presentation_offset_ms: source_audio.presentation_offset_ms,
            target_presentation_offset_ms: target_audio.presentation_offset_ms,
            source_decoded_sample_count,
            target_decoded_sample_count,
            decode_plan: fine_decode_plan,
        });
    }

    benchmark_stage("fitting", "执行分块 edit-aware DP");
    update_progress(0.89, "正在沿最佳 affine 走廊执行分块 edit-aware DP。")?;
    let mut chunk_alignment = match align_v2_feature_chunks(
        &source_audio.fine_features,
        &target_audio.fine_features,
        &best_pair.hypothesis,
        options,
        fine_active_artifact_bytes,
        cancel_flag,
    ) {
        Ok(result) => result,
        Err(error) => {
            // The fine algorithm reports cancellation through the shared token. Preserve the
            // batch lifecycle terminal state instead of disguising it as a reviewable proposal.
            check_cancelled(cancel_flag)?;
            extraction_notes.push(error);
            return Ok(create_blocked_v2_affine_proposal(
                "细粒度 DP 未能形成完整、单调的双轴路径；已安全阻断旧引擎回退。",
                &best_pair,
                top1_top2_margin,
                alternatives,
                extraction_notes,
            ));
        }
    };
    let preserved_ambiguous_span_count = chunk_alignment
        .spans
        .iter()
        .filter(|span| span.kind == AudioTimeMapSpanKind::Ambiguous)
        .count();
    if preserved_ambiguous_span_count > 0 {
        extraction_notes.push(format!(
            "细粒度 DP 将 {preserved_ambiguous_span_count} 个缺少连续恢复锚点或存在双轴跳进的区间保留为 ambiguous；可信前后路径继续保留，但该候选必须人工复核且禁止自动确认。"
        ));
    }
    extraction_notes.extend(chunk_alignment.path_checkpoints.iter().cloned());

    benchmark_stage("refining", "精修可识别版本差异边界");
    update_progress(0.94, "正在用局部相关峰精修可识别边界。")?;
    let boundary_summary = refine_v2_span_boundaries(
        &mut chunk_alignment.spans,
        &source_audio.pcm,
        &target_audio.pcm,
        source_audio.presentation_offset_ms,
        target_audio.presentation_offset_ms,
        cancel_flag,
    );
    check_cancelled(cancel_flag)?;
    benchmark_stage("reporting", "生成 Alignment V2 时间图与证据");
    update_progress(0.97, "正在生成 Alignment V2 时间图和复核证据。")?;
    extraction_notes.push(format!(
        "细对齐按 {} ms 块执行：coarse/双侧锚点证明块使用 ±{} ms 格，未锚定 edit recovery 使用 {} ms lookahead，解码窗口 guard 为 ±{} ms；250 ms 上下文可信成本阈值 {}；边界相关尝试 {} 次，可靠精修 {} 次，歧义 {} 次。",
        ALIGNMENT_V2_DP_CHUNK_MS,
        ALIGNMENT_V2_COARSE_GUIDED_DP_BAND_RADIUS_MS,
        ALIGNMENT_V2_RECURSIVE_LOOKAHEAD_MS,
        ALIGNMENT_V2_DP_BAND_RADIUS_MS,
        ALIGNMENT_V2_RECOVERY_CONTEXT_COST,
        boundary_summary.attempted_count,
        boundary_summary.refined_count,
        boundary_summary.ambiguous_count
    ));
    extraction_notes.extend(boundary_summary.evidence_notes.iter().cloned());
    let mut proposal = create_v2_alignment_proposal(
        chunk_alignment,
        boundary_summary,
        best_pair,
        top1_top2_margin,
        minimum_alternative_margin,
        selected_track_reason,
        alternatives,
        extraction_notes,
    );
    if options.enable_visual_evidence {
        benchmark_stage("extracting-visual", "独立视觉校验时间图");
        update_progress(0.98, "正在用独立视觉采样校验音频时间图。")?;
        apply_v2_visual_validation(request, options, &mut proposal, cancel_flag)?;
        benchmark_stage("reporting", "汇总音频与视觉复核证据");
    }
    Ok(proposal)
}

fn v2_prepared_retained_artifact_baseline(prepared: Option<&PreparedV2PairEvidence>) -> usize {
    prepared
        .map(|prepared| prepared.batch_retained_artifact_bytes)
        .unwrap_or(0)
}

#[derive(Debug)]
struct V2ApproximateFingerprintCandidates {
    candidates: Vec<V2TrackPairCandidate>,
    diagnostic: String,
}

fn create_v2_approximate_fingerprint_candidates(
    source_input: &AlignmentAudioInput,
    target_input: &AlignmentAudioInput,
    source_artifact: &CachedV2Landmarks,
    target_artifact: &CachedV2Landmarks,
    toolchain_cache_identity: &str,
    affine_config: &AffineMatchConfig,
    cancel_flag: Option<&AtomicBool>,
) -> Result<V2ApproximateFingerprintCandidates, String> {
    let result = if !source_artifact.coarse_fingerprint.is_empty()
        && !target_artifact.coarse_fingerprint.is_empty()
    {
        match_spectral_fingerprints_approximately(
            &source_artifact.coarse_fingerprint,
            &target_artifact.coarse_fingerprint,
            (
                target_artifact.presentation_bounds.start_ms,
                target_artifact.presentation_bounds.end_ms,
            ),
            &ApproximateFingerprintConfig::default(),
            cancel_flag,
        )
    } else {
        // Compatibility guard for in-memory test fixtures. Release v18 persistent artifacts
        // always contain full coarse spectral frames.
        match_landmark_timelines_approximately(
            &source_artifact.landmarks,
            &target_artifact.landmarks,
            (
                source_artifact.presentation_bounds.start_ms,
                source_artifact.presentation_bounds.end_ms,
            ),
            (
                target_artifact.presentation_bounds.start_ms,
                target_artifact.presentation_bounds.end_ms,
            ),
            &ApproximateFingerprintConfig::default(),
            cancel_flag,
        )
    }
    .map_err(|error| format!("近似声谱时间指纹失败：{error}"))?;
    let diagnostic = format!(
        "近似声谱时间指纹窗口统计：queryBlocks={}、scoreAccepted={}、uniqueTraining={}、best/medianScore={:?}/{:?}、best/medianMargin={:?}/{:?}、trainingOffsetsMs={:?}。",
        result.query_block_count,
        result.score_accepted_block_count,
        result.unique_training_block_count,
        result.best_block_score,
        result.median_block_score,
        result.best_block_margin,
        result.median_block_margin,
        result.unique_training_offsets_ms
    );
    let hypotheses = result.hypotheses;
    let alternative_margin = hypotheses
        .first()
        .zip(hypotheses.get(1))
        .map(|(best, second)| ((best.score - second.score) / best.score.max(0.001)).clamp(0.0, 1.0))
        .unwrap_or(1.0);
    let repeated_content_only =
        hypotheses
            .first()
            .zip(hypotheses.get(1))
            .is_some_and(|(best, second)| {
                alternative_margin < ALIGNMENT_V2_MIN_TRACK_MARGIN
                    && best.offset_ms.abs_diff(second.offset_ms) >= 10_000
            });
    let candidates = hypotheses
        .into_iter()
        .map(|approximate| {
            let hypothesis =
                v2_affine_hypothesis_from_approximate_fingerprint(&approximate, affine_config);
            let temporal_coverage = approximate.target_coverage;
            let ordinary_score = score_v2_track_pair(
                &hypothesis,
                temporal_coverage,
                affine_config,
                source_input,
                target_input,
            );
            let score = (ordinary_score * 0.70 + approximate.score * 0.30).clamp(0.0, 1.0);
            let candidate = V2TrackPairCandidate {
                source_input: source_input.clone(),
                target_input: target_input.clone(),
                // The approximate fingerprint already owns complete training and held-out
                // evidence. It must not be rematerialized through exact-hash observations.
                coarse_hypothesis: None,
                hypothesis,
                score,
                temporal_coverage,
                intrinsic_margin: alternative_margin,
                repeated_content_only,
                observation_count: approximate
                    .training_anchors
                    .len()
                    .saturating_add(approximate.held_out_anchors.len()),
                source_landmark_count: source_artifact.landmarks.len(),
                target_landmark_count: target_artifact.landmarks.len(),
                source_spectral_backend_id: source_artifact.spectral_backend.backend_id.clone(),
                target_spectral_backend_id: target_artifact.spectral_backend.backend_id.clone(),
                toolchain_cache_identity: toolchain_cache_identity.to_string(),
                global_source_interval: source_artifact.presentation_bounds,
                global_target_interval: target_artifact.presentation_bounds,
                fine_working_set_bytes: 0,
            };
            bind_v2_candidate_global_intervals(candidate, source_artifact, target_artifact)
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(V2ApproximateFingerprintCandidates {
        candidates,
        diagnostic,
    })
}

fn append_v2_approximate_fingerprint_candidates(
    source_input: &AlignmentAudioInput,
    target_input: &AlignmentAudioInput,
    approximate_result: V2ApproximateFingerprintCandidates,
    candidates: &mut Vec<V2TrackPairCandidate>,
    alternatives: &mut Vec<AudioAlternativeTrackScoreDto>,
    diagnostics: &mut Vec<String>,
) -> Result<usize, String> {
    diagnostics.push(format!(
        "音轨 #{} → #{}：{}",
        source_input.stream.stream_index,
        target_input.stream.stream_index,
        approximate_result.diagnostic
    ));
    let approximate_candidates = approximate_result.candidates;
    if approximate_candidates.is_empty() {
        diagnostics.push(format!(
            "音轨 #{} → #{} 的近似声谱时间指纹没有形成满足分布、唯一性与内点门槛的候选。",
            source_input.stream.stream_index, target_input.stream.stream_index
        ));
        return Ok(0);
    }
    let projected_candidate_count = candidates
        .len()
        .checked_add(approximate_candidates.len())
        .ok_or_else(|| {
            "blocked:resource-limit：完整 coarse supplement candidate 数量溢出。".to_string()
        })?;
    if projected_candidate_count > ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_CANDIDATES {
        return Err(format!(
            "blocked:resource-limit：完整 coarse candidate universe 需要 {} 个 candidate，超过硬上限 {}。",
            projected_candidate_count, ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_CANDIDATES
        ));
    }
    diagnostics.push(format!(
        "音轨 #{} → #{} 的近似声谱时间指纹补充 {} 个候选：{}。",
        source_input.stream.stream_index,
        target_input.stream.stream_index,
        approximate_candidates.len(),
        approximate_candidates
            .iter()
            .map(|candidate| format!(
                "offset={:+},anchors={}/{},coverage={:.3},p95={}ms,score={:.3}",
                candidate.hypothesis.offset_ms,
                candidate.hypothesis.training_anchors.len(),
                candidate.hypothesis.held_out_anchors.len(),
                candidate.temporal_coverage,
                candidate.hypothesis.p95_residual_ms,
                candidate.score
            ))
            .collect::<Vec<_>>()
            .join("；")
    ));
    alternatives.extend(approximate_candidates.iter().map(|candidate| {
        v2_alternative_hypothesis_score(
            &candidate.source_input,
            &candidate.target_input,
            &candidate.hypothesis,
            candidate.score,
        )
    }));
    let appended_count = approximate_candidates.len();
    candidates.extend(approximate_candidates);
    Ok(appended_count)
}

fn v2_affine_hypothesis_from_approximate_fingerprint(
    approximate: &ApproximateCoarseHypothesis,
    affine_config: &AffineMatchConfig,
) -> AffineHypothesis {
    let training_anchors = approximate
        .training_anchors
        .iter()
        .map(|anchor| AffineAnchorEvidence {
            source_time_ms: anchor.source_time_ms,
            target_time_ms: anchor.target_time_ms,
            residual_ms: anchor.residual_ms,
        })
        .collect::<Vec<_>>();
    let held_out_anchors = approximate
        .held_out_anchors
        .iter()
        .map(|anchor| AffineAnchorEvidence {
            source_time_ms: anchor.source_time_ms,
            target_time_ms: anchor.target_time_ms,
            residual_ms: anchor.residual_ms,
        })
        .collect::<Vec<_>>();
    let held_out_within_tolerance_count = approximate
        .held_out_anchors
        .iter()
        .filter(|anchor| {
            anchor.residual_ms.unsigned_abs() <= affine_config.residual_tolerance_ms as u64
        })
        .count();
    AffineHypothesis {
        scale: approximate.scale,
        offset_ms: approximate.offset_ms,
        inlier_count: training_anchors.len(),
        unique_source_count: training_anchors.len(),
        unique_source_coverage: approximate.target_coverage,
        unique_target_count: training_anchors.len(),
        unique_target_coverage: approximate.target_coverage,
        source_start_ms: approximate.source_start_ms,
        source_end_ms: approximate.source_end_ms,
        p50_residual_ms: approximate.p50_residual_ms,
        p95_residual_ms: approximate.p95_residual_ms,
        max_residual_ms: approximate.max_residual_ms,
        training_anchors,
        held_out_anchors,
        held_out_within_tolerance_count,
    }
}

fn collect_v2_pair_coarse_candidates(
    source_inputs: &[AlignmentAudioInput],
    target_inputs: &[AlignmentAudioInput],
    source_landmarks: &HashMap<u32, CachedV2Landmarks>,
    target_landmarks: &HashMap<u32, CachedV2Landmarks>,
    context: V2CoarseCandidateCollectionContext<'_>,
) -> Result<V2PairCoarseCandidates, String> {
    let V2CoarseCandidateCollectionContext {
        toolchain_cache_identity,
        has_explicit_selection,
        coarse_resident_baseline_bytes,
        cancel_flag,
    } = context;
    let affine_config = v2_affine_match_config();
    let mut candidates = Vec::<V2TrackPairCandidate>::new();
    let mut alternatives = Vec::new();
    let mut diagnostics = Vec::new();
    for source_input in source_inputs {
        for target_input in target_inputs {
            check_cancelled(cancel_flag)?;
            if !has_explicit_selection
                && !is_reasonable_audio_stream_pair(source_input, target_input)
            {
                continue;
            }
            let Some(source_artifact) = source_landmarks.get(&source_input.stream.stream_index)
            else {
                continue;
            };
            let Some(target_artifact) = target_landmarks.get(&target_input.stream.stream_index)
            else {
                continue;
            };
            let current_candidate_bytes = v2_coarse_candidate_reserved_bytes(candidates.len())?;
            let current_active_bytes = ensure_v2_active_artifact_budget(
                coarse_resident_baseline_bytes,
                current_candidate_bytes,
            )?;
            ensure_v2_active_artifact_budget(
                current_active_bytes,
                ALIGNMENT_V2_AFFINE_MATCH_WORKSPACE_BYTES,
            )?;
            let result = match match_landmarks_affine_coarse_universe_with_cancel(
                &source_artifact.landmarks,
                &target_artifact.landmarks,
                &affine_config,
                cancel_flag,
            ) {
                Ok(result) => result,
                Err(error) => {
                    diagnostics.push(format!(
                        "音轨 #{} → #{} landmark 拟合失败：{error}",
                        source_input.stream.stream_index, target_input.stream.stream_index
                    ));
                    continue;
                }
            };
            if result.hypotheses.is_empty() {
                diagnostics.push(format!(
                    "音轨 #{} → #{} 的 exact-landmark 仿射拟合没有候选：sourceLandmarks={}、targetLandmarks={}、exactObservations={}、modelSeeds={}；转入近似声谱时间指纹。",
                    source_input.stream.stream_index,
                    target_input.stream.stream_index,
                    result.source_landmark_count,
                    result.target_landmark_count,
                    result.observation_count,
                    result.seed_count
                ));
                let approximate_result = match create_v2_approximate_fingerprint_candidates(
                    source_input,
                    target_input,
                    source_artifact,
                    target_artifact,
                    toolchain_cache_identity,
                    &affine_config,
                    cancel_flag,
                ) {
                    Ok(result) => result,
                    Err(error) => {
                        diagnostics.push(format!(
                            "音轨 #{} → #{} 的近似声谱时间指纹无法执行：{error}",
                            source_input.stream.stream_index, target_input.stream.stream_index
                        ));
                        continue;
                    }
                };
                append_v2_approximate_fingerprint_candidates(
                    source_input,
                    target_input,
                    approximate_result,
                    &mut candidates,
                    &mut alternatives,
                    &mut diagnostics,
                )?;
                continue;
            }
            let projected_candidate_count = candidates
                .len()
                .checked_add(result.hypotheses.len())
                .ok_or_else(|| {
                "blocked:resource-limit：完整 coarse affine candidate 数量溢出。".to_string()
            })?;
            if projected_candidate_count > ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_CANDIDATES {
                return Err(format!(
                    "blocked:resource-limit：完整 coarse affine universe 需要 {} 个 candidate，超过硬上限 {}；为保留 omitted-candidate 正确性，本次不会静默截断。",
                    projected_candidate_count, ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_CANDIDATES
                ));
            }
            ensure_v2_active_artifact_budget(
                coarse_resident_baseline_bytes,
                v2_coarse_candidate_reserved_bytes(projected_candidate_count)?,
            )?;
            diagnostics.push(format!(
                "音轨 #{} → #{} 完整 coarse affine universe：{} 个 seed、{} 个去重 candidate；预览：{}。",
                source_input.stream.stream_index,
                target_input.stream.stream_index,
                result.seed_count,
                result.hypotheses.len(),
                result
                    .hypotheses
                    .iter()
                    .take(10)
                    .map(|item| format!(
                        "scale={:.6},offset={:+},inliers={},range={}-{}",
                        item.scale,
                        item.offset_ms,
                        item.inlier_count,
                        item.source_start_ms,
                        item.source_end_ms
                    ))
                    .collect::<Vec<_>>()
                    .join("；")
            ));
            let anchor_free_hypotheses = result
                .hypotheses
                .iter()
                .map(CoarseAffineHypothesis::to_anchor_free_affine_hypothesis)
                .collect::<Vec<_>>();
            let repeated_content_only = v2_affine_has_competing_repeated_location(
                &anchor_free_hypotheses,
                result.top1_top2_margin,
            );
            for (coarse_hypothesis, hypothesis) in
                result.hypotheses.iter().zip(&anchor_free_hypotheses)
            {
                let temporal_coverage = affine_temporal_coverage(
                    hypothesis,
                    &target_artifact.landmarks,
                    v2_normalized_pcm_origin_ms(target_input),
                );
                let score = score_v2_track_pair(
                    hypothesis,
                    temporal_coverage,
                    &affine_config,
                    source_input,
                    target_input,
                );
                alternatives.push(v2_alternative_hypothesis_score(
                    source_input,
                    target_input,
                    hypothesis,
                    score,
                ));
                let mut candidate = V2TrackPairCandidate {
                    source_input: source_input.clone(),
                    target_input: target_input.clone(),
                    coarse_hypothesis: Some(coarse_hypothesis.clone()),
                    hypothesis: hypothesis.clone(),
                    score,
                    temporal_coverage,
                    intrinsic_margin: result.top1_top2_margin,
                    repeated_content_only,
                    observation_count: result.observation_count,
                    source_landmark_count: result.source_landmark_count,
                    target_landmark_count: result.target_landmark_count,
                    source_spectral_backend_id: source_artifact.spectral_backend.backend_id.clone(),
                    target_spectral_backend_id: target_artifact.spectral_backend.backend_id.clone(),
                    toolchain_cache_identity: toolchain_cache_identity.to_string(),
                    global_source_interval: source_artifact.presentation_bounds,
                    global_target_interval: target_artifact.presentation_bounds,
                    fine_working_set_bytes: 0,
                };
                candidate = match bind_v2_candidate_global_intervals(
                    candidate,
                    source_artifact,
                    target_artifact,
                ) {
                    Ok(candidate) => candidate,
                    Err(error) => {
                        diagnostics.push(format!(
                            "音轨 #{} → #{} 的 affine candidate scale={:.6},offset={:+} 无法形成有界 fine window，已在项目级 shortlist 前排除：{error}",
                            source_input.stream.stream_index,
                            target_input.stream.stream_index,
                            hypothesis.scale,
                            hypothesis.offset_ms
                        ));
                        continue;
                    }
                };
                candidates.push(candidate);
            }
            match create_v2_approximate_fingerprint_candidates(
                source_input,
                target_input,
                source_artifact,
                target_artifact,
                toolchain_cache_identity,
                &affine_config,
                cancel_flag,
            ) {
                Ok(approximate_result) => {
                    let appended_count = append_v2_approximate_fingerprint_candidates(
                        source_input,
                        target_input,
                        approximate_result,
                        &mut candidates,
                        &mut alternatives,
                        &mut diagnostics,
                    )?;
                    diagnostics.push(format!(
                        "音轨 #{} → #{} 同时保留 exact-landmark 与 {} 个近似声谱候选进入统一 temporal-window grouping；两种证据不再互斥。",
                        source_input.stream.stream_index,
                        target_input.stream.stream_index,
                        appended_count
                    ));
                }
                Err(error) => diagnostics.push(format!(
                    "音轨 #{} → #{} 的近似声谱补充无法执行，已保留完整 exact-landmark universe：{error}",
                    source_input.stream.stream_index, target_input.stream.stream_index
                )),
            }
        }
    }
    candidates.sort_by(compare_v2_track_pair_candidates);
    alternatives.sort_by(|left, right| {
        right
            .score
            .total_cmp(&left.score)
            .then_with(|| right.inlier_count.cmp(&left.inlier_count))
            .then_with(|| left.source_stream_index.cmp(&right.source_stream_index))
            .then_with(|| left.target_stream_index.cmp(&right.target_stream_index))
            .then_with(|| left.offset_ms.cmp(&right.offset_ms))
    });
    alternatives.truncate(10);
    if let Some(best) = candidates.first().cloned() {
        let margin = candidates
            .get(1)
            .map(|second| ((best.score - second.score) / best.score.max(0.001)).clamp(0.0, 1.0))
            .unwrap_or(1.0);
        if let Some(best) = candidates.first_mut() {
            best.intrinsic_margin = margin.min(best.intrinsic_margin);
        }
    }
    // Group only after every candidate field that contributes to the admissible global weight is
    // frozen. The groups keep indices rather than deep candidate clones, so representative order
    // and later fine-frontier identities always refer to this exact executable universe.
    let (temporal_window_groups, temporal_window_group_probe_count) =
        group_v2_pair_coarse_temporal_windows_with_probe_count(&candidates);
    diagnostics.push(format!(
        "pair coarse temporal-window grouping：完整保留 {} 个跨音轨 affine raw candidate，以 bounded intersection-core 归入 {} 个稳定时间候选组，共执行 {} 次 O(1) group probe；raw candidate 仍逐个计入完整证据集，temporal group 作为 pair-level relation alternative 进入 evidence v3 完整 fine frontier，不是展示用 Top-K。",
        candidates.len(),
        temporal_window_groups.len(),
        temporal_window_group_probe_count
    ));
    Ok(V2PairCoarseCandidates {
        candidates,
        temporal_window_groups,
        alternatives,
        diagnostics,
    })
}

fn bind_v2_candidate_global_intervals(
    mut candidate: V2TrackPairCandidate,
    source_artifact: &CachedV2Landmarks,
    target_artifact: &CachedV2Landmarks,
) -> Result<V2TrackPairCandidate, String> {
    // The guarded plan proves this candidate can enter bounded fine. Conflict geometry uses a
    // separate zero-guard content interval: adjacent episodes may share decoder context while
    // their actual candidate content intervals only touch.
    let fine_plan = plan_v2_selected_fine_decode(&candidate, source_artifact, target_artifact)?;
    let mut fine_working_set_bytes = 0_usize;
    if let Some(plan) = fine_plan {
        for (input, window) in [
            (&candidate.source_input, plan.windows.source),
            (&candidate.target_input, plan.windows.target),
        ] {
            if should_stream_v2_coarse_only(input) {
                fine_working_set_bytes = fine_working_set_bytes
                    .checked_add(v2_fine_window_artifact_upper_bound(window)?)
                    .ok_or_else(|| {
                        "blocked:resource-limit：candidate fine working-set 上界溢出。".to_string()
                    })?;
            }
        }
    }
    let maximum_fine_frames = usize::try_from(
        u128::from(ALIGNMENT_V2_MAX_DURATION_MS).div_ceil(u128::from(ALIGNMENT_V2_FINE_HOP_MS)),
    )
    .map_err(|_| "blocked:resource-limit：candidate DP 帧数上界无法表示。".to_string())?;
    let dp_workspace_bytes = v2_dp_workspace_upper_bound(
        ALIGNMENT_V2_MAX_DP_CELLS,
        maximum_fine_frames,
        maximum_fine_frames,
    )?;
    fine_working_set_bytes = fine_working_set_bytes
        .checked_add(dp_workspace_bytes)
        .ok_or_else(|| "blocked:resource-limit：candidate DP workspace 上界溢出。".to_string())?;
    let content_intervals = derive_v2_selected_candidate_content_intervals(
        &candidate,
        source_artifact,
        target_artifact,
    )?;
    candidate.global_source_interval = content_intervals.source;
    candidate.global_target_interval = content_intervals.target;
    candidate.fine_working_set_bytes = fine_working_set_bytes;
    Ok(candidate)
}

fn materialize_v2_candidate_hypothesis(
    mut candidate: V2TrackPairCandidate,
    source_artifact: &CachedV2Landmarks,
    target_artifact: &CachedV2Landmarks,
    affine_config: &AffineMatchConfig,
    active_artifact_bytes: usize,
    cancel_flag: Option<&AtomicBool>,
) -> Result<V2TrackPairCandidate, String> {
    let Some(coarse_hypothesis) = candidate.coarse_hypothesis.as_ref() else {
        // Synthetic tests and legacy in-memory callers may already own full evidence.
        return Ok(candidate);
    };
    ensure_v2_active_artifact_budget(
        active_artifact_bytes,
        ALIGNMENT_V2_AFFINE_MATCH_WORKSPACE_BYTES,
    )?;
    candidate.hypothesis = materialize_affine_hypothesis_with_cancel(
        &source_artifact.landmarks,
        &target_artifact.landmarks,
        affine_config,
        coarse_hypothesis,
        cancel_flag,
    )
    .map_err(|error| {
        format!(
            "blocked:coarse-evidence-materialization：所选 affine candidate 无法重建完整 anchor 证据：{error}"
        )
    })?;
    Ok(candidate)
}

fn v2_affine_match_config() -> AffineMatchConfig {
    AffineMatchConfig {
        residual_tolerance_ms: 140,
        min_inliers: 6,
        top_k: 5,
        ..AffineMatchConfig::default()
    }
}

fn compare_v2_track_pair_candidates(
    left: &V2TrackPairCandidate,
    right: &V2TrackPairCandidate,
) -> std::cmp::Ordering {
    right
        .score
        .total_cmp(&left.score)
        .then_with(|| {
            right
                .hypothesis
                .inlier_count
                .cmp(&left.hypothesis.inlier_count)
        })
        .then_with(|| {
            left.source_input
                .stream
                .stream_index
                .cmp(&right.source_input.stream.stream_index)
        })
        .then_with(|| {
            left.target_input
                .stream
                .stream_index
                .cmp(&right.target_input.stream.stream_index)
        })
        .then_with(|| {
            left.hypothesis
                .source_start_ms
                .cmp(&right.hypothesis.source_start_ms)
        })
        .then_with(|| left.hypothesis.offset_ms.cmp(&right.hypothesis.offset_ms))
        .then_with(|| {
            left.global_source_interval
                .start_ms
                .cmp(&right.global_source_interval.start_ms)
        })
        .then_with(|| {
            left.global_source_interval
                .end_ms
                .cmp(&right.global_source_interval.end_ms)
        })
        .then_with(|| {
            left.global_target_interval
                .start_ms
                .cmp(&right.global_target_interval.start_ms)
        })
        .then_with(|| {
            left.global_target_interval
                .end_ms
                .cmp(&right.global_target_interval.end_ms)
        })
        .then_with(|| {
            left.hypothesis
                .source_end_ms
                .cmp(&right.hypothesis.source_end_ms)
        })
        .then_with(|| left.hypothesis.scale.total_cmp(&right.hypothesis.scale))
        .then_with(|| left.temporal_coverage.total_cmp(&right.temporal_coverage))
        .then_with(|| left.intrinsic_margin.total_cmp(&right.intrinsic_margin))
        .then_with(|| left.repeated_content_only.cmp(&right.repeated_content_only))
        .then_with(|| left.observation_count.cmp(&right.observation_count))
        .then_with(|| left.source_landmark_count.cmp(&right.source_landmark_count))
        .then_with(|| left.target_landmark_count.cmp(&right.target_landmark_count))
        .then_with(|| {
            left.source_spectral_backend_id
                .cmp(&right.source_spectral_backend_id)
        })
        .then_with(|| {
            left.target_spectral_backend_id
                .cmp(&right.target_spectral_backend_id)
        })
        .then_with(|| {
            left.toolchain_cache_identity
                .cmp(&right.toolchain_cache_identity)
        })
        .then_with(|| {
            left.fine_working_set_bytes
                .cmp(&right.fine_working_set_bytes)
        })
}

#[cfg(test)]
fn group_v2_pair_coarse_temporal_windows(
    candidates: &[V2TrackPairCandidate],
) -> Vec<V2TemporalWindowGroup> {
    group_v2_pair_coarse_temporal_windows_with_probe_count(candidates).0
}

fn group_v2_pair_coarse_temporal_windows_with_probe_count(
    candidates: &[V2TrackPairCandidate],
) -> (Vec<V2TemporalWindowGroup>, usize) {
    let mut ordered = (0..candidates.len()).collect::<Vec<_>>();
    ordered.sort_by(|left, right| {
        compare_v2_temporal_window_geometry(&candidates[*left], &candidates[*right])
            .then_with(|| left.cmp(right))
    });
    let mut builders = Vec::<V2TemporalWindowGroupBuilder>::new();
    let mut probe_count = 0_usize;
    for candidate_index in ordered {
        let candidate = &candidates[candidate_index];
        // Geometry sorting makes plausible co-located windows adjacent. Probe only a bounded
        // recent frontier, then use an O(1) intersection-core certificate that is stronger than
        // pairwise complete-link: every accepted member shares at least 80% of the group's
        // longest interval on both axes and the whole scale range fits the tolerance. Missing a
        // far-away compatible group can only over-split scheduling groups; it never drops or
        // merges executable candidates, while eliminating the previous Θ(n²) diagnostic path.
        let first_builder = builders
            .len()
            .saturating_sub(ALIGNMENT_V2_TEMPORAL_GROUP_MAX_RECENT_PROBES);
        let mut accepted_builder = None;
        for builder_index in (first_builder..builders.len()).rev() {
            probe_count = probe_count.saturating_add(1);
            if builders[builder_index].can_accept(candidate) {
                accepted_builder = Some(builder_index);
                break;
            }
        }
        if let Some(builder_index) = accepted_builder {
            builders[builder_index].accept(candidate_index, candidate);
        } else {
            builders.push(V2TemporalWindowGroupBuilder::new(
                candidate_index,
                candidate,
            ));
        }
    }
    let mut groups = builders
        .into_iter()
        .map(|mut builder| {
            builder.member_indices.sort_by(|left, right| {
                compare_v2_temporal_window_members(&candidates[*left], &candidates[*right])
                    .then_with(|| left.cmp(right))
            });
            V2TemporalWindowGroup {
                member_indices: builder.member_indices,
            }
        })
        .collect::<Vec<_>>();
    groups.sort_by(|left, right| {
        compare_v2_temporal_window_members(
            &candidates[left.member_indices[0]],
            &candidates[right.member_indices[0]],
        )
        .then_with(|| left.member_indices[0].cmp(&right.member_indices[0]))
    });
    (groups, probe_count)
}

impl V2TemporalWindowGroupBuilder {
    fn new(candidate_index: usize, candidate: &V2TrackPairCandidate) -> Self {
        Self {
            member_indices: vec![candidate_index],
            min_scale: candidate.hypothesis.scale,
            max_scale: candidate.hypothesis.scale,
            source_intersection: candidate.global_source_interval,
            target_intersection: candidate.global_target_interval,
            max_source_length_ms: v2_presentation_range_length(candidate.global_source_interval),
            max_target_length_ms: v2_presentation_range_length(candidate.global_target_interval),
        }
    }

    fn can_accept(&self, candidate: &V2TrackPairCandidate) -> bool {
        let min_scale = self.min_scale.min(candidate.hypothesis.scale);
        let max_scale = self.max_scale.max(candidate.hypothesis.scale);
        if max_scale - min_scale > ALIGNMENT_V2_TEMPORAL_WINDOW_SCALE_TOLERANCE + f64::EPSILON * 4.0
        {
            return false;
        }
        let source_intersection = v2_intersect_presentation_ranges(
            self.source_intersection,
            candidate.global_source_interval,
        );
        let target_intersection = v2_intersect_presentation_ranges(
            self.target_intersection,
            candidate.global_target_interval,
        );
        let max_source_length_ms = self.max_source_length_ms.max(v2_presentation_range_length(
            candidate.global_source_interval,
        ));
        let max_target_length_ms = self.max_target_length_ms.max(v2_presentation_range_length(
            candidate.global_target_interval,
        ));
        v2_group_intersection_has_required_overlap(source_intersection, max_source_length_ms)
            && v2_group_intersection_has_required_overlap(target_intersection, max_target_length_ms)
    }

    fn accept(&mut self, candidate_index: usize, candidate: &V2TrackPairCandidate) {
        self.member_indices.push(candidate_index);
        self.min_scale = self.min_scale.min(candidate.hypothesis.scale);
        self.max_scale = self.max_scale.max(candidate.hypothesis.scale);
        self.source_intersection = v2_intersect_presentation_ranges(
            self.source_intersection,
            candidate.global_source_interval,
        );
        self.target_intersection = v2_intersect_presentation_ranges(
            self.target_intersection,
            candidate.global_target_interval,
        );
        self.max_source_length_ms = self.max_source_length_ms.max(v2_presentation_range_length(
            candidate.global_source_interval,
        ));
        self.max_target_length_ms = self.max_target_length_ms.max(v2_presentation_range_length(
            candidate.global_target_interval,
        ));
    }
}

fn compare_v2_temporal_window_geometry(
    left: &V2TrackPairCandidate,
    right: &V2TrackPairCandidate,
) -> std::cmp::Ordering {
    left.global_source_interval
        .start_ms
        .cmp(&right.global_source_interval.start_ms)
        .then_with(|| {
            left.global_target_interval
                .start_ms
                .cmp(&right.global_target_interval.start_ms)
        })
        .then_with(|| {
            left.global_source_interval
                .end_ms
                .cmp(&right.global_source_interval.end_ms)
        })
        .then_with(|| {
            left.global_target_interval
                .end_ms
                .cmp(&right.global_target_interval.end_ms)
        })
        .then_with(|| left.hypothesis.scale.total_cmp(&right.hypothesis.scale))
        .then_with(|| compare_v2_track_pair_candidates(left, right))
}

fn v2_presentation_range_length(range: PresentationRangeMs) -> i64 {
    range.end_ms.saturating_sub(range.start_ms).max(0)
}

fn v2_intersect_presentation_ranges(
    left: PresentationRangeMs,
    right: PresentationRangeMs,
) -> PresentationRangeMs {
    PresentationRangeMs {
        start_ms: left.start_ms.max(right.start_ms),
        end_ms: left.end_ms.min(right.end_ms),
    }
}

fn v2_group_intersection_has_required_overlap(
    intersection: PresentationRangeMs,
    longest_member_ms: i64,
) -> bool {
    let intersection_ms = v2_presentation_range_length(intersection);
    intersection_ms as f64 / longest_member_ms.max(1) as f64
        >= ALIGNMENT_V2_TEMPORAL_WINDOW_MIN_OVERLAP
}

fn compare_v2_temporal_window_members(
    left: &V2TrackPairCandidate,
    right: &V2TrackPairCandidate,
) -> std::cmp::Ordering {
    v2_global_candidate_weight(right)
        .total_cmp(&v2_global_candidate_weight(left))
        .then_with(|| compare_v2_track_pair_candidates(left, right))
}

#[cfg(test)]
fn v2_pair_coarse_candidates_same_temporal_window(
    left: &V2TrackPairCandidate,
    right: &V2TrackPairCandidate,
) -> bool {
    v2_temporal_windows_same_location(
        left.hypothesis.scale,
        left.global_source_interval,
        left.global_target_interval,
        right.hypothesis.scale,
        right.global_source_interval,
        right.global_target_interval,
    )
}

#[cfg(test)]
fn v2_temporal_windows_same_location(
    left_scale: f64,
    left_source: PresentationRangeMs,
    left_target: PresentationRangeMs,
    right_scale: f64,
    right_source: PresentationRangeMs,
    right_target: PresentationRangeMs,
) -> bool {
    if (left_scale - right_scale).abs()
        > ALIGNMENT_V2_TEMPORAL_WINDOW_SCALE_TOLERANCE + f64::EPSILON * 4.0
    {
        return false;
    }
    let left_source = (left_source.start_ms, left_source.end_ms);
    let right_source = (right_source.start_ms, right_source.end_ms);
    let source_overlap = v2_interval_overlap_ms(left_source, right_source);
    let longer_source = (left_source.1 - left_source.0)
        .max(right_source.1 - right_source.0)
        .max(1);
    let left_target = (left_target.start_ms, left_target.end_ms);
    let right_target = (right_target.start_ms, right_target.end_ms);
    let target_overlap = v2_interval_overlap_ms(left_target, right_target);
    let longer_target = (left_target.1 - left_target.0)
        .max(right_target.1 - right_target.0)
        .max(1);
    source_overlap as f64 / longer_source as f64 >= ALIGNMENT_V2_TEMPORAL_WINDOW_MIN_OVERLAP
        && target_overlap as f64 / longer_target as f64 >= ALIGNMENT_V2_TEMPORAL_WINDOW_MIN_OVERLAP
}

#[cfg(test)]
fn v2_hypothesis_source_interval(hypothesis: &AffineHypothesis) -> (i64, i64) {
    (
        hypothesis.source_start_ms.min(hypothesis.source_end_ms),
        hypothesis.source_start_ms.max(hypothesis.source_end_ms),
    )
}

fn v2_interval_overlap_ms(left: (i64, i64), right: (i64, i64)) -> i64 {
    left.1
        .min(right.1)
        .saturating_sub(left.0.max(right.0))
        .max(0)
}

fn v2_coarse_intervals_conflict(left: (i64, i64), right: (i64, i64)) -> bool {
    let shorter_duration_ms = left
        .1
        .saturating_sub(left.0)
        .min(right.1.saturating_sub(right.0))
        .max(0);
    let proportional_tolerance_ms = shorter_duration_ms
        .div_euclid(ALIGNMENT_V2_COARSE_BOUNDARY_OVERLAP_RATIO_DENOMINATOR)
        .min(ALIGNMENT_V2_COARSE_BOUNDARY_OVERLAP_MAX_MS);
    let effective_tolerance_ms =
        proportional_tolerance_ms.max(ALIGNMENT_V2_GLOBAL_OVERLAP_TOLERANCE_MS);
    v2_interval_overlap_ms(left, right) > effective_tolerance_ms
}

#[derive(Debug, Clone)]
struct V2GlobalAssignmentState {
    choices: Vec<Option<usize>>,
    selected_count: usize,
    total_score: f64,
}

#[derive(Debug, Clone, Copy)]
struct V2GlobalExactLimits {
    max_states: usize,
    max_expansions: usize,
}

impl V2GlobalExactLimits {
    const PRODUCTION: Self = Self {
        max_states: ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_STATES,
        max_expansions: ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_EXPANSIONS,
    };
}

struct V2GlobalExactSearch<'a> {
    plan: &'a PlannedAudioAlignmentBatch,
    coarse: &'a [&'a V2PairCoarseCandidates],
    eligible_indices: &'a [Vec<usize>],
    processing_order: &'a [usize],
    remaining_score_upper_bound: Vec<f64>,
    best_states: Vec<V2GlobalAssignmentState>,
    state_count: usize,
    expansion_count: usize,
    limits: V2GlobalExactLimits,
    cancel_flag: Option<&'a AtomicBool>,
    competitor_of: Option<&'a [Option<usize>]>,
}

impl V2GlobalExactSearch<'_> {
    fn search(&mut self, depth: usize, state: &mut V2GlobalAssignmentState) -> Result<(), String> {
        check_cancelled(self.cancel_flag)?;
        self.state_count = self.state_count.checked_add(1).ok_or_else(|| {
            "blocked:resource-limit：批次级 Top-K exact 状态计数溢出。".to_string()
        })?;
        if self.state_count > self.limits.max_states {
            return Err(format!(
                "blocked:resource-limit：批次级 Top-K exact branch-and-bound 预计需要超过 {} 个状态；未截断搜索冒充全局最优。",
                self.limits.max_states
            ));
        }
        if depth == self.processing_order.len() {
            self.record_solution(state);
            return Ok(());
        }
        let pruning_score = if self.competitor_of.is_some() {
            self.best_states.first().map(|best| best.total_score)
        } else {
            self.best_states.get(1).map(|runner| runner.total_score)
        };
        if pruning_score.is_some_and(|score| {
            state.total_score + self.remaining_score_upper_bound[depth] < score
        }) {
            return Ok(());
        }

        let pair_index = self.processing_order[depth];
        let expansion_width = self.eligible_indices[pair_index]
            .len()
            .checked_add(1)
            .ok_or_else(|| "blocked:resource-limit：批次级 Top-K exact 分支数溢出。".to_string())?;
        self.expansion_count = self
            .expansion_count
            .checked_add(expansion_width)
            .ok_or_else(|| {
                "blocked:resource-limit：批次级 Top-K exact 展开计数溢出。".to_string()
            })?;
        if self.expansion_count > self.limits.max_expansions {
            return Err(format!(
                "blocked:resource-limit：批次级 Top-K exact branch-and-bound 预计需要超过 {} 次展开；未截断搜索冒充全局最优。",
                self.limits.max_expansions
            ));
        }

        // Candidate-first traversal establishes strong incumbents early, improving the exact
        // upper-bound pruning rate. Final ranking remains deterministic and independent of this
        // traversal order.
        for candidate_position in 0..self.eligible_indices[pair_index].len() {
            let candidate_index = self.eligible_indices[pair_index][candidate_position];
            if v2_global_candidate_conflicts_with_state(
                self.plan,
                self.coarse,
                state,
                pair_index,
                candidate_index,
            ) {
                continue;
            }
            let candidate_weight =
                v2_global_candidate_weight(&self.coarse[pair_index].candidates[candidate_index]);
            state.choices[pair_index] = Some(candidate_index);
            state.selected_count = state.selected_count.saturating_add(1);
            state.total_score += candidate_weight;
            self.search(depth + 1, state)?;
            state.total_score -= candidate_weight;
            state.selected_count = state.selected_count.saturating_sub(1);
            state.choices[pair_index] = None;
        }
        self.search(depth + 1, state)
    }

    fn record_solution(&mut self, state: &V2GlobalAssignmentState) {
        if self.competitor_of.is_some_and(|best_choices| {
            !v2_global_assignment_is_nontrivial_competitor(best_choices, &state.choices)
        }) {
            return;
        }
        self.best_states.push(state.clone());
        self.best_states
            .sort_by(compare_v2_global_assignment_states);
        self.best_states
            .dedup_by(|left, right| left.choices == right.choices);
        self.best_states.truncate(2);
    }
}

fn v2_global_assignment_is_nontrivial_competitor(
    best_choices: &[Option<usize>],
    competitor_choices: &[Option<usize>],
) -> bool {
    best_choices.len() == competitor_choices.len()
        && competitor_choices
            .iter()
            .zip(best_choices)
            .any(|(competitor, best)| competitor.is_some() && competitor != best)
}

fn block_v2_global_shortlist_for_resource_limit(
    coarse: &[&V2PairCoarseCandidates],
    reason: &str,
) -> Vec<V2GlobalShortlistDecision> {
    coarse
        .iter()
        .map(|pair| {
            let mut diagnostics = pair.diagnostics.clone();
            diagnostics.push(reason.to_string());
            V2GlobalShortlistDecision::Blocked {
                candidate: pair.candidates.first().cloned(),
                alternatives: pair.alternatives.clone(),
                margin: 0.0,
                reason: reason.to_string(),
                diagnostics,
            }
        })
        .collect()
}

fn select_v2_global_shortlist(
    plan: &PlannedAudioAlignmentBatch,
    coarse_by_pair: &[Result<V2PairCoarseCandidates, String>],
    batch_retained_artifact_bytes: usize,
    cancel_flag: Option<&AtomicBool>,
) -> Result<Vec<V2GlobalShortlistDecision>, String> {
    select_v2_global_shortlist_with_limits(
        plan,
        coarse_by_pair,
        batch_retained_artifact_bytes,
        cancel_flag,
        V2GlobalExactLimits::PRODUCTION,
    )
}

fn select_v2_global_shortlist_with_limits(
    plan: &PlannedAudioAlignmentBatch,
    coarse_by_pair: &[Result<V2PairCoarseCandidates, String>],
    batch_retained_artifact_bytes: usize,
    cancel_flag: Option<&AtomicBool>,
    limits: V2GlobalExactLimits,
) -> Result<Vec<V2GlobalShortlistDecision>, String> {
    if coarse_by_pair.len() != plan.pairs.len() {
        return Err("批次级 Top-K coarse 结果数量与 pair 计划不一致。".to_string());
    }
    check_cancelled(cancel_flag)?;
    let coarse_incomplete = coarse_by_pair.iter().any(Result::is_err);
    if coarse_incomplete {
        let mut affected = coarse_by_pair
            .iter()
            .map(Result::is_err)
            .collect::<Vec<_>>();
        loop {
            let mut changed = false;
            for pair_index in 0..plan.pairs.len() {
                if affected[pair_index] {
                    continue;
                }
                let pair = &plan.pairs[pair_index];
                let shares_affected_physical_axis =
                    plan.pairs.iter().enumerate().any(|(other_index, other)| {
                        affected[other_index]
                            && (pair.source_physical_media_index
                                == other.source_physical_media_index
                                || pair.target_physical_media_index
                                    == other.target_physical_media_index)
                    });
                if shares_affected_physical_axis {
                    affected[pair_index] = true;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }

        let unaffected_indices = affected
            .iter()
            .enumerate()
            .filter_map(|(index, affected)| (!*affected).then_some(index))
            .collect::<Vec<_>>();
        let mut unaffected_decisions = if unaffected_indices.is_empty() {
            Vec::new().into_iter()
        } else {
            let subplan = PlannedAudioAlignmentBatch {
                pairing_mode: plan.pairing_mode.clone(),
                source_media_ids: plan.source_media_ids.clone(),
                target_media_ids: plan.target_media_ids.clone(),
                version_reuse_groups: plan.version_reuse_groups.clone(),
                media: plan.media.clone(),
                pairs: unaffected_indices
                    .iter()
                    .map(|index| plan.pairs[*index].clone())
                    .collect(),
                spectral_backend_request: plan.spectral_backend_request.clone(),
            };
            let subcoarse = unaffected_indices
                .iter()
                .map(|index| {
                    Ok(coarse_by_pair[*index]
                        .as_ref()
                        .expect("unaffected coarse result checked")
                        .clone())
                })
                .collect::<Vec<_>>();
            select_v2_global_shortlist_with_limits(
                &subplan,
                &subcoarse,
                batch_retained_artifact_bytes,
                cancel_flag,
                limits,
            )?
            .into_iter()
        };
        return Ok(coarse_by_pair
            .iter()
            .enumerate()
            .map(|(pair_index, coarse)| {
                if !affected[pair_index] {
                    let mut decision = unaffected_decisions
                        .next()
                        .expect("unaffected shortlist decision count must match");
                    annotate_v2_component_level_decision(&mut decision);
                    return decision;
                }
                match coarse {
                    Err(error) => V2GlobalShortlistDecision::Failed(error.clone()),
                    Ok(coarse) => V2GlobalShortlistDecision::Blocked {
                        candidate: coarse.candidates.first().cloned(),
                        alternatives: coarse.alternatives.clone(),
                        margin: 0.0,
                        reason: "该物理媒体冲突 component 内至少一个 pair 未完成 coarse scoring；仅本 component 未进入 fine。"
                            .to_string(),
                        diagnostics: coarse.diagnostics.clone(),
                    },
                }
            })
            .collect());
    }

    let coarse = coarse_by_pair
        .iter()
        .map(|item| item.as_ref().expect("coarse completeness checked above"))
        .collect::<Vec<_>>();
    let affine_config = v2_affine_match_config();
    let eligible_indices = coarse
        .iter()
        .map(|pair| {
            pair.candidates
                .iter()
                .enumerate()
                .filter(|(_, candidate)| {
                    candidate.temporal_coverage >= ALIGNMENT_V2_MIN_TEMPORAL_COVERAGE
                        && candidate.hypothesis.inlier_count >= affine_config.min_inliers
                        && v2_global_candidate_weight(candidate) > 0.0
                        && ensure_v2_active_artifact_budget(
                            batch_retained_artifact_bytes,
                            candidate.fine_working_set_bytes,
                        )
                        .is_ok()
                })
                .map(|(index, _)| index)
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let total_candidate_count = eligible_indices
        .iter()
        .try_fold(0_usize, |total, candidates| {
            total.checked_add(candidates.len())
        })
        .ok_or_else(|| "blocked:resource-limit：批次级 Top-K candidate 计数溢出。".to_string())?;
    if total_candidate_count > ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_CANDIDATES {
        let reason = format!(
            "blocked:resource-limit：批次级 Top-K 有 {total_candidate_count} 个可执行 candidate，超过 {} 个确定性硬上限；未截断候选冒充全局最优。",
            ALIGNMENT_V2_GLOBAL_SHORTLIST_MAX_CANDIDATES
        );
        return Ok(block_v2_global_shortlist_for_resource_limit(
            &coarse, &reason,
        ));
    }

    // Process the most constrained pair first. This improves exact branch-and-bound pruning
    // without using file names, request order or inferred episode numbers as a prior. Pair index
    // is only the final deterministic tie-break when the constraint graph is otherwise identical.
    let mut processing_order = (0..plan.pairs.len()).collect::<Vec<_>>();
    processing_order.sort_by(|left, right| {
        eligible_indices[*left]
            .len()
            .cmp(&eligible_indices[*right].len())
            .then_with(|| {
                plan.pairs[*left]
                    .source_media_index
                    .cmp(&plan.pairs[*right].source_media_index)
            })
            .then_with(|| {
                plan.pairs[*left]
                    .target_media_index
                    .cmp(&plan.pairs[*right].target_media_index)
            })
            .then_with(|| left.cmp(right))
    });
    let mut remaining_score_upper_bound = vec![0.0_f64; processing_order.len() + 1];
    for depth in (0..processing_order.len()).rev() {
        let pair_index = processing_order[depth];
        let pair_upper_bound = eligible_indices[pair_index]
            .iter()
            .map(|candidate_index| {
                v2_global_candidate_weight(&coarse[pair_index].candidates[*candidate_index])
            })
            .fold(0.0_f64, f64::max);
        remaining_score_upper_bound[depth] =
            remaining_score_upper_bound[depth + 1] + pair_upper_bound;
    }
    let mut initial_state = V2GlobalAssignmentState {
        choices: vec![None; plan.pairs.len()],
        selected_count: 0,
        total_score: 0.0,
    };
    let mut exact = V2GlobalExactSearch {
        plan,
        coarse: &coarse,
        eligible_indices: &eligible_indices,
        processing_order: &processing_order,
        remaining_score_upper_bound,
        best_states: Vec::new(),
        state_count: 0,
        expansion_count: 0,
        limits,
        cancel_flag,
        competitor_of: None,
    };
    if let Err(error) = exact.search(0, &mut initial_state) {
        if error.starts_with("blocked:resource-limit") {
            return Ok(block_v2_global_shortlist_for_resource_limit(
                &coarse, &error,
            ));
        }
        return Err(error);
    }
    let Some(best) = exact.best_states.first().cloned() else {
        return Err("批次级 Top-K exact branch-and-bound 没有产生任何完整状态。".to_string());
    };
    let first_pass_state_count = exact.state_count;
    let first_pass_expansion_count = exact.expansion_count;
    let has_possible_nontrivial_competitor =
        eligible_indices
            .iter()
            .enumerate()
            .any(|(pair_index, candidates)| match best.choices[pair_index] {
                Some(best_candidate) => candidates
                    .iter()
                    .any(|candidate| *candidate != best_candidate),
                None => !candidates.is_empty(),
            });
    let mut competitor_states = Vec::new();
    let mut competitor_state_count = 0usize;
    let mut competitor_expansion_count = 0usize;
    if has_possible_nontrivial_competitor {
        let mut competitor_initial = V2GlobalAssignmentState {
            choices: vec![None; plan.pairs.len()],
            selected_count: 0,
            total_score: 0.0,
        };
        let mut competitor_exact = V2GlobalExactSearch {
            plan,
            coarse: &coarse,
            eligible_indices: &eligible_indices,
            processing_order: &processing_order,
            remaining_score_upper_bound: exact.remaining_score_upper_bound.clone(),
            best_states: Vec::new(),
            state_count: 0,
            expansion_count: 0,
            limits,
            cancel_flag,
            competitor_of: Some(&best.choices),
        };
        if let Err(error) = competitor_exact.search(0, &mut competitor_initial) {
            if error.starts_with("blocked:resource-limit") {
                return Ok(block_v2_global_shortlist_for_resource_limit(
                    &coarse, &error,
                ));
            }
            return Err(error);
        }
        competitor_state_count = competitor_exact.state_count;
        competitor_expansion_count = competitor_exact.expansion_count;
        competitor_states = competitor_exact.best_states;
    }
    let runner_up = competitor_states.first();
    let competing_pair_indices = runner_up
        .map(|runner| {
            best.choices
                .iter()
                .zip(&runner.choices)
                .enumerate()
                .filter_map(|(pair_index, (best_choice, runner_choice))| {
                    (best_choice != runner_choice).then_some(pair_index)
                })
                .collect::<HashSet<_>>()
        })
        .unwrap_or_default();
    let global_margin = runner_up
        .map(|runner| {
            let competing_score = competing_pair_indices
                .iter()
                .map(|pair_index| {
                    let best_weight = best.choices[*pair_index]
                        .map(|candidate_index| {
                            v2_global_candidate_weight(
                                &coarse[*pair_index].candidates[candidate_index],
                            )
                        })
                        .unwrap_or(0.0);
                    let runner_weight = runner.choices[*pair_index]
                        .map(|candidate_index| {
                            v2_global_candidate_weight(
                                &coarse[*pair_index].candidates[candidate_index],
                            )
                        })
                        .unwrap_or(0.0);
                    best_weight.max(runner_weight)
                })
                .sum::<f64>();
            ((best.total_score - runner.total_score) / competing_score.max(0.001)).clamp(0.0, 1.0)
        })
        .unwrap_or(1.0);
    let close_competition =
        runner_up.is_some() && global_margin < ALIGNMENT_V2_GLOBAL_AMBIGUITY_MARGIN;
    let global_summary = format!(
        "项目级 Top-K shortlist：{} 个 pair、{} 个合格 candidate，exact branch-and-bound 访问 {} 个状态、展开 {} 次；best 选择 {}/{} 个 pair，总分 {:.4}，runner-up margin {:.3}；未静默截断，未使用文件名、数组顺序或剧集号先验。",
        plan.pairs.len(),
        total_candidate_count,
        first_pass_state_count.saturating_add(competitor_state_count),
        first_pass_expansion_count.saturating_add(competitor_expansion_count),
        best.selected_count,
        plan.pairs.len(),
        best.total_score,
        global_margin
    );
    Ok(coarse
        .iter()
        .enumerate()
        .map(|(pair_index, coarse)| {
            let mut diagnostics = coarse.diagnostics.clone();
            diagnostics.push(global_summary.clone());
            let pair_has_close_competition =
                close_competition && competing_pair_indices.contains(&pair_index);
            let pair_margin = if competing_pair_indices.contains(&pair_index) {
                global_margin
            } else {
                1.0
            };
            match best.choices[pair_index] {
                Some(candidate_index) if !pair_has_close_competition => {
                    V2GlobalShortlistDecision::Selected(PreparedV2SelectedCandidate {
                        candidate: coarse.candidates[candidate_index].clone(),
                        alternatives: coarse.alternatives.clone(),
                        global_margin: pair_margin,
                        global_diagnostic: diagnostics.join("；"),
                    })
                }
                Some(candidate_index) => V2GlobalShortlistDecision::Blocked {
                    candidate: Some(coarse.candidates[candidate_index].clone()),
                    alternatives: coarse.alternatives.clone(),
                    margin: pair_margin,
                    reason: format!(
                        "项目级 Top-K best/非平凡竞争解 margin {pair_margin:.3} 低于 {:.3}；该 pair 参与竞争，未执行 fine。",
                        ALIGNMENT_V2_GLOBAL_AMBIGUITY_MARGIN
                    ),
                    diagnostics,
                },
                None => V2GlobalShortlistDecision::Blocked {
                    candidate: coarse.candidates.first().cloned(),
                    alternatives: coarse.alternatives.clone(),
                    margin: pair_margin,
                    reason: "该 pair 的 Top-K 候选与同一物理媒体上已选区间冲突，未进入项目级 shortlist，也未执行 fine。"
                        .to_string(),
                    diagnostics,
                },
            }
        })
        .collect())
}

fn annotate_v2_component_level_decision(decision: &mut V2GlobalShortlistDecision) {
    const NOTE: &str =
        "批次含其他失败 component；本结果仅声明当前独立 physical-media component 内的全局最优。";
    match decision {
        V2GlobalShortlistDecision::Selected(selected) => {
            selected.global_diagnostic.push('；');
            selected.global_diagnostic.push_str(NOTE);
        }
        V2GlobalShortlistDecision::Blocked { diagnostics, .. } => {
            diagnostics.push(NOTE.to_string());
        }
        V2GlobalShortlistDecision::Failed(_) => {}
    }
}

fn create_audio_alignment_batch_execution_identity(
    pair: &PlannedAudioAlignmentBatchPair,
    prepared: &[PreparedAudioAlignmentBatchMediaState],
    toolchain: &PinnedMediaToolchain,
    native_executable_digest: &str,
) -> Result<(String, AudioAlignmentBatchExecutionIdentitySnapshot), String> {
    let source =
        prepared_audio_alignment_batch_media(prepared, pair.source_media_index, "B 站参考")?;
    let target =
        prepared_audio_alignment_batch_media(prepared, pair.target_media_index, "目标原片")?;
    if source.evidence.toolchain_cache_identity != target.evidence.toolchain_cache_identity
        || source.evidence.toolchain_cache_identity != toolchain.cache_identity_fragment()
    {
        return Err(
            "blocked:media-toolchain-integrity：关系分数 execution identity 未绑定同一固定工具链。"
                .to_string(),
        );
    }
    let identity = AudioAlignmentBatchExecutionIdentitySnapshot {
        schema_version: AUDIO_ALIGNMENT_BATCH_EXECUTION_IDENTITY_SCHEMA_VERSION,
        engine_version: ALIGNMENT_V2_ENGINE_VERSION,
        feature_version: ALIGNMENT_V2_FEATURE_VERSION,
        relation_score_version: AUDIO_ALIGNMENT_BATCH_RELATION_SCORE_VERSION,
        native_executable_digest: native_executable_digest.to_string(),
        ffmpeg_binary_digest: format!("sha256:{}", toolchain.ffmpeg().binary_digest()),
        ffprobe_binary_digest: format!("sha256:{}", toolchain.ffprobe().binary_digest()),
        source_spectral_backends: collect_audio_alignment_batch_spectral_backend_identities(
            &source.evidence.landmarks,
            "B 站参考",
        )?,
        target_spectral_backends: collect_audio_alignment_batch_spectral_backend_identities(
            &target.evidence.landmarks,
            "目标原片",
        )?,
    };
    let canonical = canonicalize_alignment_benchmark_json(
        &serde_json::to_value(&identity)
            .map_err(|_| "关系分数 execution identity 无法序列化。".to_string())?,
    )?;
    let digest = format!(
        "sha256:{}",
        sha256_alignment_benchmark_bytes(canonical.as_bytes())
    );
    Ok((digest, identity))
}

fn current_audio_alignment_native_executable_digest() -> Result<String, String> {
    let executable = std::env::current_exe()
        .map_err(|_| "blocked:native-build-identity：无法定位当前原生可执行文件。".to_string())?;
    let mut reader = File::open(executable)
        .map_err(|_| "blocked:native-build-identity：无法读取当前原生可执行文件。".to_string())?;
    let mut hasher = Sha256::new();
    let mut buffer = vec![0_u8; 1024 * 1024];
    loop {
        let read = reader.read(&mut buffer).map_err(|_| {
            "blocked:native-build-identity：当前原生可执行文件摘要读取失败。".to_string()
        })?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(format!(
        "sha256:{}",
        hasher
            .finalize()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    ))
}

fn collect_audio_alignment_batch_spectral_backend_identities(
    landmarks: &HashMap<u32, CachedV2Landmarks>,
    role: &str,
) -> Result<Vec<AudioAlignmentBatchSpectralBackendIdentitySnapshot>, String> {
    let mut identities = landmarks
        .values()
        .map(
            |artifact| AudioAlignmentBatchSpectralBackendIdentitySnapshot {
                backend_id: artifact.spectral_backend.backend_id.clone(),
                requested_backend: artifact.spectral_backend.requested_backend.clone(),
                backend_detail: artifact.spectral_backend.backend_detail.clone(),
                fallback_reason: artifact.spectral_backend.fallback_reason.clone(),
            },
        )
        .collect::<Vec<_>>();
    identities.sort_by(|left, right| {
        left.backend_id
            .cmp(&right.backend_id)
            .then_with(|| left.requested_backend.cmp(&right.requested_backend))
            .then_with(|| left.backend_detail.cmp(&right.backend_detail))
            .then_with(|| left.fallback_reason.cmp(&right.fallback_reason))
    });
    identities.dedup();
    if identities.is_empty() {
        return Err(format!(
            "blocked:spectral-backend-identity：{role}没有实际完成 coarse scoring 的声谱后端身份。"
        ));
    }
    Ok(identities)
}

fn v2_relation_candidate_is_intrinsically_eligible(candidate: &V2TrackPairCandidate) -> bool {
    let global_score = v2_global_candidate_weight(candidate);
    let affine_config = v2_affine_match_config();
    candidate.score.is_finite()
        && global_score.is_finite()
        && global_score > 0.0
        && candidate.hypothesis.scale.is_finite()
        && candidate.hypothesis.scale > 0.0
        && candidate.temporal_coverage.is_finite()
        && candidate.temporal_coverage >= ALIGNMENT_V2_MIN_TEMPORAL_COVERAGE
        && candidate.hypothesis.unique_source_coverage.is_finite()
        && candidate.hypothesis.inlier_count >= affine_config.min_inliers
}

fn compare_v2_relation_candidates(
    left_rank: usize,
    left: &V2TrackPairCandidate,
    right_rank: usize,
    right: &V2TrackPairCandidate,
) -> std::cmp::Ordering {
    v2_global_candidate_weight(right)
        .total_cmp(&v2_global_candidate_weight(left))
        .then_with(|| right.score.total_cmp(&left.score))
        .then_with(|| left_rank.cmp(&right_rank))
}

fn create_audio_alignment_batch_relation_candidate_snapshot(
    rank: usize,
    candidate: &V2TrackPairCandidate,
) -> AudioAlignmentBatchRelationCandidateSnapshot {
    AudioAlignmentBatchRelationCandidateSnapshot {
        rank,
        source_stream_index: candidate.source_input.stream.stream_index,
        target_stream_index: candidate.target_input.stream.stream_index,
        score: candidate.score,
        global_score: v2_global_candidate_weight(candidate),
        scale: candidate.hypothesis.scale,
        offset_ms: candidate.hypothesis.offset_ms,
        source_start_ms: candidate.global_source_interval.start_ms,
        source_end_ms: candidate.global_source_interval.end_ms,
        target_start_ms: candidate.global_target_interval.start_ms,
        target_end_ms: candidate.global_target_interval.end_ms,
        inlier_count: candidate.hypothesis.inlier_count,
        temporal_coverage: candidate.temporal_coverage,
        unique_source_coverage: candidate.hypothesis.unique_source_coverage,
    }
}

fn create_audio_alignment_batch_relation_ranking_evidence(
    coarse: &Result<V2PairCoarseCandidates, String>,
    execution_identity: Result<(String, AudioAlignmentBatchExecutionIdentitySnapshot), String>,
) -> Result<AudioAlignmentBatchRelationRankingSnapshot, String> {
    let Ok(coarse) = coarse else {
        return Ok(AudioAlignmentBatchRelationRankingSnapshot::failed());
    };
    let (execution_identity_digest, execution_identity) = execution_identity?;
    if coarse.candidates.iter().any(|candidate| {
        !candidate.score.is_finite()
            || !v2_global_candidate_weight(candidate).is_finite()
            || !candidate.hypothesis.scale.is_finite()
            || !candidate.temporal_coverage.is_finite()
            || !candidate.hypothesis.unique_source_coverage.is_finite()
    }) {
        return Err(
            "关系排名 evidence 含非有限 coarse candidate 数值；拒绝发布不可比较分数。".to_string(),
        );
    }
    let eligible = coarse
        .candidates
        .iter()
        .enumerate()
        .filter(|(_, candidate)| v2_relation_candidate_is_intrinsically_eligible(candidate))
        .collect::<Vec<_>>();
    let candidate_count = coarse.candidates.len();
    let eligible_candidate_count = eligible.len();
    let best = eligible
        .into_iter()
        .min_by(|(left_index, left), (right_index, right)| {
            compare_v2_relation_candidates(*left_index, left, *right_index, right)
        });
    let Some((best_index, best_candidate)) = best else {
        return Ok(
            AudioAlignmentBatchRelationRankingSnapshot::no_eligible_candidate(
                candidate_count,
                execution_identity_digest,
                execution_identity,
            ),
        );
    };
    let best_eligible_candidate =
        create_audio_alignment_batch_relation_candidate_snapshot(best_index + 1, best_candidate);
    Ok(AudioAlignmentBatchRelationRankingSnapshot {
        score_version: AUDIO_ALIGNMENT_BATCH_RELATION_SCORE_VERSION,
        execution_identity_digest: Some(execution_identity_digest),
        execution_identity: Some(execution_identity),
        state: AudioAlignmentBatchRelationRankingState::Ranked,
        candidate_count,
        eligible_candidate_count,
        score: Some(best_eligible_candidate.global_score),
        best_eligible_candidate: Some(best_eligible_candidate),
    })
}

fn create_audio_alignment_batch_global_selection_evidence(
    coarse: &Result<V2PairCoarseCandidates, String>,
    decision: &V2GlobalShortlistDecision,
    batch_retained_artifact_bytes: usize,
) -> Result<AudioAlignmentBatchGlobalSelectionSnapshot, String> {
    let Ok(coarse) = coarse else {
        return Ok(AudioAlignmentBatchGlobalSelectionSnapshot::failed());
    };
    if coarse.candidates.iter().any(|candidate| {
        !candidate.score.is_finite()
            || !candidate.temporal_coverage.is_finite()
            || !candidate.hypothesis.scale.is_finite()
            || !candidate.hypothesis.unique_source_coverage.is_finite()
            || !v2_global_candidate_weight(candidate).is_finite()
    }) {
        return Err(
            "批次级 Top-K evidence 含有非有限数值；拒绝发布不可序列化的 blind 结果。".to_string(),
        );
    }
    match decision {
        V2GlobalShortlistDecision::Blocked {
            alternatives,
            reason,
            ..
        } if reason.trim().is_empty()
            || alternatives.len() > 10
            || alternatives.iter().any(|alternative| {
                !alternative.score.is_finite() || !alternative.scale.is_finite()
            }) =>
        {
            return Err("批次级 Top-K blocked 诊断不完整或含非有限备选分数。".to_string());
        }
        V2GlobalShortlistDecision::Failed(error) if error.trim().is_empty() => {
            return Err("批次级 Top-K failed 诊断不能为空。".to_string());
        }
        _ => {}
    }
    let affine_config = v2_affine_match_config();
    let eligible = coarse
        .candidates
        .iter()
        .map(|candidate| {
            candidate.temporal_coverage >= ALIGNMENT_V2_MIN_TEMPORAL_COVERAGE
                && candidate.hypothesis.inlier_count >= affine_config.min_inliers
                && v2_global_candidate_weight(candidate) > 0.0
                && ensure_v2_active_artifact_budget(
                    batch_retained_artifact_bytes,
                    candidate.fine_working_set_bytes,
                )
                .is_ok()
        })
        .collect::<Vec<_>>();
    let (state, selected, decision_candidate, margin) = match decision {
        V2GlobalShortlistDecision::Selected(selected) => (
            AudioAlignmentBatchGlobalSelectionState::Selected,
            true,
            Some(&selected.candidate),
            Some(selected.global_margin),
        ),
        V2GlobalShortlistDecision::Blocked {
            candidate, margin, ..
        } => (
            AudioAlignmentBatchGlobalSelectionState::Blocked,
            false,
            candidate.as_ref(),
            Some(*margin),
        ),
        V2GlobalShortlistDecision::Failed(_) => (
            AudioAlignmentBatchGlobalSelectionState::Failed,
            false,
            None,
            None,
        ),
    };
    let decision_rank = decision_candidate.and_then(|candidate| {
        coarse
            .candidates
            .iter()
            .position(|item| v2_batch_evidence_candidate_eq(item, candidate))
            .map(|index| index + 1)
    });
    let decision_score = decision_candidate.map(v2_global_candidate_weight);
    if decision_candidate.is_some() && decision_rank.is_none() {
        return Err(
            "批次级 Top-K decision candidate 无法回溯到当前 pair 的完整候选表。".to_string(),
        );
    }
    if selected
        && decision_rank
            .and_then(|rank| eligible.get(rank.saturating_sub(1)))
            .copied()
            != Some(true)
    {
        return Err("批次级 Top-K selected candidate 不在可执行候选集中。".to_string());
    }
    if margin.is_some_and(|value| !value.is_finite()) {
        return Err("批次级 Top-K margin 不是有限数值。".to_string());
    }
    let top_k = coarse
        .candidates
        .iter()
        .take(AUDIO_ALIGNMENT_BATCH_EVIDENCE_TOP_K)
        .enumerate()
        .map(|(index, candidate)| {
            create_audio_alignment_batch_global_candidate_snapshot(
                index + 1,
                candidate,
                eligible[index],
                selected && decision_rank == Some(index + 1),
            )
        })
        .collect::<Vec<_>>();
    let decision_candidate = decision_candidate
        .zip(decision_rank)
        .map(|(candidate, rank)| {
            create_audio_alignment_batch_global_candidate_snapshot(
                rank,
                candidate,
                eligible[rank - 1],
                selected,
            )
        });
    Ok(AudioAlignmentBatchGlobalSelectionSnapshot {
        state,
        selected,
        selected_rank: if selected { decision_rank } else { None },
        selected_score: if selected { decision_score } else { None },
        decision_rank,
        decision_score,
        margin,
        candidate_count: coarse.candidates.len(),
        eligible_candidate_count: eligible.iter().filter(|value| **value).count(),
        top_k,
        decision_candidate,
    })
}

fn create_audio_alignment_batch_global_candidate_snapshot(
    rank: usize,
    candidate: &V2TrackPairCandidate,
    eligible: bool,
    global_selected: bool,
) -> AudioAlignmentBatchGlobalCandidateSnapshot {
    AudioAlignmentBatchGlobalCandidateSnapshot {
        rank,
        source_stream_index: candidate.source_input.stream.stream_index,
        target_stream_index: candidate.target_input.stream.stream_index,
        score: candidate.score,
        global_score: v2_global_candidate_weight(candidate),
        scale: candidate.hypothesis.scale,
        offset_ms: candidate.hypothesis.offset_ms,
        source_start_ms: candidate.global_source_interval.start_ms,
        source_end_ms: candidate.global_source_interval.end_ms,
        target_start_ms: candidate.global_target_interval.start_ms,
        target_end_ms: candidate.global_target_interval.end_ms,
        inlier_count: candidate.hypothesis.inlier_count,
        temporal_coverage: candidate.temporal_coverage,
        unique_source_coverage: candidate.hypothesis.unique_source_coverage,
        eligible,
        global_selected,
    }
}

fn v2_batch_evidence_candidate_eq(
    left: &V2TrackPairCandidate,
    right: &V2TrackPairCandidate,
) -> bool {
    left.source_input.stream.stream_index == right.source_input.stream.stream_index
        && left.target_input.stream.stream_index == right.target_input.stream.stream_index
        && left.hypothesis == right.hypothesis
        && left.score.to_bits() == right.score.to_bits()
        && left.global_source_interval == right.global_source_interval
        && left.global_target_interval == right.global_target_interval
}

fn compare_v2_global_assignment_states(
    left: &V2GlobalAssignmentState,
    right: &V2GlobalAssignmentState,
) -> std::cmp::Ordering {
    right
        .total_score
        .total_cmp(&left.total_score)
        .then_with(|| left.choices.cmp(&right.choices))
}

fn v2_global_candidate_weight(candidate: &V2TrackPairCandidate) -> f64 {
    let uniqueness_factor =
        0.35 + candidate.hypothesis.unique_source_coverage.clamp(0.0, 1.0) * 0.65;
    let alternative_bonus = candidate.intrinsic_margin.clamp(0.0, 1.0) * 0.20;
    let repeated_penalty = if candidate.repeated_content_only {
        ALIGNMENT_V2_GLOBAL_REPEATED_CONTENT_PENALTY
    } else {
        0.0
    };
    candidate.score.clamp(0.0, 1.0) * uniqueness_factor + alternative_bonus - repeated_penalty
}

fn v2_fine_coarse_upper_bound(candidate: &V2TrackPairCandidate) -> Result<ScoreMicros, String> {
    let weight = v2_global_candidate_weight(candidate);
    if !weight.is_finite() {
        return Err(
            "fine frontier coarse upper bound 不能由非有限 global weight 构造。".to_string(),
        );
    }
    let normalized = (weight.max(0.0) / AUDIO_ALIGNMENT_BATCH_GLOBAL_WEIGHT_MAX).clamp(0.0, 1.0);
    let micros = (normalized * f64::from(SCORE_MICROS_ONE))
        .ceil()
        .clamp(0.0, f64::from(SCORE_MICROS_ONE)) as u32;
    ScoreMicros::new(micros)
        .map_err(|error| format!("fine frontier coarse upper bound 越界：{error:?}"))
}

fn v2_fine_score_from_proposal(
    coarse_upper_bound: ScoreMicros,
    proposal: &AudioAlignmentProposal,
) -> Result<ScoreMicros, String> {
    if !proposal.confidence.is_finite() || proposal.confidence <= 0.0 {
        return Err("fine proposal 没有正的有限 confidence，不能标记为 Scored。".to_string());
    }
    let quality_micros =
        (proposal.confidence.clamp(0.0, 1.0) * f64::from(SCORE_MICROS_ONE)).floor() as u64;
    let score =
        (u64::from(coarse_upper_bound.get()) * quality_micros) / u64::from(SCORE_MICROS_ONE);
    let score = u32::try_from(score).map_err(|_| "fine score micros 无法表示。".to_string())?;
    if score == 0 {
        return Err("fine proposal 的版本化质量因子量化后为零。".to_string());
    }
    let score =
        ScoreMicros::new(score).map_err(|error| format!("fine score micros 越界：{error:?}"))?;
    if score > coarse_upper_bound {
        return Err("fine score 超过 coarse upper bound。".to_string());
    }
    Ok(score)
}

fn canonicalize_v2_physical_intervals(
    mut intervals: Vec<PhysicalInterval>,
) -> Vec<PhysicalInterval> {
    intervals.sort_by_key(|interval| (interval.start_ms, interval.end_ms));
    let mut canonical = Vec::<PhysicalInterval>::with_capacity(intervals.len());
    for interval in intervals {
        if interval.end_ms <= interval.start_ms {
            continue;
        }
        if let Some(previous) = canonical.last_mut() {
            if interval.start_ms <= previous.end_ms {
                previous.end_ms = previous.end_ms.max(interval.end_ms);
                continue;
            }
        }
        canonical.push(interval);
    }
    canonical
}

fn v2_fine_physical_occupancy_from_proposal(
    pair: &PlannedAudioAlignmentBatchPair,
    proposal: &AudioAlignmentProposal,
) -> Result<PairPhysicalOccupancy, String> {
    let time_map = proposal
        .time_map
        .as_ref()
        .ok_or_else(|| "fine proposal 缺少最终 TimeMap。".to_string())?;
    let source = canonicalize_v2_physical_intervals(
        time_map
            .spans
            .iter()
            .filter_map(|span| {
                (span.source_end_ms > span.source_start_ms).then_some(PhysicalInterval {
                    start_ms: span.source_start_ms,
                    end_ms: span.source_end_ms,
                })
            })
            .collect(),
    );
    let target = canonicalize_v2_physical_intervals(
        time_map
            .spans
            .iter()
            .filter_map(|span| {
                (span.target_end_ms > span.target_start_ms).then_some(PhysicalInterval {
                    start_ms: span.target_start_ms,
                    end_ms: span.target_end_ms,
                })
            })
            .collect(),
    );
    if source.is_empty() || target.is_empty() {
        return Err("fine proposal 的最终 TimeMap 没有双轴非空物理占用。".to_string());
    }
    Ok(PairPhysicalOccupancy {
        source: PhysicalAxisOccupancy {
            space_ordinal: u32::try_from(pair.source_physical_media_index)
                .map_err(|_| "source physical group ordinal 无法表示为 u32。".to_string())?,
            reuse_group_ordinal: pair.source_axis_reuse_group_ordinal,
            intervals: source,
        },
        target: PhysicalAxisOccupancy {
            space_ordinal: u32::try_from(pair.target_physical_media_index)
                .map_err(|_| "target physical group ordinal 无法表示为 u32。".to_string())?,
            reuse_group_ordinal: pair.target_axis_reuse_group_ordinal,
            intervals: target,
        },
    })
}

fn v2_fine_pair_components(plan: &PlannedAudioAlignmentBatch) -> Vec<Vec<usize>> {
    let mut assigned = vec![false; plan.pairs.len()];
    let mut components = Vec::<Vec<usize>>::new();
    for seed in 0..plan.pairs.len() {
        if assigned[seed] {
            continue;
        }
        assigned[seed] = true;
        let mut component = vec![seed];
        let mut cursor = 0_usize;
        while cursor < component.len() {
            let current = &plan.pairs[component[cursor]];
            for (candidate_index, candidate_assigned) in assigned.iter_mut().enumerate() {
                if *candidate_assigned {
                    continue;
                }
                let candidate = &plan.pairs[candidate_index];
                if current.source_physical_media_index == candidate.source_physical_media_index
                    || current.target_physical_media_index == candidate.target_physical_media_index
                {
                    *candidate_assigned = true;
                    component.push(candidate_index);
                }
            }
            cursor += 1;
        }
        component.sort_unstable();
        components.push(component);
    }
    components
}

type V2FineFrontierInventoryBuild = (
    FineCandidateInventory,
    Vec<V2FineFrontierGroupBinding>,
    Vec<FineCandidateId>,
    V2FineInventoryEvidence,
    FineFrontierConfig,
);

fn create_v2_fine_frontier_inventory(
    plan: &PlannedAudioAlignmentBatch,
    coarse_by_pair: &[Result<V2PairCoarseCandidates, String>],
    pair_indices: &[usize],
) -> Result<V2FineFrontierInventoryBuild, String> {
    let mut candidates = Vec::<FineCandidate>::new();
    let mut bindings = Vec::<V2FineFrontierGroupBinding>::new();
    let mut inventory_candidates = Vec::<AudioAlignmentBatchFineInventoryCandidateSnapshot>::new();
    let mut mandatory_seed_by_target =
        HashMap::<(bool, usize), (ScoreMicros, FineCandidateId)>::new();
    for pair_index in pair_indices {
        let pair = plan
            .pairs
            .get(*pair_index)
            .ok_or_else(|| "fine frontier component pair 索引越界。".to_string())?;
        let coarse = coarse_by_pair
            .get(*pair_index)
            .ok_or_else(|| "fine frontier coarse pair 索引越界。".to_string())?
            .as_ref()
            .map_err(Clone::clone)?;
        let pair_ordinal = u32::try_from(pair.pair_ordinal)
            .map_err(|_| "fine frontier pair ordinal 无法表示为 u32。".to_string())?;
        let mut seen = vec![false; coarse.candidates.len()];
        for (group_index, group) in coarse.temporal_window_groups.iter().enumerate() {
            if group.member_indices.is_empty() {
                return Err("fine frontier temporal group 不能为空。".to_string());
            }
            let id = FineCandidateId {
                pair_ordinal,
                candidate_ordinal: u32::try_from(group_index + 1)
                    .map_err(|_| "fine frontier candidate ordinal 无法表示为 u32。".to_string())?,
            };
            let mut upper = ScoreMicros::ZERO;
            let mut intrinsically_eligible = false;
            let mut members = Vec::with_capacity(group.member_indices.len());
            for member_index in &group.member_indices {
                let candidate = coarse
                    .candidates
                    .get(*member_index)
                    .ok_or_else(|| "fine frontier temporal group member 索引越界。".to_string())?;
                if std::mem::replace(
                    seen.get_mut(*member_index).ok_or_else(|| {
                        "fine frontier temporal group seen 索引越界。".to_string()
                    })?,
                    true,
                ) {
                    return Err("同一 raw coarse candidate 被重复放入 fine group。".to_string());
                }
                upper = upper.max(v2_fine_coarse_upper_bound(candidate)?);
                intrinsically_eligible |=
                    v2_relation_candidate_is_intrinsically_eligible(candidate);
                members.push(create_audio_alignment_batch_relation_candidate_snapshot(
                    member_index + 1,
                    candidate,
                ));
            }
            candidates.push(FineCandidate {
                id,
                coarse_upper_bound: upper,
                physical_occupancy: None,
                state: if intrinsically_eligible {
                    FineEvaluationState::Unresolved
                } else {
                    FineEvaluationState::EvaluatedIneligible
                },
            });
            if intrinsically_eligible {
                let target_axis_key = pair
                    .target_axis_reuse_group_ordinal
                    .map(|ordinal| (true, ordinal as usize))
                    .unwrap_or((false, pair.target_physical_media_index));
                mandatory_seed_by_target
                    .entry(target_axis_key)
                    .and_modify(|current| {
                        if upper > current.0 || (upper == current.0 && id < current.1) {
                            *current = (upper, id);
                        }
                    })
                    .or_insert((upper, id));
            }
            bindings.push(V2FineFrontierGroupBinding {
                id,
                pair_index: *pair_index,
                member_indices: group.member_indices.clone(),
            });
            inventory_candidates.push(AudioAlignmentBatchFineInventoryCandidateSnapshot {
                id: id.into(),
                coarse_upper_bound_micros: upper.get(),
                source_axis_reuse_group_ordinal: pair.source_axis_reuse_group_ordinal,
                target_axis_reuse_group_ordinal: pair.target_axis_reuse_group_ordinal,
                members,
            });
        }
        if seen.iter().any(|seen| !*seen) {
            return Err(
                "fine frontier temporal groups 未完整覆盖 raw coarse candidate universe。"
                    .to_string(),
            );
        }
    }
    let inventory_digest = create_v2_fine_inventory_digest(&inventory_candidates)?;
    let inventory = FineCandidateInventory { candidates };
    let mut max_upper_by_pair = HashMap::<u32, u32>::new();
    for candidate in &inventory.candidates {
        max_upper_by_pair
            .entry(candidate.id.pair_ordinal)
            .and_modify(|upper| *upper = (*upper).max(candidate.coarse_upper_bound.get()))
            .or_insert(candidate.coarse_upper_bound.get());
    }
    let component_upper_sum = max_upper_by_pair.values().try_fold(0_u64, |sum, upper| {
        sum.checked_add(u64::from(*upper))
            .ok_or_else(|| "fine frontier component upper sum 溢出。".to_string())
    })?;
    let resolution_margin_micros = ((component_upper_sum as f64)
        * ALIGNMENT_V2_GLOBAL_AMBIGUITY_MARGIN)
        .ceil()
        .max(AUDIO_ALIGNMENT_BATCH_FINE_FRONTIER_MIN_RESOLUTION_MARGIN_MICROS as f64)
        as u64;
    let overlap_tolerance_ms = u64::try_from(ALIGNMENT_V2_GLOBAL_OVERLAP_TOLERANCE_MS)
        .map_err(|_| "fine frontier overlap tolerance 不能为负数。".to_string())?;
    let config = FineFrontierConfig {
        resolution_margin_micros,
        overlap_tolerance_ms,
        ..FineFrontierConfig::default()
    };
    let mut mandatory_seed_candidate_ids = mandatory_seed_by_target
        .into_values()
        .map(|(_, id)| id)
        .collect::<Vec<_>>();
    mandatory_seed_candidate_ids.sort_unstable();
    Ok((
        inventory,
        bindings,
        mandatory_seed_candidate_ids,
        V2FineInventoryEvidence {
            candidates: inventory_candidates,
            digest: inventory_digest,
        },
        config,
    ))
}

fn create_v2_fine_inventory_digest(
    inventory_candidates: &[AudioAlignmentBatchFineInventoryCandidateSnapshot],
) -> Result<String, String> {
    let canonical = canonicalize_v2_cross_language_json(
        &serde_json::to_value(inventory_candidates)
            .map_err(|_| "fine frontier inventory 无法序列化。".to_string())?,
    )?;
    Ok(v2_domain_separated_canonical_digest(
        AUDIO_ALIGNMENT_BATCH_FINE_INVENTORY_DIGEST_DOMAIN,
        &canonical,
    ))
}

fn audio_alignment_batch_fine_assignment_snapshot(
    assignment: &ExactAssignment,
) -> AudioAlignmentBatchFineAssignmentSnapshot {
    AudioAlignmentBatchFineAssignmentSnapshot {
        candidate_ids: assignment
            .candidate_ids
            .iter()
            .copied()
            .map(Into::into)
            .collect(),
        total_score_micros: assignment.total_score_micros,
    }
}

fn audio_alignment_batch_fine_omitted_snapshot(
    assignment: &OptimisticOmittedAssignment,
) -> AudioAlignmentBatchFineOmittedAssignmentSnapshot {
    AudioAlignmentBatchFineOmittedAssignmentSnapshot {
        candidate_ids: assignment
            .candidate_ids
            .iter()
            .copied()
            .map(Into::into)
            .collect(),
        total_upper_bound_micros: assignment.total_upper_bound_micros,
        open_candidate_ids: assignment
            .open_candidate_ids
            .iter()
            .copied()
            .map(Into::into)
            .collect(),
        unresolved_candidate_ids: assignment
            .unresolved_candidate_ids
            .iter()
            .copied()
            .map(Into::into)
            .collect(),
        blocked_candidate_ids: assignment
            .blocked_candidate_ids
            .iter()
            .copied()
            .map(Into::into)
            .collect(),
    }
}

fn audio_alignment_batch_fine_state_counts(
    inventory: &FineCandidateInventory,
) -> AudioAlignmentBatchFineStateCountsSnapshot {
    let mut counts = AudioAlignmentBatchFineStateCountsSnapshot::default();
    for candidate in &inventory.candidates {
        match candidate.state {
            FineEvaluationState::Unresolved => counts.unresolved += 1,
            FineEvaluationState::Scored { .. } => counts.scored += 1,
            FineEvaluationState::EvaluatedIneligible => counts.evaluated_ineligible += 1,
            FineEvaluationState::EvidenceBlocked => counts.evidence_blocked += 1,
            FineEvaluationState::ResourceBlocked => counts.resource_blocked += 1,
            FineEvaluationState::InfrastructureFailed => counts.infrastructure_failed += 1,
            FineEvaluationState::Cancelled => counts.cancelled += 1,
        }
    }
    counts
}

fn audio_alignment_batch_fine_limits_snapshot(
    config: FineFrontierConfig,
) -> AudioAlignmentBatchFineLimitsSnapshot {
    AudioAlignmentBatchFineLimitsSnapshot {
        max_candidates: config.limits.max_candidates,
        max_search_states: config.limits.max_search_states,
        max_search_expansions: config.limits.max_search_expansions,
        max_interval_comparisons: config.limits.max_interval_comparisons,
        max_intervals_per_axis: config.limits.max_intervals_per_axis,
        max_total_intervals: config.limits.max_total_intervals,
        refinement_batch_size: config.limits.refinement_batch_size,
    }
}

fn v2_domain_separated_canonical_digest(domain: &str, canonical_json: &str) -> String {
    let mut bytes = Vec::with_capacity(domain.len() + 1 + canonical_json.len());
    bytes.extend_from_slice(domain.as_bytes());
    bytes.push(b'\n');
    bytes.extend_from_slice(canonical_json.as_bytes());
    format!("sha256:{}", sha256_alignment_benchmark_bytes(&bytes))
}

fn canonicalize_v2_cross_language_json(value: &serde_json::Value) -> Result<String, String> {
    fn normalize(value: &serde_json::Value) -> Result<serde_json::Value, String> {
        match value {
            serde_json::Value::Null | serde_json::Value::Bool(_) | serde_json::Value::String(_) => {
                Ok(value.clone())
            }
            serde_json::Value::Number(number) => {
                if number
                    .as_u64()
                    .is_some_and(|value| value > AUDIO_ALIGNMENT_BATCH_V3_MAX_SAFE_INTEGER)
                    || number.as_i64().is_some_and(|value| {
                        value.unsigned_abs() > AUDIO_ALIGNMENT_BATCH_V3_MAX_SAFE_INTEGER
                    })
                {
                    return Err(
                        "alignment evidence v3 JSON integer 超过 JavaScript MAX_SAFE_INTEGER。"
                            .to_string(),
                    );
                }
                let value = number
                    .as_f64()
                    .filter(|value| value.is_finite())
                    .ok_or_else(|| {
                        "alignment evidence v3 JSON number 不是有限 f64。".to_string()
                    })?;
                if value.fract() == 0.0
                    && value.abs() > AUDIO_ALIGNMENT_BATCH_V3_MAX_SAFE_INTEGER as f64
                {
                    return Err(
                        "alignment evidence v3 整数型 f64 超过 JavaScript MAX_SAFE_INTEGER。"
                            .to_string(),
                    );
                }
                Ok(serde_json::Value::String(format!(
                    "f64:{:016x}",
                    value.to_bits()
                )))
            }
            serde_json::Value::Array(values) => values
                .iter()
                .map(normalize)
                .collect::<Result<Vec<_>, _>>()
                .map(serde_json::Value::Array),
            serde_json::Value::Object(values) => values
                .iter()
                .map(|(key, value)| Ok((key.clone(), normalize(value)?)))
                .collect::<Result<serde_json::Map<_, _>, String>>()
                .map(serde_json::Value::Object),
        }
    }
    canonicalize_alignment_benchmark_json(&normalize(value)?)
}

fn seal_audio_alignment_batch_fine_frontier_receipt(
    mut receipt: AudioAlignmentBatchFineFrontierReceiptSnapshot,
) -> Result<AudioAlignmentBatchFineFrontierReceiptSnapshot, String> {
    receipt.receipt_digest.clear();
    let canonical = canonicalize_v2_cross_language_json(
        &serde_json::to_value(&receipt)
            .map_err(|_| "fine frontier receipt 无法序列化。".to_string())?,
    )?;
    receipt.receipt_digest = v2_domain_separated_canonical_digest(
        AUDIO_ALIGNMENT_BATCH_FINE_FRONTIER_RECEIPT_DIGEST_DOMAIN,
        &canonical,
    );
    Ok(receipt)
}

fn create_audio_alignment_batch_fine_frontier_receipt(
    component_ordinal: usize,
    plan: &PlannedAudioAlignmentBatch,
    inventory_candidates: &[AudioAlignmentBatchFineInventoryCandidateSnapshot],
    resolution: &V2FineComponentResolution,
) -> Result<AudioAlignmentBatchFineFrontierReceiptSnapshot, String> {
    let final_state = match resolution.outcome.state {
        CoreFineFrontierState::Resolved => AudioAlignmentBatchFineFrontierStateSnapshot::Resolved,
        CoreFineFrontierState::NoEligibleCandidate => {
            AudioAlignmentBatchFineFrontierStateSnapshot::NoEligibleCandidate
        }
        CoreFineFrontierState::Pending | CoreFineFrontierState::Unresolved => {
            AudioAlignmentBatchFineFrontierStateSnapshot::Unresolved
        }
    };
    let resolved = resolution.outcome.state == CoreFineFrontierState::Resolved;
    let selected_candidate_ids = if resolved {
        resolution
            .outcome
            .best_completed
            .candidate_ids
            .iter()
            .copied()
            .map(Into::into)
            .collect()
    } else {
        Vec::new()
    };
    let component_pair_ordinals = resolution
        .pair_indices
        .iter()
        .map(|pair_index| {
            plan.pairs
                .get(*pair_index)
                .map(|pair| pair.pair_ordinal)
                .ok_or_else(|| "fine frontier receipt pair 索引越界。".to_string())
        })
        .collect::<Result<Vec<_>, _>>()?;
    seal_audio_alignment_batch_fine_frontier_receipt(
        AudioAlignmentBatchFineFrontierReceiptSnapshot {
            contract_version: FINE_FRONTIER_CONTRACT_VERSION,
            score_version: AUDIO_ALIGNMENT_BATCH_FINE_SCORE_VERSION,
            inventory_digest: resolution.inventory_digest.clone(),
            inventory_candidates: inventory_candidates.to_vec(),
            receipt_digest: String::new(),
            component_ordinal,
            component_pair_ordinals,
            inventory_candidate_count: resolution.inventory.candidates.len(),
            resolution_margin_micros: resolution.config.resolution_margin_micros,
            overlap_tolerance_ms: resolution.config.overlap_tolerance_ms,
            limits: audio_alignment_batch_fine_limits_snapshot(resolution.config),
            inventory_state_counts: audio_alignment_batch_fine_state_counts(&resolution.inventory),
            refinement_round_count: resolution.refinement_round_count,
            evaluated_candidate_count: resolution.evaluated_candidate_count,
            final_state,
            resolved,
            selected_total_score_micros: resolved
                .then_some(resolution.outcome.best_completed.total_score_micros),
            selected_candidate_ids,
            best_completed: audio_alignment_batch_fine_assignment_snapshot(
                &resolution.outcome.best_completed,
            ),
            runner_up_completed: resolution
                .outcome
                .runner_up_completed
                .as_ref()
                .map(audio_alignment_batch_fine_assignment_snapshot),
            optimistic_omitted: resolution
                .outcome
                .optimistic_omitted
                .as_ref()
                .map(audio_alignment_batch_fine_omitted_snapshot),
            // A terminal adapter receipt never publishes speculative scheduler work. The core
            // computes the batch before deciding that an already-completed assignment proves
            // resolution, so its internal terminal outcome may still carry now-unneeded IDs.
            next_refinement_candidate_ids: Vec::new(),
            deferred_candidate_count: 0,
            proof: AudioAlignmentBatchFineResolutionProofSnapshot {
                beats_runner_up_with_margin: resolution.outcome.proof.beats_runner_up_with_margin,
                beats_optimistic_omitted_with_margin: resolution
                    .outcome
                    .proof
                    .beats_optimistic_omitted_with_margin,
            },
            search: AudioAlignmentBatchFineSearchSnapshot {
                states_visited: resolution.outcome.search.states_visited,
                expansions_considered: resolution.outcome.search.expansions_considered,
                interval_comparisons: resolution.outcome.search.interval_comparisons,
            },
        },
    )
}

fn create_failed_audio_alignment_batch_fine_frontier_receipt(
    component_ordinal: usize,
    plan: &PlannedAudioAlignmentBatch,
    pair_indices: &[usize],
    inventory: &FineCandidateInventory,
    inventory_evidence: &V2FineInventoryEvidence,
    config: FineFrontierConfig,
    progress: V2FineFrontierFailureProgress,
) -> Result<AudioAlignmentBatchFineFrontierReceiptSnapshot, String> {
    let component_pair_ordinals = pair_indices
        .iter()
        .map(|pair_index| {
            plan.pairs
                .get(*pair_index)
                .map(|pair| pair.pair_ordinal)
                .ok_or_else(|| "failed fine receipt pair 索引越界。".to_string())
        })
        .collect::<Result<Vec<_>, _>>()?;
    seal_audio_alignment_batch_fine_frontier_receipt(
        AudioAlignmentBatchFineFrontierReceiptSnapshot {
            contract_version: FINE_FRONTIER_CONTRACT_VERSION,
            score_version: AUDIO_ALIGNMENT_BATCH_FINE_SCORE_VERSION,
            inventory_digest: inventory_evidence.digest.clone(),
            inventory_candidates: inventory_evidence.candidates.clone(),
            receipt_digest: String::new(),
            component_ordinal,
            component_pair_ordinals,
            inventory_candidate_count: inventory.candidates.len(),
            resolution_margin_micros: config.resolution_margin_micros,
            overlap_tolerance_ms: config.overlap_tolerance_ms,
            limits: audio_alignment_batch_fine_limits_snapshot(config),
            inventory_state_counts: audio_alignment_batch_fine_state_counts(inventory),
            refinement_round_count: progress.refinement_round_count,
            evaluated_candidate_count: progress.evaluated_candidate_count,
            final_state: AudioAlignmentBatchFineFrontierStateSnapshot::Failed,
            resolved: false,
            selected_candidate_ids: Vec::new(),
            selected_total_score_micros: None,
            best_completed: AudioAlignmentBatchFineAssignmentSnapshot {
                candidate_ids: Vec::new(),
                total_score_micros: 0,
            },
            runner_up_completed: None,
            optimistic_omitted: None,
            next_refinement_candidate_ids: Vec::new(),
            deferred_candidate_count: 0,
            proof: AudioAlignmentBatchFineResolutionProofSnapshot {
                beats_runner_up_with_margin: false,
                beats_optimistic_omitted_with_margin: false,
            },
            search: AudioAlignmentBatchFineSearchSnapshot {
                states_visited: progress.search.states_visited,
                expansions_considered: progress.search.expansions_considered,
                interval_comparisons: progress.search.interval_comparisons,
            },
        },
    )
}

fn audio_alignment_batch_spectral_backend_identity(
    backend: &SpectralBackendExecution,
) -> AudioAlignmentBatchSpectralBackendIdentitySnapshot {
    AudioAlignmentBatchSpectralBackendIdentitySnapshot {
        backend_id: backend.backend_id.clone(),
        requested_backend: backend.requested_backend.clone(),
        backend_detail: backend.backend_detail.clone(),
        fallback_reason: backend.fallback_reason.clone(),
    }
}

fn v2_fine_decode_window_snapshot(
    range: PresentationRangeMs,
) -> Result<AudioAlignmentBatchFineDecodeWindowSnapshot, String> {
    if range.end_ms <= range.start_ms {
        return Err("fine execution decode window 不能为空。".to_string());
    }
    let duration_ms = u64::try_from(range.end_ms - range.start_ms)
        .map_err(|_| "fine execution decode window 时长无法表示。".to_string())?;
    let expected_sample_count = duration_ms
        .checked_mul(u64::from(ALIGNMENT_V2_SAMPLE_RATE))
        .ok_or_else(|| "fine execution expected sample count 溢出。".to_string())?
        .div_ceil(1_000);
    Ok(AudioAlignmentBatchFineDecodeWindowSnapshot {
        start_ms: range.start_ms,
        end_ms: range.end_ms,
        presentation_offset_ms: range.start_ms,
        sample_rate: ALIGNMENT_V2_SAMPLE_RATE,
        expected_sample_count,
        actual_decoded_sample_count: None,
    })
}

fn v2_fine_effective_decode_window_snapshot(
    requested_range: PresentationRangeMs,
    presentation_offset_ms: i64,
    actual_decoded_sample_count: u64,
) -> Result<AudioAlignmentBatchFineDecodeWindowSnapshot, String> {
    let mut snapshot = v2_fine_decode_window_snapshot(requested_range)?;
    let decoded_duration_ms = actual_decoded_sample_count
        .checked_mul(1_000)
        .ok_or_else(|| "fine effective decoded duration 溢出。".to_string())?
        .div_ceil(u64::from(ALIGNMENT_V2_SAMPLE_RATE));
    let decoded_duration_ms = i64::try_from(decoded_duration_ms)
        .map_err(|_| "fine effective decoded duration 无法表示。".to_string())?;
    snapshot.start_ms = presentation_offset_ms;
    snapshot.end_ms = presentation_offset_ms
        .checked_add(decoded_duration_ms)
        .ok_or_else(|| "fine effective decoded end 溢出。".to_string())?;
    snapshot.presentation_offset_ms = presentation_offset_ms;
    snapshot.expected_sample_count = u64::try_from(decoded_duration_ms)
        .map_err(|_| "fine effective rounded duration 不能为负数。".to_string())?
        .checked_mul(u64::from(ALIGNMENT_V2_SAMPLE_RATE))
        .ok_or_else(|| "fine effective expected sample count 溢出。".to_string())?
        .div_ceil(1_000);
    snapshot.actual_decoded_sample_count = Some(actual_decoded_sample_count);
    Ok(snapshot)
}

fn v2_fine_occupancy_digest(occupancy: &PairPhysicalOccupancy) -> Result<String, String> {
    let value = serde_json::json!({
        "source": {
            "spaceOrdinal": occupancy.source.space_ordinal,
            "reuseGroupOrdinal": occupancy.source.reuse_group_ordinal,
            "intervals": occupancy.source.intervals.iter().map(|interval| {
                serde_json::json!({"startMs": interval.start_ms, "endMs": interval.end_ms})
            }).collect::<Vec<_>>()
        },
        "target": {
            "spaceOrdinal": occupancy.target.space_ordinal,
            "reuseGroupOrdinal": occupancy.target.reuse_group_ordinal,
            "intervals": occupancy.target.intervals.iter().map(|interval| {
                serde_json::json!({"startMs": interval.start_ms, "endMs": interval.end_ms})
            }).collect::<Vec<_>>()
        }
    });
    let canonical = canonicalize_v2_cross_language_json(&value)?;
    Ok(v2_domain_separated_canonical_digest(
        AUDIO_ALIGNMENT_BATCH_FINE_OCCUPANCY_DIGEST_DOMAIN,
        &canonical,
    ))
}

fn v2_fine_time_map_digest(proposal: &AudioAlignmentProposal) -> Result<String, String> {
    let time_map = proposal
        .time_map
        .as_ref()
        .ok_or_else(|| "fine execution evidence 缺少 proposal TimeMap。".to_string())?;
    let canonical = canonicalize_v2_cross_language_json(
        &serde_json::to_value(time_map)
            .map_err(|_| "fine proposal TimeMap 无法序列化。".to_string())?,
    )?;
    Ok(v2_domain_separated_canonical_digest(
        AUDIO_ALIGNMENT_BATCH_FINE_TIME_MAP_DIGEST_DOMAIN,
        &canonical,
    ))
}

fn v2_fine_parameters_digest(time_map: &AudioAlignmentTimeMapDto) -> Result<String, String> {
    let value = serde_json::json!({
        "engineVersion": ALIGNMENT_V2_ENGINE_VERSION,
        "featureVersion": ALIGNMENT_V2_FEATURE_VERSION,
        "fineScoreVersion": AUDIO_ALIGNMENT_BATCH_FINE_SCORE_VERSION,
        "legacyParametersHash": time_map.parameters_hash,
    });
    let canonical = canonicalize_v2_cross_language_json(&value)?;
    Ok(v2_domain_separated_canonical_digest(
        AUDIO_ALIGNMENT_BATCH_FINE_PARAMETERS_DIGEST_DOMAIN,
        &canonical,
    ))
}

fn seal_audio_alignment_batch_fine_execution_evidence(
    mut evidence: AudioAlignmentBatchFineExecutionEvidenceSnapshot,
) -> Result<AudioAlignmentBatchFineExecutionEvidenceSnapshot, String> {
    evidence.evidence_digest.clear();
    let canonical = canonicalize_v2_cross_language_json(
        &serde_json::to_value(&evidence)
            .map_err(|_| "fine execution evidence 无法序列化。".to_string())?,
    )?;
    evidence.evidence_digest = v2_domain_separated_canonical_digest(
        AUDIO_ALIGNMENT_BATCH_FINE_EXECUTION_DIGEST_DOMAIN,
        &canonical,
    );
    Ok(evidence)
}

fn create_audio_alignment_batch_fine_execution_evidence(
    input: V2FineExecutionEvidenceInput<'_>,
) -> Result<AudioAlignmentBatchFineExecutionEvidenceSnapshot, String> {
    let V2FineExecutionEvidenceInput {
        id,
        binding,
        selected_member_index,
        candidate,
        source_artifact,
        target_artifact,
        runtime,
        proposal,
        score,
        occupancy,
    } = input;
    let source_requested_range = runtime
        .decode_plan
        .map(|plan| plan.windows.source)
        .unwrap_or(source_artifact.presentation_bounds);
    let target_requested_range = runtime
        .decode_plan
        .map(|plan| plan.windows.target)
        .unwrap_or(target_artifact.presentation_bounds);
    let source_requested_window = v2_fine_decode_window_snapshot(source_requested_range)?;
    let target_requested_window = v2_fine_decode_window_snapshot(target_requested_range)?;
    let source_effective_window = v2_fine_effective_decode_window_snapshot(
        source_requested_range,
        runtime.source_presentation_offset_ms,
        runtime.source_decoded_sample_count,
    )?;
    let target_effective_window = v2_fine_effective_decode_window_snapshot(
        target_requested_range,
        runtime.target_presentation_offset_ms,
        runtime.target_decoded_sample_count,
    )?;
    let time_map = proposal
        .time_map
        .as_ref()
        .ok_or_else(|| "fine execution evidence 缺少 proposal TimeMap。".to_string())?;
    seal_audio_alignment_batch_fine_execution_evidence(
        AudioAlignmentBatchFineExecutionEvidenceSnapshot {
            candidate_id: id.into(),
            selected_member_rank: selected_member_index + 1,
            group_member_ranks: binding
                .member_indices
                .iter()
                .map(|index| index + 1)
                .collect(),
            source_stream_index: candidate.source_input.stream.stream_index,
            target_stream_index: candidate.target_input.stream.stream_index,
            source_coarse_backend: audio_alignment_batch_spectral_backend_identity(
                &source_artifact.spectral_backend,
            ),
            target_coarse_backend: audio_alignment_batch_spectral_backend_identity(
                &target_artifact.spectral_backend,
            ),
            source_fine_backend: audio_alignment_batch_spectral_backend_identity(
                &runtime.source_fine_backend,
            ),
            target_fine_backend: audio_alignment_batch_spectral_backend_identity(
                &runtime.target_fine_backend,
            ),
            source_requested_window,
            target_requested_window,
            source_effective_window,
            target_effective_window,
            parameters_hash: v2_fine_parameters_digest(time_map)?,
            occupancy_digest: v2_fine_occupancy_digest(occupancy)?,
            proposal_time_map_digest: v2_fine_time_map_digest(proposal)?,
            score_micros: u64::from(score.get()),
            evidence_digest: String::new(),
        },
    )
}

fn v2_global_candidate_conflicts_with_state(
    plan: &PlannedAudioAlignmentBatch,
    coarse: &[&V2PairCoarseCandidates],
    state: &V2GlobalAssignmentState,
    pair_index: usize,
    candidate_index: usize,
) -> bool {
    state
        .choices
        .iter()
        .enumerate()
        .filter_map(|(selected_pair_index, selected_candidate_index)| {
            selected_candidate_index.map(|candidate_index| (selected_pair_index, candidate_index))
        })
        .any(|(selected_pair_index, selected_candidate_index)| {
            v2_global_candidates_conflict(
                &plan.pairs[pair_index],
                &coarse[pair_index].candidates[candidate_index],
                &plan.pairs[selected_pair_index],
                &coarse[selected_pair_index].candidates[selected_candidate_index],
            )
        })
}

fn v2_global_candidates_conflict(
    left_pair: &PlannedAudioAlignmentBatchPair,
    left: &V2TrackPairCandidate,
    right_pair: &PlannedAudioAlignmentBatchPair,
    right: &V2TrackPairCandidate,
) -> bool {
    (left_pair.source_physical_media_index == right_pair.source_physical_media_index
        && !v2_version_reuse_allows_shared_axis(
            left_pair.source_axis_reuse_group_ordinal,
            right_pair.source_axis_reuse_group_ordinal,
            left_pair.target_physical_media_index,
            right_pair.target_physical_media_index,
        )
        && v2_coarse_intervals_conflict(
            (
                left.global_source_interval.start_ms,
                left.global_source_interval.end_ms,
            ),
            (
                right.global_source_interval.start_ms,
                right.global_source_interval.end_ms,
            ),
        ))
        || (left_pair.target_physical_media_index == right_pair.target_physical_media_index
            && !v2_version_reuse_allows_shared_axis(
                left_pair.target_axis_reuse_group_ordinal,
                right_pair.target_axis_reuse_group_ordinal,
                left_pair.source_physical_media_index,
                right_pair.source_physical_media_index,
            )
            && v2_coarse_intervals_conflict(
                (
                    left.global_target_interval.start_ms,
                    left.global_target_interval.end_ms,
                ),
                (
                    right.global_target_interval.start_ms,
                    right.global_target_interval.end_ms,
                ),
            ))
}

fn v2_version_reuse_allows_shared_axis(
    left_group: Option<u32>,
    right_group: Option<u32>,
    left_opposite_physical_media_index: usize,
    right_opposite_physical_media_index: usize,
) -> bool {
    left_group.is_some_and(|group| {
        right_group == Some(group)
            && left_opposite_physical_media_index != right_opposite_physical_media_index
    })
}

fn probe_alignment_audio_candidates(
    media_path: &str,
    label: &str,
    requested_stream_index: Option<u32>,
    options: &AudioAlignmentOptions,
    cancel_flag: Option<&AtomicBool>,
) -> Result<Vec<AlignmentAudioInput>, String> {
    probe_alignment_audio_candidates_with_diagnostics(
        media_path,
        label,
        requested_stream_index,
        options,
        cancel_flag,
        &mut |_stage_key, _duration_ms, _message| Ok(()),
    )
}

fn probe_alignment_audio_candidates_with_diagnostics<F>(
    media_path: &str,
    label: &str,
    requested_stream_index: Option<u32>,
    options: &AudioAlignmentOptions,
    cancel_flag: Option<&AtomicBool>,
    diagnostics: &mut F,
) -> Result<Vec<AlignmentAudioInput>, String>
where
    F: FnMut(&str, Option<u64>, &str) -> Result<(), String>,
{
    diagnostics(
        "media.timeline-probe",
        None,
        "开始核验媒体身份并读取容器、音轨和展示时间线。",
    )?;
    let timeline_started_at = Instant::now();
    let snapshot = probe_media_timeline_with_ffprobe_cancellable(
        media_path,
        &options.ffprobe_path,
        cancel_flag,
    )
    .map_err(|error| format_alignment_probe_error(&format!("{label}媒体时间线探测失败"), error))?;
    diagnostics(
        "media.timeline-probe",
        Some(u64::try_from(timeline_started_at.elapsed().as_millis()).unwrap_or(u64::MAX)),
        "媒体身份与容器时间线读取完成。",
    )?;
    check_v2_coarse_probe_duration(snapshot.duration_ms, label)?;
    diagnostics(
        "media.audio-pts-probe",
        None,
        "开始扫描音频 frame/packet PTS 与 skip-sample 证据。",
    )?;
    let pts_started_at = Instant::now();
    let decode_timelines = probe_audio_decode_timelines_with_ffprobe_cancellable(
        media_path,
        &options.ffprobe_path,
        snapshot.content_identity.as_ref().ok_or_else(|| {
            format!(
                "blocked:media-identity-missing：{label}媒体时间线缺少全文件身份，Alignment V2 已阻断。"
            )
        })?,
        cancel_flag,
    )
    .map_err(|error| {
        format_alignment_probe_error(&format!("{label}逐帧 PTS/skip-sample 探测失败"), error)
    })?;
    diagnostics(
        "media.audio-pts-probe",
        Some(u64::try_from(pts_started_at.elapsed().as_millis()).unwrap_or(u64::MAX)),
        "音频 PTS 与 skip-sample 扫描完成。",
    )?;
    if let Some(stream_index) = requested_stream_index {
        let stream = select_audio_stream(&snapshot, Some(stream_index), label)?;
        let decode_timeline = decode_timelines
            .get(&stream.stream_index)
            .cloned()
            .ok_or_else(|| {
                format!(
                    "{label}音轨 #{} 没有可复核的逐帧 PTS 证据，Alignment V2 已阻断。",
                    stream.stream_index
                )
            })?;
        return Ok(vec![alignment_audio_input_from_snapshot(
            &snapshot,
            stream,
            true,
            Some(decode_timeline),
        )]);
    }
    let mut streams = snapshot
        .audio_streams
        .iter()
        .filter(|stream| !stream.is_commentary && stream.timeline_offset_ms >= 0)
        .cloned()
        .collect::<Vec<_>>();
    streams.sort_by(|left, right| {
        right
            .is_default
            .cmp(&left.is_default)
            .then_with(|| right.channels.unwrap_or(0).cmp(&left.channels.unwrap_or(0)))
            .then_with(|| left.stream_index.cmp(&right.stream_index))
    });
    if streams.len() > ALIGNMENT_V2_MAX_UNSELECTED_STREAMS {
        return Err(format!(
            "blocked:resource-limit：{label}有 {} 条非 commentary 候选音轨，超过自动内容评分硬上限 {}；请显式选择音轨后重试，系统不会按 default/声道数提前截断。",
            streams.len(), ALIGNMENT_V2_MAX_UNSELECTED_STREAMS
        ));
    }
    streams
        .into_iter()
        .map(|stream| {
            let decode_timeline = decode_timelines
                .get(&stream.stream_index)
                .cloned()
                .ok_or_else(|| {
                    format!(
                        "{label}音轨 #{} 没有可复核的逐帧 PTS 证据，Alignment V2 已阻断。",
                        stream.stream_index
                    )
                })?;
            Ok(alignment_audio_input_from_snapshot(
                &snapshot,
                stream,
                false,
                Some(decode_timeline),
            ))
        })
        .collect()
}

fn check_v2_coarse_probe_duration(duration_ms: Option<u64>, label: &str) -> Result<(), String> {
    // Long media are intentionally admitted to the bounded streaming coarse stage. The
    // one-hour full-PCM limit is enforced only when a selected candidate enters fine alignment;
    // rejecting it here would make the streaming path unreachable from the production entry.
    if duration_ms.is_some_and(|duration| duration > ALIGNMENT_V2_COARSE_MAX_DURATION_MS) {
        return Err(format!(
            "blocked:resource-limit：{label}时长超过流式粗定位当前 {} 小时上限。",
            ALIGNMENT_V2_COARSE_MAX_DURATION_MS / (60 * 60 * 1_000)
        ));
    }
    Ok(())
}

fn alignment_audio_input_from_snapshot(
    snapshot: &MediaProbeSnapshot,
    stream: AudioStreamProbe,
    explicit_stream_selection: bool,
    decode_timeline: Option<AudioDecodeTimelineProbe>,
) -> AlignmentAudioInput {
    AlignmentAudioInput {
        presentation_origin_ms: snapshot.presentation_origin_ms,
        media_duration_ms: snapshot.duration_ms.or(stream.duration_ms),
        content_identity: snapshot.content_identity.clone(),
        decode_timeline,
        audio_stream_count: snapshot.audio_streams.len(),
        explicit_stream_selection,
        stream,
    }
}

fn is_reasonable_audio_stream_pair(
    source: &AlignmentAudioInput,
    target: &AlignmentAudioInput,
) -> bool {
    !source.stream.is_commentary && !target.stream.is_commentary
}

fn normalized_stream_language(language: Option<&str>) -> Option<String> {
    let normalized = language?
        .trim()
        .to_ascii_lowercase()
        .split(['-', '_'])
        .next()
        .unwrap_or_default()
        .to_string();
    if normalized.is_empty() || matches!(normalized.as_str(), "und" | "unknown" | "mul") {
        None
    } else {
        Some(
            match normalized.as_str() {
                "ja" | "jpn" => "ja",
                "zh" | "zho" | "chi" => "zh",
                "en" | "eng" => "en",
                "de" | "deu" | "ger" => "de",
                "fr" | "fra" | "fre" => "fr",
                "es" | "spa" => "es",
                "it" | "ita" => "it",
                "ko" | "kor" => "ko",
                "ru" | "rus" => "ru",
                "pt" | "por" => "pt",
                "ar" | "ara" => "ar",
                other => other,
            }
            .to_string(),
        )
    }
}

fn v2_normalized_pcm_origin_ms(input: &AlignmentAudioInput) -> i64 {
    input
        .decode_timeline
        .as_ref()
        .map(|item| item.normalized_pcm_origin_ms)
        .unwrap_or(0)
}

fn format_v2_decode_timeline_diagnostic(label: &str, input: &AlignmentAudioInput) -> String {
    let Some(timeline) = input.decode_timeline.as_ref() else {
        return format!("{label}缺少逐帧 PTS/skip-sample 证据。");
    };
    format!(
        "{label}音轨 #{}：first decoded PTS {:?} ms，PTS discontinuity {} 次，max gap {:?} ms，skip/discard samples={}/{}, normalized PCM origin {} ms。",
        input.stream.stream_index,
        timeline.first_decoded_pts_ms,
        timeline.pts_discontinuity_count,
        timeline.max_pts_gap_ms,
        timeline.skip_samples,
        timeline.discard_padding,
        timeline.normalized_pcm_origin_ms
    )
}

fn v2_language_pair_prior(source: &AlignmentAudioInput, target: &AlignmentAudioInput) -> f64 {
    match (
        normalized_stream_language(source.stream.language.as_deref()),
        normalized_stream_language(target.stream.language.as_deref()),
    ) {
        (Some(source), Some(target)) if source == target => 0.02,
        (Some(_), Some(_)) => -0.02,
        _ => 0.0,
    }
}

// These arguments deliberately keep media identity, cancellation and memory-accounting
// boundaries visible at the extraction call site.
#[allow(clippy::too_many_arguments)]
fn extract_v2_landmark_candidates(
    media_path: &str,
    label: &str,
    options: &AudioAlignmentOptions,
    inputs: &[AlignmentAudioInput],
    cancel_flag: Option<&AtomicBool>,
    prebuilt_cache_plan: Option<V2CandidateSetCachePlan>,
    identity_guard: Option<&Arc<PinnedMediaIdentityGuard>>,
    state: &mut V2CandidateExtractionState<'_>,
) -> Result<HashMap<u32, CachedV2Landmarks>, String> {
    // Snapshot every warm artifact as an Arc-backed plan before extraction. Cache hits are charged
    // by their actual retained payload and remain reusable even if a later miss evicts their LRU
    // entry; only misses reserve a decode/analysis phase peak.
    let cache_plan = match prebuilt_cache_plan {
        Some(plan) => {
            if plan.candidates.len() != inputs.len() {
                return Err(
                    "blocked:resource-limit：预建 coarse 缓存计划与候选音轨数量不一致。"
                        .to_string(),
                );
            }
            if *state.retained_artifact_bytes > plan.planned_baseline_bytes {
                return Err(
                    "blocked:resource-limit：执行时驻留制品已超过预建 coarse 缓存计划基线。"
                        .to_string(),
                );
            }
            plan
        }
        None => plan_v2_candidate_set_cache_aware(
            media_path,
            options,
            inputs,
            &state.spectral_backend_request.planned_backend_id,
            *state.retained_artifact_bytes,
        )?,
    };
    let mut output = HashMap::new();
    for (input, candidate_plan) in inputs.iter().zip(cache_plan.candidates) {
        match get_v2_landmarks(
            media_path,
            label,
            options,
            input,
            V2LandmarkExtractionContext {
                cancel_flag,
                shared_backend_request: Some(state.spectral_backend_request),
                cache_plan: Some(candidate_plan),
                retained_artifact_bytes: *state.retained_artifact_bytes,
                identity_guard: identity_guard.cloned(),
            },
        ) {
            Ok(artifact) if !artifact.landmarks.is_empty() => {
                let artifact_bytes = cached_v2_landmark_retained_bytes(&artifact);
                let next_retained_bytes = ensure_v2_active_artifact_budget(
                    *state.retained_artifact_bytes,
                    artifact_bytes,
                )?;
                *state.retained_artifact_bytes = next_retained_bytes;
                state.notes.push(format!(
                    "{label}音轨 #{} landmark {}：{} 个；声谱后端 {}（{}）。",
                    input.stream.stream_index,
                    artifact.cache_origin.label(),
                    artifact.landmarks.len(),
                    artifact.spectral_backend.backend_id,
                    artifact.spectral_backend.backend_detail
                ));
                if let Some(reason) = &artifact.spectral_backend.fallback_reason {
                    state.notes.push(format!(
                        "{label}音轨 #{} 声谱后端说明：{reason}",
                        input.stream.stream_index
                    ));
                }
                if let Some(error) = &artifact.cache_persistence_error {
                    state.notes.push(format!(
                        "{label}音轨 #{} 的磁盘粗索引未写入：{error}",
                        input.stream.stream_index
                    ));
                }
                output.insert(input.stream.stream_index, artifact);
            }
            Ok(_) => state.notes.push(format!(
                "{label}音轨 #{} 只有静音或重复性过高，未得到可用 landmark。",
                input.stream.stream_index
            )),
            Err(error) => {
                propagate_alignment_process_cleanup(&error)?;
                if is_media_identity_guard_error(&error)
                    || error == AUDIO_ALIGNMENT_CANCELLED
                    || error.starts_with("blocked:resource-limit")
                    || error.starts_with("blocked:cuda-fft")
                {
                    return Err(error);
                }
                state.notes.push(format!(
                    "{label}音轨 #{} landmark 提取失败：{error}",
                    input.stream.stream_index
                ));
            }
        }
    }
    Ok(output)
}

fn check_v2_duration_limit(input: &AlignmentAudioInput, label: &str) -> Result<(), String> {
    let Some(duration_ms) = input.media_duration_ms else {
        return Err(format!(
            "blocked:resource-limit：{label}时长未知，只允许进入有界流式粗定位；当前不能安全执行完整 PCM 细对齐。"
        ));
    };
    if duration_ms > ALIGNMENT_V2_MAX_DURATION_MS {
        return Err(format!(
            "blocked:resource-limit：{label}时长超过 Alignment V2 当前 {} 分钟的单次 PCM 上限。",
            ALIGNMENT_V2_MAX_DURATION_MS / 60_000
        ));
    }
    Ok(())
}

fn v2_pcm_bytes_for_duration_ms(duration_ms: u64) -> Option<usize> {
    let samples = (duration_ms as u128)
        .checked_mul(ALIGNMENT_V2_SAMPLE_RATE as u128)?
        .checked_add(999)?
        / 1_000;
    let bytes = samples.checked_mul(std::mem::size_of::<i16>() as u128)?;
    usize::try_from(bytes).ok()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct V2PcmDecodeBudget {
    duration_budget_ms: u64,
    stdout_hard_limit_bytes: usize,
}

fn v2_short_pcm_decode_budget(input: &AlignmentAudioInput) -> Result<V2PcmDecodeBudget, String> {
    let container_duration_ms = input.media_duration_ms.ok_or_else(|| {
        "blocked:resource-limit：短媒体完整 PCM 解码要求已知容器时长。".to_string()
    })?;
    if container_duration_ms > ALIGNMENT_V2_MAX_DURATION_MS {
        return Err("blocked:resource-limit：长媒体不能使用短媒体完整 PCM 解码预算。".to_string());
    }
    let probed_duration_ms = input
        .stream
        .duration_ms
        .unwrap_or(container_duration_ms)
        .max(container_duration_ms);
    let duration_budget_ms = probed_duration_ms
        .checked_add(ALIGNMENT_V2_SHORT_DECODE_DURATION_SLACK_MS)
        .ok_or_else(|| "blocked:resource-limit：短媒体 PCM 时长预算溢出。".to_string())?
        .min(ALIGNMENT_V2_MAX_DURATION_MS);
    let stdout_hard_limit_bytes = v2_pcm_bytes_for_duration_ms(duration_budget_ms)
        .ok_or_else(|| "blocked:resource-limit：短媒体 PCM stdout 上界无法表示。".to_string())?;
    Ok(V2PcmDecodeBudget {
        duration_budget_ms,
        stdout_hard_limit_bytes,
    })
}

fn v2_fine_window_pcm_decode_budget(
    range: PresentationRangeMs,
) -> Result<V2PcmDecodeBudget, String> {
    let duration_ms = v2_presentation_range_duration_ms(range)?;
    if duration_ms > ALIGNMENT_V2_MAX_DURATION_MS {
        return Err(format!(
            "blocked:resource-limit：精解码窗口超过 {} 分钟硬上限。",
            ALIGNMENT_V2_MAX_DURATION_MS / 60_000
        ));
    }
    let duration_budget_ms = duration_ms
        .checked_add(ALIGNMENT_V2_FINE_WINDOW_DECODE_TOLERANCE_MS)
        .ok_or_else(|| "blocked:resource-limit：精解码 stdout 时长预算溢出。".to_string())?;
    let stdout_hard_limit_bytes = v2_pcm_bytes_for_duration_ms(duration_budget_ms)
        .ok_or_else(|| "blocked:resource-limit：精解码 stdout 字节预算无法表示。".to_string())?;
    Ok(V2PcmDecodeBudget {
        duration_budget_ms,
        stdout_hard_limit_bytes,
    })
}

fn supervised_read_bounded_vec_capacity_upper_bound(hard_limit: usize) -> Result<usize, String> {
    hard_limit
        .checked_mul(2)
        .map(|doubled| doubled.max(SUPERVISED_READ_BOUNDED_INITIAL_CAPACITY_BYTES))
        .ok_or_else(|| "blocked:resource-limit：受监督 reader Vec capacity 上界溢出。".to_string())
}

fn supervised_read_bounded_stderr_capacity_upper_bound() -> Result<usize, String> {
    supervised_read_bounded_vec_capacity_upper_bound(ALIGNMENT_V2_MAX_STDERR_BYTES)
}

fn v2_presentation_bounds_for_samples(
    presentation_offset_ms: i64,
    sample_count: u64,
) -> Result<PresentationRangeMs, String> {
    if sample_count == 0 {
        return Err("细对齐 PCM 没有可表示的 presentation 区间。".to_string());
    }
    let duration_ms = (u128::from(sample_count)
        .checked_mul(1_000)
        .ok_or_else(|| "blocked:resource-limit：PCM presentation 时长溢出。".to_string())?
        .checked_add(u128::from(ALIGNMENT_V2_SAMPLE_RATE - 1))
        .ok_or_else(|| "blocked:resource-limit：PCM presentation 时长溢出。".to_string())?)
        / u128::from(ALIGNMENT_V2_SAMPLE_RATE);
    let duration_ms = i64::try_from(duration_ms)
        .map_err(|_| "blocked:resource-limit：PCM presentation 时长无法表示。".to_string())?;
    let end_ms = presentation_offset_ms
        .checked_add(duration_ms)
        .ok_or_else(|| "blocked:resource-limit：PCM presentation 终点溢出。".to_string())?;
    if end_ms <= presentation_offset_ms {
        return Err("细对齐 PCM presentation 区间为空。".to_string());
    }
    Ok(PresentationRangeMs {
        start_ms: presentation_offset_ms,
        end_ms,
    })
}

fn v2_presentation_range_duration_ms(range: PresentationRangeMs) -> Result<u64, String> {
    let duration = range
        .end_ms
        .checked_sub(range.start_ms)
        .ok_or_else(|| "blocked:resource-limit：精解码窗口时长溢出。".to_string())?;
    u64::try_from(duration)
        .map_err(|_| "blocked:resource-limit：精解码窗口必须是正毫秒区间。".to_string())
        .and_then(|duration| {
            if duration == 0 {
                Err("blocked:resource-limit：精解码窗口不能为空。".to_string())
            } else {
                Ok(duration)
            }
        })
}

fn v2_resource_checked_sum(parts: &[usize], label: &str) -> Result<usize, String> {
    parts.iter().try_fold(0_usize, |total, part| {
        total
            .checked_add(*part)
            .ok_or_else(|| format!("blocked:resource-limit：{label}内存上界溢出。"))
    })
}

fn v2_resource_checked_product(parts: &[usize], label: &str) -> Result<usize, String> {
    parts.iter().try_fold(1_usize, |total, part| {
        total
            .checked_mul(*part)
            .ok_or_else(|| format!("blocked:resource-limit：{label}内存上界溢出。"))
    })
}

fn v2_short_coarse_frame_count_upper_bound(input: &AlignmentAudioInput) -> Result<usize, String> {
    let duration_ms = v2_short_pcm_decode_budget(input)?.duration_budget_ms;
    usize::try_from(
        (duration_ms as u128)
            .checked_add(ALIGNMENT_V2_LANDMARK_HOP_MS as u128 - 1)
            .ok_or_else(|| "blocked:resource-limit：候选帧数溢出。".to_string())?
            / ALIGNMENT_V2_LANDMARK_HOP_MS as u128,
    )
    .map_err(|_| "blocked:resource-limit：候选帧数无法表示。".to_string())
}

fn v2_unsuppressed_landmark_bytes(frame_count: usize) -> Result<usize, String> {
    v2_resource_checked_product(
        &[
            frame_count,
            ALIGNMENT_V2_MAX_SPECTRAL_PEAKS_PER_FRAME,
            ALIGNMENT_V2_LANDMARK_FANOUT,
            std::mem::size_of::<SpectralLandmark>(),
        ],
        "未抑制 landmark",
    )
}

fn v2_fine_feature_bytes(frame_count: usize) -> Result<usize, String> {
    let bytes_per_frame = std::mem::size_of::<FineFeatureFrame>()
        .checked_add(
            ALIGNMENT_V2_FINE_FEATURE_VALUE_COUNT
                .checked_mul(std::mem::size_of::<f32>())
                .ok_or_else(|| {
                    "blocked:resource-limit：fine feature value 上界溢出。".to_string()
                })?,
        )
        .ok_or_else(|| "blocked:resource-limit：fine feature frame 上界溢出。".to_string())?;
    v2_resource_checked_product(&[frame_count, bytes_per_frame], "fine feature")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum V2CoarseBackendBudgetKind {
    Cpu,
    CudaOrHybrid,
}

fn v2_coarse_backend_budget_kind(
    planned_backend_id: &str,
) -> Result<V2CoarseBackendBudgetKind, String> {
    match planned_backend_id {
        CPU_SPECTRAL_BACKEND_ID | STREAMING_CPU_SPECTRAL_BACKEND_ID => {
            Ok(V2CoarseBackendBudgetKind::Cpu)
        }
        CUDA_FFT_BACKEND_ID | STREAMING_HYBRID_SPECTRAL_BACKEND_ID => {
            Ok(V2CoarseBackendBudgetKind::CudaOrHybrid)
        }
        backend_id => Err(format!(
            "blocked:resource-limit：无法为未知 coarse 声谱后端 {backend_id:?} 建立阶段预算。"
        )),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(not(test), allow(dead_code))]
struct V2CoarseStageBudget {
    final_artifact_bytes: usize,
    decode_phase_bytes: usize,
    analysis_phase_bytes: usize,
    peak_additional_bytes: usize,
}

fn v2_cuda_fft_batch_transient_upper_bound_bytes() -> Result<usize, String> {
    let device =
        CudaFftMemoryBudget::for_batch(CUDA_FFT_DEFAULT_BATCH_FRAMES).map_err(|error| {
            format!(
                "blocked:resource-limit：CUDA FFT 批次显存上界无法建立：{:?}: {}",
                error.code, error.message
            )
        })?;
    // `transform_batch_inner` first downloads `Vec<cufft_sys::float2>` and then collects a
    // `Vec<CudaComplex32>`. The allocator may optimize that conversion in place, but admission
    // cannot depend on an implementation detail, so both pageable host output Vecs are charged.
    let double_host_output_bytes = device
        .output_bytes
        .checked_mul(2)
        .ok_or_else(|| "blocked:resource-limit：CUDA FFT 双主机输出上界溢出。".to_string())?;
    let host_batch_bytes = v2_resource_checked_sum(
        &[
            device.input_bytes,
            double_host_output_bytes,
            v2_resource_checked_product(
                &[CUDA_FFT_DEFAULT_BATCH_FRAMES, std::mem::size_of::<f64>()],
                "CUDA FFT RMS",
            )?,
        ],
        "CUDA FFT 主机批次",
    )?;
    v2_resource_checked_sum(
        &[device.worst_case_total_device_bytes, host_batch_bytes],
        "CUDA FFT 主机与显存合计",
    )
}

fn v2_short_coarse_decode_phase_upper_bound(input: &AlignmentAudioInput) -> Result<usize, String> {
    let decode_budget = v2_short_pcm_decode_budget(input)?;
    v2_resource_checked_sum(
        &[
            supervised_read_bounded_vec_capacity_upper_bound(
                decode_budget.stdout_hard_limit_bytes,
            )?,
            decode_budget.stdout_hard_limit_bytes,
            supervised_read_bounded_stderr_capacity_upper_bound()?,
        ],
        "短媒体 FFmpeg read_bounded stdout 与 parsed PCM 阶段",
    )
}

fn v2_short_coarse_analysis_phase_upper_bound(
    input: &AlignmentAudioInput,
    backend_kind: V2CoarseBackendBudgetKind,
) -> Result<usize, String> {
    let pcm_bytes = v2_short_pcm_decode_budget(input)?.stdout_hard_limit_bytes;
    let frame_count = v2_short_coarse_frame_count_upper_bound(input)?;
    let fine_bytes = v2_fine_feature_bytes(frame_count)?;
    let unsuppressed_landmark_bytes = v2_unsuppressed_landmark_bytes(frame_count)?;
    let spectra_bytes = v2_resource_checked_product(
        &[
            frame_count,
            std::mem::size_of::<Vec<f64>>()
                + ALIGNMENT_V2_SPECTRAL_BIN_COUNT * std::mem::size_of::<f64>(),
        ],
        "短媒体 duration-sized spectra",
    )?;
    let peaks_bytes = v2_resource_checked_product(
        &[
            frame_count,
            std::mem::size_of::<Vec<u8>>()
                + ALIGNMENT_V2_MAX_SPECTRAL_PEAKS_PER_FRAME
                    * ALIGNMENT_V2_SPECTRAL_PEAK_UPPER_BYTES,
        ],
        "短媒体 peaks-by-frame",
    )?;
    let frame_time_bytes = v2_resource_checked_product(
        &[frame_count, std::mem::size_of::<i64>()],
        "短媒体 frame time",
    )?;
    // During common-family suppression the original unsuppressed Vec allocation can coexist with
    // all per-family Vec allocations. Each geometrically grown family Vec is bounded below 2x
    // its live length, so four payload copies cover the input capacity plus family capacities and
    // the rebuilding output while the spectra/peaks analysis remains borrowed.
    let landmark_suppression_bytes = unsuppressed_landmark_bytes
        .checked_mul(4)
        .ok_or_else(|| "blocked:resource-limit：短媒体 landmark 抑制阶段上界溢出。".to_string())?;
    let cpu_fft_scratch_bytes = v2_resource_checked_sum(
        &[
            v2_resource_checked_product(
                &[CUDA_FFT_FRAME_LEN, std::mem::size_of::<(f64, f64)>()],
                "CPU FFT scratch",
            )?,
            v2_resource_checked_product(
                &[
                    ALIGNMENT_V2_SPECTRAL_BIN_COUNT,
                    std::mem::size_of::<usize>(),
                ],
                "CPU FFT selected bins",
            )?,
        ],
        "CPU FFT scratch",
    )?;
    let cuda_batch_bytes = match backend_kind {
        V2CoarseBackendBudgetKind::Cpu => 0,
        V2CoarseBackendBudgetKind::CudaOrHybrid => v2_cuda_fft_batch_transient_upper_bound_bytes()?,
    };
    v2_resource_checked_sum(
        &[
            pcm_bytes,
            fine_bytes,
            spectra_bytes,
            frame_count, // Vec<bool> is bit-packed; one byte per frame is deliberately conservative.
            peaks_bytes,
            frame_time_bytes,
            landmark_suppression_bytes,
            ALIGNMENT_V2_STREAMING_FAMILY_OVERHEAD_BYTES,
            cpu_fft_scratch_bytes,
            cuda_batch_bytes,
        ],
        "短媒体 coarse 分析阶段",
    )
}

fn v2_streaming_coarse_phase_upper_bound(
    backend_kind: V2CoarseBackendBudgetKind,
) -> Result<usize, String> {
    let final_landmarks = v2_resource_checked_product(
        &[
            ALIGNMENT_V2_COARSE_MAX_LANDMARKS,
            std::mem::size_of::<SpectralLandmark>(),
        ],
        "流式最终 landmark",
    )?;
    let ranked_index_bytes = v2_resource_checked_product(
        &[
            ALIGNMENT_V2_COARSE_MAX_LANDMARKS,
            ALIGNMENT_V2_STREAMING_RANKED_LANDMARK_UPPER_BYTES,
        ],
        "流式 ranked coarse index",
    )?;
    let stdout_ring_bytes = v2_resource_checked_product(
        &[
            ALIGNMENT_V2_COARSE_STDOUT_CHUNK_BYTES,
            ALIGNMENT_V2_COARSE_STDOUT_BUFFERED_CHUNKS + 1,
        ],
        "流式 stdout ring",
    )?;
    let sample_buffer_bytes = ALIGNMENT_V2_COARSE_STDOUT_CHUNK_BYTES
        .checked_add(std::mem::size_of::<i16>())
        .ok_or_else(|| "blocked:resource-limit：流式 sample buffer 上界溢出。".to_string())?;
    let bounded_spectral_state_bytes = v2_resource_checked_sum(
        &[
            ALIGNMENT_V2_COARSE_WINDOW_SAMPLES * std::mem::size_of::<i16>(),
            3 * (std::mem::size_of::<Vec<f64>>()
                + ALIGNMENT_V2_SPECTRAL_BIN_COUNT * std::mem::size_of::<f64>()),
            24 * (std::mem::size_of::<Vec<u8>>()
                + ALIGNMENT_V2_MAX_SPECTRAL_PEAKS_PER_FRAME
                    * ALIGNMENT_V2_SPECTRAL_PEAK_UPPER_BYTES),
            CUDA_FFT_FRAME_LEN * std::mem::size_of::<(f64, f64)>(),
        ],
        "流式 CPU 声谱状态",
    )?;
    let cuda_streaming_bytes = match backend_kind {
        V2CoarseBackendBudgetKind::Cpu => 0,
        V2CoarseBackendBudgetKind::CudaOrHybrid => {
            let source_frames = v2_resource_checked_product(
                &[
                    CUDA_FFT_DEFAULT_BATCH_FRAMES,
                    ALIGNMENT_V2_COARSE_WINDOW_SAMPLES,
                    std::mem::size_of::<i16>(),
                ],
                "流式 CUDA source frames",
            )?;
            let frame_indices = v2_resource_checked_product(
                &[CUDA_FFT_DEFAULT_BATCH_FRAMES, std::mem::size_of::<usize>()],
                "流式 CUDA frame indices",
            )?;
            let reduced_frames = v2_resource_checked_product(
                &[
                    CUDA_FFT_DEFAULT_BATCH_FRAMES,
                    std::mem::size_of::<Vec<f64>>()
                        + ALIGNMENT_V2_SPECTRAL_BIN_COUNT * std::mem::size_of::<f64>(),
                ],
                "流式 CUDA reduced frames",
            )?;
            v2_resource_checked_sum(
                &[
                    v2_cuda_fft_batch_transient_upper_bound_bytes()?,
                    source_frames,
                    frame_indices,
                    reduced_frames,
                ],
                "流式 CUDA 或 hybrid 批次",
            )?
        }
    };
    v2_resource_checked_sum(
        &[
            final_landmarks,
            ranked_index_bytes,
            ALIGNMENT_V2_STREAMING_FAMILY_OVERHEAD_BYTES,
            stdout_ring_bytes,
            sample_buffer_bytes,
            supervised_read_bounded_stderr_capacity_upper_bound()?,
            bounded_spectral_state_bytes,
            cuda_streaming_bytes,
        ],
        "流式 coarse 阶段",
    )
}

fn v2_coarse_stage_budget_for_backend_id(
    input: &AlignmentAudioInput,
    planned_backend_id: &str,
) -> Result<V2CoarseStageBudget, String> {
    let backend_kind = v2_coarse_backend_budget_kind(planned_backend_id)?;
    let final_artifact_bytes = v2_candidate_artifact_upper_bound(input)?;
    let (decode_phase_bytes, analysis_phase_bytes) = if should_stream_v2_coarse_only(input) {
        let streaming_phase = v2_streaming_coarse_phase_upper_bound(backend_kind)?;
        (streaming_phase, streaming_phase)
    } else {
        (
            v2_short_coarse_decode_phase_upper_bound(input)?,
            v2_short_coarse_analysis_phase_upper_bound(input, backend_kind)?,
        )
    };
    Ok(V2CoarseStageBudget {
        final_artifact_bytes,
        decode_phase_bytes,
        analysis_phase_bytes,
        peak_additional_bytes: final_artifact_bytes
            .max(decode_phase_bytes)
            .max(analysis_phase_bytes),
    })
}

fn execute_after_v2_coarse_stage_admission<T, F>(
    retained_artifact_bytes: usize,
    input: &AlignmentAudioInput,
    planned_backend_id: &str,
    execute: F,
) -> Result<T, String>
where
    F: FnOnce() -> Result<T, String>,
{
    let budget = v2_coarse_stage_budget_for_backend_id(input, planned_backend_id)?;
    // This is a phase-peak admission, not another retained reservation. Once extraction returns,
    // the caller settles only `cached_v2_landmark_retained_bytes`; transient bytes never leak into
    // the next candidate's baseline.
    ensure_v2_active_artifact_budget(retained_artifact_bytes, budget.peak_additional_bytes)?;
    execute()
}

fn v2_candidate_artifact_upper_bound(input: &AlignmentAudioInput) -> Result<usize, String> {
    if should_stream_v2_coarse_only(input) {
        // All long candidates retain only the duration-independent coarse index. After Top-K
        // selection, the one selected window is charged separately by
        // `v2_fine_window_artifact_upper_bound` before any bounded PCM decode begins.
        return ALIGNMENT_V2_COARSE_MAX_LANDMARKS
            .checked_mul(std::mem::size_of::<SpectralLandmark>())
            .ok_or_else(|| {
                "blocked:resource-limit：流式粗定位 landmark 驻留上界溢出。".to_string()
            });
    }
    let pcm_bytes = v2_short_pcm_decode_budget(input)?.stdout_hard_limit_bytes;
    let frame_count = v2_short_coarse_frame_count_upper_bound(input)?;
    let landmark_bytes = v2_unsuppressed_landmark_bytes(frame_count)?;
    let fine_bytes = v2_fine_feature_bytes(frame_count)?;
    pcm_bytes
        .checked_add(landmark_bytes)
        .and_then(|value| value.checked_add(fine_bytes))
        .ok_or_else(|| "blocked:resource-limit：候选音轨制品驻留上界溢出。".to_string())
}

fn v2_fine_window_artifact_upper_bound(range: PresentationRangeMs) -> Result<usize, String> {
    let duration_ms = v2_presentation_range_duration_ms(range)?;
    let decode_budget = v2_fine_window_pcm_decode_budget(range)?;
    let frame_count =
        usize::try_from(u128::from(duration_ms).div_ceil(u128::from(ALIGNMENT_V2_FINE_HOP_MS)))
            .map_err(|_| "blocked:resource-limit：精解码窗口细特征帧数无法表示。".to_string())?;
    let fine_bytes = v2_fine_feature_bytes(frame_count)
        .map_err(|_| "blocked:resource-limit：精解码窗口细特征上界溢出。".to_string())?;
    let decode_phase_bytes = v2_resource_checked_sum(
        &[
            supervised_read_bounded_vec_capacity_upper_bound(
                decode_budget.stdout_hard_limit_bytes,
            )?,
            decode_budget.stdout_hard_limit_bytes,
            supervised_read_bounded_stderr_capacity_upper_bound()?,
        ],
        "精解码 read_bounded 与 parsed PCM 阶段",
    )?;
    let analysis_phase_bytes = v2_resource_checked_sum(
        &[decode_budget.stdout_hard_limit_bytes, fine_bytes],
        "精解码 PCM 与 fine feature 阶段",
    )?;
    Ok(decode_phase_bytes.max(analysis_phase_bytes))
}

fn v2_cuda_fine_transient_upper_bound_bytes() -> Result<usize, String> {
    // Source and target fine extraction are sequential, so one complete CUDA batch is the
    // whole-run transient peak rather than one batch per axis.
    v2_cuda_fft_batch_transient_upper_bound_bytes()
}

fn v2_selected_fine_cuda_transient_upper_bound(
    source_artifact: &CachedV2Landmarks,
    target_artifact: &CachedV2Landmarks,
) -> Result<usize, String> {
    for artifact in [source_artifact, target_artifact] {
        if artifact.fine_features.is_some() {
            continue;
        }
        let request = lock_fine_spectral_backend_request(&artifact.spectral_backend)?;
        if request.planned_backend_id == CUDA_FFT_BACKEND_ID {
            return v2_cuda_fine_transient_upper_bound_bytes();
        }
    }
    Ok(0)
}

fn should_stream_v2_coarse_only(input: &AlignmentAudioInput) -> bool {
    input
        .media_duration_ms
        .is_none_or(|duration| duration > ALIGNMENT_V2_MAX_DURATION_MS)
}

fn v2_landmark_artifact_kind(_input: &AlignmentAudioInput) -> &'static str {
    "landmark-streaming-coarse"
}

fn v2_planned_coarse_cache_backend_id<'a>(
    _input: &AlignmentAudioInput,
    planned_backend_id: &'a str,
) -> &'a str {
    if planned_backend_id != CUDA_FFT_BACKEND_ID {
        STREAMING_CPU_SPECTRAL_BACKEND_ID
    } else {
        planned_backend_id
    }
}

fn create_v2_planned_coarse_cache_key(
    media_path: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    planned_backend_id: &str,
) -> Result<String, String> {
    create_v2_audio_cache_key_for_backend(
        media_path,
        options,
        input,
        v2_landmark_artifact_kind(input),
        v2_planned_coarse_cache_backend_id(input, planned_backend_id),
    )
}

fn cached_v2_landmarks_from_media_artifact(
    cache_key: String,
    artifact: V2MediaArtifact,
    cache_origin: V2ArtifactCacheOrigin,
    identity_guard: Option<Arc<PinnedMediaIdentityGuard>>,
) -> CachedV2Landmarks {
    CachedV2Landmarks {
        landmarks: artifact.landmarks,
        coarse_fingerprint: artifact.coarse_fingerprint,
        pcm: artifact.pcm,
        fine_features: artifact.fine_features,
        cache_key,
        cache_hit: true,
        cache_origin,
        cache_persistence_error: None,
        spectral_backend: artifact.spectral_backend,
        presentation_bounds: artifact.presentation_bounds,
        identity_guard,
    }
}

fn plan_v2_candidate_set_cache_aware(
    media_path: &str,
    options: &AudioAlignmentOptions,
    inputs: &[AlignmentAudioInput],
    planned_backend_id: &str,
    retained_artifact_bytes: usize,
) -> Result<V2CandidateSetCachePlan, String> {
    let cache_keys = inputs
        .iter()
        .map(|input| {
            create_v2_planned_coarse_cache_key(media_path, options, input, planned_backend_id)
        })
        .collect::<Result<Vec<_>, _>>()?;
    // Clone every Arc-backed hit while holding one cache lock. Subsequent misses may mutate the
    // LRU, but execution consumes these snapshots instead of performing a second lookup.
    let cached_artifacts = {
        let mut cache = v2_landmark_cache()
            .lock()
            .map_err(|_| "Alignment V2 landmark 缓存锁已损坏。".to_string())?;
        cache_keys
            .iter()
            .map(|cache_key| cache.get(cache_key))
            .collect::<Vec<_>>()
    };

    let mut prefix_retained = retained_artifact_bytes;
    let mut plan = Vec::with_capacity(inputs.len());
    for ((input, cache_key), cached_artifact) in inputs.iter().zip(cache_keys).zip(cached_artifacts)
    {
        if let Some(artifact) = cached_artifact {
            let cached = cached_v2_landmarks_from_media_artifact(
                cache_key,
                artifact,
                V2ArtifactCacheOrigin::Memory,
                None,
            );
            prefix_retained = ensure_v2_active_artifact_budget(
                prefix_retained,
                cached_v2_landmark_retained_bytes(&cached),
            )?;
            plan.push(V2CoarseCandidateCachePlan::Hit(cached));
        } else {
            let budget = v2_coarse_stage_budget_for_backend_id(input, planned_backend_id)?;
            ensure_v2_active_artifact_budget(prefix_retained, budget.peak_additional_bytes)?;
            prefix_retained =
                ensure_v2_active_artifact_budget(prefix_retained, budget.final_artifact_bytes)?;
            plan.push(V2CoarseCandidateCachePlan::Miss {
                expected_cache_key: cache_key,
            });
        }
    }
    Ok(V2CandidateSetCachePlan {
        candidates: plan,
        planned_baseline_bytes: retained_artifact_bytes,
        projected_retained_bytes: prefix_retained,
    })
}

fn plan_v2_ordinary_candidate_sets_cache_aware(
    source_media_path: &str,
    target_media_path: &str,
    options: &AudioAlignmentOptions,
    source_inputs: &[AlignmentAudioInput],
    target_inputs: &[AlignmentAudioInput],
    planned_backend_id: &str,
    retained_artifact_bytes: usize,
) -> Result<V2OrdinaryCandidateCachePlans, String> {
    let source = plan_v2_candidate_set_cache_aware(
        source_media_path,
        options,
        source_inputs,
        planned_backend_id,
        retained_artifact_bytes,
    )?;
    let target = plan_v2_candidate_set_cache_aware(
        target_media_path,
        options,
        target_inputs,
        planned_backend_id,
        source.projected_retained_bytes,
    )?;
    Ok(V2OrdinaryCandidateCachePlans { source, target })
}

#[cfg(test)]
fn ensure_v2_candidate_set_active_budget(
    source_inputs: &[AlignmentAudioInput],
    target_inputs: &[AlignmentAudioInput],
) -> Result<(), String> {
    reserve_v2_candidate_set_active_budget(0, source_inputs, target_inputs).map(|_| ())
}

#[cfg(test)]
fn reserve_v2_candidate_set_active_budget(
    retained_artifact_bytes: usize,
    source_inputs: &[AlignmentAudioInput],
    target_inputs: &[AlignmentAudioInput],
) -> Result<usize, String> {
    let mut retained = retained_artifact_bytes;
    for input in source_inputs.iter().chain(target_inputs) {
        retained =
            ensure_v2_active_artifact_budget(retained, v2_candidate_artifact_upper_bound(input)?)?;
    }
    Ok(retained)
}

#[cfg(test)]
fn execute_after_v2_candidate_reservation<T, F>(
    retained_artifact_bytes: usize,
    source_inputs: &[AlignmentAudioInput],
    target_inputs: &[AlignmentAudioInput],
    execute: F,
) -> Result<T, String>
where
    F: FnOnce() -> Result<T, String>,
{
    // Reservation is deliberately completed before `execute` can spawn FFmpeg. Actual retained
    // bytes are settled by the caller after extraction, so conservative headroom is not kept.
    reserve_v2_candidate_set_active_budget(retained_artifact_bytes, source_inputs, target_inputs)?;
    execute()
}

fn ensure_v2_active_artifact_budget(
    retained_bytes: usize,
    additional_bytes: usize,
) -> Result<usize, String> {
    let next = retained_bytes
        .checked_add(additional_bytes)
        .ok_or_else(|| "blocked:resource-limit：候选音轨制品驻留字节溢出。".to_string())?;
    if next > MAX_V2_ACTIVE_ARTIFACT_BYTES {
        return Err(format!(
            "blocked:resource-limit：候选音轨制品的单次驻留预算超过 {} MiB；请显式选择需要比较的音轨。",
            MAX_V2_ACTIVE_ARTIFACT_BYTES / (1024 * 1024)
        ));
    }
    Ok(next)
}

fn v2_coarse_candidate_reserved_bytes(candidate_count: usize) -> Result<usize, String> {
    candidate_count
        .checked_mul(ALIGNMENT_V2_COARSE_CANDIDATE_RESERVED_BYTES)
        .ok_or_else(|| {
            "blocked:resource-limit：coarse affine candidate 驻留字节上界溢出。".to_string()
        })
}

fn v2_materialized_anchor_resident_bytes(hypothesis: &AffineHypothesis) -> Result<usize, String> {
    hypothesis
        .training_anchors
        .capacity()
        .checked_add(hypothesis.held_out_anchors.capacity())
        .and_then(|anchor_count| {
            anchor_count.checked_mul(std::mem::size_of::<AffineAnchorEvidence>())
        })
        .ok_or_else(|| {
            "blocked:resource-limit：materialized affine anchor 驻留字节溢出。".to_string()
        })
}

fn cached_v2_landmark_retained_bytes(artifact: &CachedV2Landmarks) -> usize {
    v2_media_artifact_payload_bytes(&V2MediaArtifact {
        pcm: artifact.pcm.clone(),
        landmarks: artifact.landmarks.clone(),
        coarse_fingerprint: artifact.coarse_fingerprint.clone(),
        fine_features: artifact.fine_features.clone(),
        spectral_backend: artifact.spectral_backend.clone(),
        presentation_bounds: artifact.presentation_bounds,
    })
}

fn v2_media_artifact_payload_bytes(artifact: &V2MediaArtifact) -> usize {
    let pcm_bytes = artifact
        .pcm
        .as_ref()
        .map(|pcm| pcm.capacity().saturating_mul(std::mem::size_of::<i16>()))
        .unwrap_or(0);
    let landmark_bytes = artifact
        .landmarks
        .capacity()
        .saturating_mul(std::mem::size_of::<SpectralLandmark>());
    let coarse_fingerprint_bytes = artifact
        .coarse_fingerprint
        .capacity()
        .saturating_mul(std::mem::size_of::<CoarseSpectralFingerprintFrame>());
    let fine_bytes = artifact
        .fine_features
        .as_ref()
        .map(|frames| {
            frames
                .capacity()
                .saturating_mul(std::mem::size_of::<FineFeatureFrame>())
                .saturating_add(frames.iter().fold(0_usize, |total, frame| {
                    total.saturating_add(
                        frame
                            .values
                            .capacity()
                            .saturating_mul(std::mem::size_of::<f32>()),
                    )
                }))
        })
        .unwrap_or(0);
    pcm_bytes
        .saturating_add(landmark_bytes)
        .saturating_add(coarse_fingerprint_bytes)
        .saturating_add(fine_bytes)
        .saturating_add(artifact.spectral_backend.backend_id.len())
        .saturating_add(artifact.spectral_backend.requested_backend.len())
        .saturating_add(artifact.spectral_backend.backend_detail.len())
        .saturating_add(
            artifact
                .spectral_backend
                .fallback_reason
                .as_ref()
                .map(String::len)
                .unwrap_or(0),
        )
}

fn v2_media_artifact_resident_bytes(cache_key: &str, artifact: &V2MediaArtifact) -> usize {
    v2_media_artifact_payload_bytes(artifact)
        .saturating_add(cache_key.len())
        .saturating_add(std::mem::size_of::<V2MediaArtifactCacheEntry>())
}

fn v2_landmark_cache() -> &'static Mutex<V2MediaArtifactCache> {
    V2_LANDMARK_CACHE
        .get_or_init(|| Mutex::new(V2MediaArtifactCache::new(MAX_V2_MEDIA_ARTIFACT_CACHE_BYTES)))
}

fn persistent_v2_coarse_cache_root() -> Option<PathBuf> {
    if let Some(path) = std::env::var_os("C137_V2_COARSE_CACHE_DIR")
        .map(PathBuf::from)
        .filter(|path| !path.as_os_str().is_empty())
    {
        return Some(path);
    }
    std::env::var_os("LOCALAPPDATA").map(|root| {
        PathBuf::from(root)
            .join("studio.danmaku.timeline")
            .join(PERSISTENT_V2_COARSE_CACHE_DIRECTORY)
    })
}

fn persistent_v2_coarse_cache_key_digest(cache_key: &str) -> String {
    Sha256::digest(cache_key.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn persistent_v2_coarse_payload_digest(
    payload: &PersistentV2CoarsePayload,
) -> Result<String, String> {
    let bytes =
        serde_json::to_vec(payload).map_err(|_| "磁盘粗索引 payload 无法序列化。".to_string())?;
    Ok(format!(
        "sha256:{}",
        Sha256::digest(bytes)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    ))
}

fn persistent_v2_coarse_cache_path(root: &Path, cache_key_digest: &str) -> PathBuf {
    root.join(format!("{cache_key_digest}.json"))
}

fn persistent_v2_coarse_payload_from_artifact(
    cache_key: &str,
    artifact: &V2MediaArtifact,
) -> PersistentV2CoarsePayload {
    PersistentV2CoarsePayload {
        cache_key_digest: persistent_v2_coarse_cache_key_digest(cache_key),
        presentation_start_ms: artifact.presentation_bounds.start_ms,
        presentation_end_ms: artifact.presentation_bounds.end_ms,
        spectral_backend: PersistentV2CoarseBackend {
            backend_id: artifact.spectral_backend.backend_id.clone(),
            requested_backend: artifact.spectral_backend.requested_backend.clone(),
            backend_detail: artifact.spectral_backend.backend_detail.clone(),
            fallback_reason: artifact.spectral_backend.fallback_reason.clone(),
        },
        landmarks: artifact.landmarks.as_ref().clone(),
        coarse_fingerprint: artifact.coarse_fingerprint.as_ref().clone(),
    }
}

fn validate_persistent_v2_coarse_payload(
    expected_cache_key_digest: &str,
    payload: &PersistentV2CoarsePayload,
) -> Result<(), String> {
    if payload.cache_key_digest != expected_cache_key_digest {
        return Err("磁盘粗索引 cache key 摘要不匹配。".to_string());
    }
    if payload.presentation_end_ms <= payload.presentation_start_ms {
        return Err("磁盘粗索引展示时间范围无效。".to_string());
    }
    if payload.landmarks.is_empty() || payload.landmarks.len() > ALIGNMENT_V2_COARSE_MAX_LANDMARKS {
        return Err("磁盘粗索引 landmark 数量超出硬边界。".to_string());
    }
    if payload.coarse_fingerprint.is_empty()
        || payload.coarse_fingerprint.len() > 200_000
        || payload.coarse_fingerprint.windows(2).any(|pair| {
            pair[0].time_ms >= pair[1].time_ms
                || pair[0].active_ratio_milli > 1_000
                || pair[1].active_ratio_milli > 1_000
        })
        || payload.coarse_fingerprint.iter().any(|frame| {
            frame.time_ms < payload.presentation_start_ms
                || frame.time_ms > payload.presentation_end_ms
                || frame.active_ratio_milli > 1_000
        })
    {
        return Err("磁盘粗索引 coarse fingerprint 无效。".to_string());
    }
    for landmark in &payload.landmarks {
        let anchor_bin = landmark.hash >> 16;
        let target_bin = (landmark.hash >> 8) & 0xff;
        if anchor_bin >= ALIGNMENT_V2_SPECTRAL_BIN_COUNT as u64
            || target_bin >= ALIGNMENT_V2_SPECTRAL_BIN_COUNT as u64
            || landmark.time_ms < payload.presentation_start_ms
            || landmark.time_ms > payload.presentation_end_ms
        {
            return Err("磁盘粗索引包含越界 landmark。".to_string());
        }
    }
    if payload.landmarks.windows(2).any(|pair| {
        let left = &pair[0];
        let right = &pair[1];
        left.time_ms > right.time_ms
            || (left.time_ms == right.time_ms && left.hash > right.hash)
            || (left.time_ms == right.time_ms
                && left.hash == right.hash
                && left.strength_milli < right.strength_milli)
    }) {
        return Err("磁盘粗索引 landmark 未按规范顺序保存。".to_string());
    }
    for value in [
        payload.spectral_backend.backend_id.as_str(),
        payload.spectral_backend.requested_backend.as_str(),
        payload.spectral_backend.backend_detail.as_str(),
    ] {
        if value.is_empty() || value.len() > 16 * 1024 {
            return Err("磁盘粗索引声谱后端字段无效。".to_string());
        }
    }
    if payload
        .spectral_backend
        .fallback_reason
        .as_ref()
        .is_some_and(|value| value.len() > 16 * 1024)
    {
        return Err("磁盘粗索引声谱回退字段过长。".to_string());
    }
    Ok(())
}

fn v2_media_artifact_from_persistent_payload(
    payload: PersistentV2CoarsePayload,
) -> V2MediaArtifact {
    V2MediaArtifact {
        pcm: None,
        landmarks: Arc::new(payload.landmarks),
        coarse_fingerprint: Arc::new(payload.coarse_fingerprint),
        fine_features: None,
        spectral_backend: SpectralBackendExecution {
            backend_id: payload.spectral_backend.backend_id,
            requested_backend: payload.spectral_backend.requested_backend,
            backend_detail: payload.spectral_backend.backend_detail,
            fallback_reason: payload.spectral_backend.fallback_reason,
        },
        presentation_bounds: PresentationRangeMs {
            start_ms: payload.presentation_start_ms,
            end_ms: payload.presentation_end_ms,
        },
    }
}

fn replace_persistent_v2_coarse_cache_file(
    temporary_path: &Path,
    destination_path: &Path,
) -> Result<(), String> {
    #[cfg(windows)]
    {
        use std::os::windows::ffi::OsStrExt;
        use windows_sys::Win32::Storage::FileSystem::{
            MoveFileExW, MOVEFILE_REPLACE_EXISTING, MOVEFILE_WRITE_THROUGH,
        };
        let temporary = temporary_path
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        let destination = destination_path
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        // SAFETY: both UTF-16 buffers are NUL-terminated and remain alive for the call.
        let moved = unsafe {
            MoveFileExW(
                temporary.as_ptr(),
                destination.as_ptr(),
                MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH,
            )
        };
        if moved == 0 {
            return Err("磁盘粗索引无法原子替换目标文件。".to_string());
        }
        Ok(())
    }
    #[cfg(not(windows))]
    {
        fs::rename(temporary_path, destination_path)
            .map_err(|_| "磁盘粗索引无法原子替换目标文件。".to_string())
    }
}

fn prune_persistent_v2_coarse_cache(root: &Path) {
    let Ok(entries) = fs::read_dir(root) else {
        return;
    };
    let mut artifacts = entries
        .filter_map(Result::ok)
        .filter_map(|entry| {
            let path = entry.path();
            let file_name = path.file_name()?.to_str()?;
            let digest = file_name.strip_suffix(".json")?;
            if digest.len() != 64
                || !digest
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
            {
                return None;
            }
            let metadata = entry.metadata().ok()?;
            let modified = metadata.modified().unwrap_or(UNIX_EPOCH);
            Some((path, metadata.len(), modified))
        })
        .collect::<Vec<_>>();
    artifacts.sort_by_key(|(_, _, modified)| *modified);
    let mut total_bytes = artifacts
        .iter()
        .fold(0_u64, |total, (_, bytes, _)| total.saturating_add(*bytes));
    let mut remaining_entries = artifacts.len();
    for (path, bytes, _) in artifacts {
        if remaining_entries <= PERSISTENT_V2_COARSE_CACHE_MAX_ENTRIES
            && total_bytes <= PERSISTENT_V2_COARSE_CACHE_MAX_TOTAL_BYTES
        {
            break;
        }
        if fs::remove_file(path).is_ok() {
            remaining_entries = remaining_entries.saturating_sub(1);
            total_bytes = total_bytes.saturating_sub(bytes);
        }
    }
}

fn write_persistent_v2_coarse_artifact(
    cache_key: &str,
    artifact: &V2MediaArtifact,
) -> Result<(), String> {
    let Some(root) = persistent_v2_coarse_cache_root() else {
        return Err("当前环境没有可用的本地应用数据目录。".to_string());
    };
    write_persistent_v2_coarse_artifact_at(&root, cache_key, artifact)
}

fn write_persistent_v2_coarse_artifact_at(
    root: &Path,
    cache_key: &str,
    artifact: &V2MediaArtifact,
) -> Result<(), String> {
    fs::create_dir_all(root).map_err(|_| "无法创建磁盘粗索引目录。".to_string())?;
    let payload = persistent_v2_coarse_payload_from_artifact(cache_key, artifact);
    validate_persistent_v2_coarse_payload(&payload.cache_key_digest, &payload)?;
    let envelope = PersistentV2CoarseEnvelope {
        schema_version: PERSISTENT_V2_COARSE_CACHE_SCHEMA_VERSION,
        payload_digest: persistent_v2_coarse_payload_digest(&payload)?,
        last_access_ms: current_time_ms(),
        payload,
    };
    let bytes = serde_json::to_vec(&envelope)
        .map_err(|_| "磁盘粗索引 envelope 无法序列化。".to_string())?;
    if bytes.len() as u64 > PERSISTENT_V2_COARSE_CACHE_MAX_FILE_BYTES {
        return Err("磁盘粗索引文件超过单文件硬上限。".to_string());
    }
    let destination = persistent_v2_coarse_cache_path(root, &envelope.payload.cache_key_digest);
    let temporary = root.join(format!(
        ".{}.{}.{}.tmp",
        envelope.payload.cache_key_digest,
        std::process::id(),
        current_time_ms()
    ));
    let write_result = (|| {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|_| "无法创建磁盘粗索引临时文件。".to_string())?;
        file.write_all(&bytes)
            .map_err(|_| "无法完整写入磁盘粗索引临时文件。".to_string())?;
        file.sync_all()
            .map_err(|_| "无法同步磁盘粗索引临时文件。".to_string())?;
        replace_persistent_v2_coarse_cache_file(&temporary, &destination)
    })();
    if write_result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    write_result?;
    prune_persistent_v2_coarse_cache(root);
    Ok(())
}

fn load_persistent_v2_coarse_artifact(cache_key: &str) -> Option<V2MediaArtifact> {
    let root = persistent_v2_coarse_cache_root()?;
    load_persistent_v2_coarse_artifact_at(&root, cache_key)
}

fn load_persistent_v2_coarse_artifact_at(root: &Path, cache_key: &str) -> Option<V2MediaArtifact> {
    let expected_cache_key_digest = persistent_v2_coarse_cache_key_digest(cache_key);
    let path = persistent_v2_coarse_cache_path(root, &expected_cache_key_digest);
    let load_result = (|| -> Result<(V2MediaArtifact, PersistentV2CoarseEnvelope), String> {
        let metadata = fs::metadata(&path).map_err(|_| "磁盘粗索引不存在。".to_string())?;
        if metadata.len() == 0 || metadata.len() > PERSISTENT_V2_COARSE_CACHE_MAX_FILE_BYTES {
            return Err("磁盘粗索引文件大小无效。".to_string());
        }
        let bytes = fs::read(&path).map_err(|_| "磁盘粗索引无法读取。".to_string())?;
        let mut envelope = serde_json::from_slice::<PersistentV2CoarseEnvelope>(&bytes)
            .map_err(|_| "磁盘粗索引 JSON 无效。".to_string())?;
        if envelope.schema_version != PERSISTENT_V2_COARSE_CACHE_SCHEMA_VERSION {
            return Err("磁盘粗索引 schema 版本不受支持。".to_string());
        }
        validate_persistent_v2_coarse_payload(&expected_cache_key_digest, &envelope.payload)?;
        let expected_payload_digest = persistent_v2_coarse_payload_digest(&envelope.payload)?;
        if envelope.payload_digest != expected_payload_digest {
            return Err("磁盘粗索引 payload 摘要校验失败。".to_string());
        }
        envelope.last_access_ms = current_time_ms();
        let artifact = v2_media_artifact_from_persistent_payload(envelope.payload.clone());
        Ok((artifact, envelope))
    })();
    match load_result {
        Ok((artifact, envelope)) => {
            // Refreshing the envelope gives the bounded cleanup pass a real last-access order.
            let _ = write_persistent_v2_coarse_artifact_at(root, cache_key, &artifact);
            debug_assert_eq!(envelope.payload.cache_key_digest, expected_cache_key_digest);
            Some(artifact)
        }
        Err(_) => {
            if path.is_file() {
                let _ = fs::remove_file(path);
            }
            None
        }
    }
}

fn get_v2_landmarks(
    media_path: &str,
    label: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    context: V2LandmarkExtractionContext<'_>,
) -> Result<CachedV2Landmarks, String> {
    let V2LandmarkExtractionContext {
        cancel_flag,
        shared_backend_request,
        cache_plan,
        retained_artifact_bytes,
        identity_guard,
    } = context;
    check_cancelled(cancel_flag)?;
    let backend_request = shared_backend_request.unwrap_or(&options.spectral_backend_request);
    let mut cache_key = create_v2_planned_coarse_cache_key(
        media_path,
        options,
        input,
        &backend_request.planned_backend_id,
    )?;
    match cache_plan {
        Some(V2CoarseCandidateCachePlan::Hit(mut cached)) => {
            if cached.cache_key != cache_key {
                return Err(
                    "blocked:media-identity-changed：V2 coarse 缓存计划与当前媒体身份不一致。"
                        .to_string(),
                );
            }
            verify_v2_spectral_backend_policy(
                &cached.spectral_backend,
                &options.spectral_backend_request,
            )?;
            verify_media_content_identity_after_tool_output_or_pinned(
                identity_guard.as_deref(),
                media_path,
                input.content_identity.as_ref(),
                cancel_flag,
                "V2 landmark 缓存复用",
            )?;
            benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Hit);
            cached.identity_guard = identity_guard;
            return Ok(cached);
        }
        Some(V2CoarseCandidateCachePlan::Miss { expected_cache_key }) => {
            if expected_cache_key != cache_key {
                return Err(
                    "blocked:media-identity-changed：V2 coarse miss 计划与当前媒体身份不一致。"
                        .to_string(),
                );
            }
            benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Miss);
        }
        None => {
            let cached_artifact = {
                let mut cache = v2_landmark_cache()
                    .lock()
                    .map_err(|_| "Alignment V2 landmark 缓存锁已损坏。".to_string())?;
                cache.get(&cache_key)
            };
            if let Some(artifact) = cached_artifact {
                verify_v2_spectral_backend_policy(
                    &artifact.spectral_backend,
                    &options.spectral_backend_request,
                )?;
                verify_media_content_identity_after_tool_output_or_pinned(
                    identity_guard.as_deref(),
                    media_path,
                    input.content_identity.as_ref(),
                    cancel_flag,
                    "V2 landmark 缓存复用",
                )?;
                benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Hit);
                return Ok(cached_v2_landmarks_from_media_artifact(
                    cache_key,
                    artifact,
                    V2ArtifactCacheOrigin::Memory,
                    identity_guard,
                ));
            }
            benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Miss);
        }
    }
    check_cancelled(cancel_flag)?;
    if let Some(artifact) = load_persistent_v2_coarse_artifact(&cache_key) {
        verify_v2_spectral_backend_policy(
            &artifact.spectral_backend,
            &options.spectral_backend_request,
        )?;
        verify_media_content_identity_after_tool_output_or_pinned(
            identity_guard.as_deref(),
            media_path,
            input.content_identity.as_ref(),
            cancel_flag,
            "V2 磁盘粗索引复用",
        )?;
        let cached = cached_v2_landmarks_from_media_artifact(
            cache_key.clone(),
            artifact.clone(),
            V2ArtifactCacheOrigin::Persistent,
            identity_guard.clone(),
        );
        let mut cache = v2_landmark_cache()
            .lock()
            .map_err(|_| "Alignment V2 landmark 缓存锁已损坏。".to_string())?;
        let insertion = cache.insert(cache_key, artifact, cancel_flag)?;
        for _ in 0..insertion.eviction_count {
            benchmark_cache_event(
                BenchmarkCacheKind::V2Landmarks,
                BenchmarkCacheEvent::Eviction,
            );
        }
        benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Hit);
        return Ok(cached);
    }
    let presentation_offset_ms = input
        .decode_timeline
        .as_ref()
        .map(|item| item.normalized_pcm_origin_ms)
        .unwrap_or(0);
    let (landmarks, coarse_fingerprint, spectral_backend, presentation_bounds) =
        execute_after_v2_coarse_stage_admission(
            retained_artifact_bytes,
            input,
            &backend_request.planned_backend_id,
            || {
                let coarse = decode_v2_coarse_landmarks_streaming(
                    media_path,
                    label,
                    options,
                    input,
                    backend_request,
                    cancel_flag,
                    identity_guard.as_deref(),
                )?;
                let presentation_bounds = v2_presentation_bounds_for_samples(
                    presentation_offset_ms,
                    coarse.decoded_sample_count,
                )?;
                Ok((
                    Arc::new(coarse.index.landmarks),
                    Arc::new(coarse.coarse_fingerprint),
                    coarse.spectral_backend,
                    presentation_bounds,
                ))
            },
        )?;
    verify_v2_spectral_backend_policy(&spectral_backend, &options.spectral_backend_request)?;
    cache_key = create_v2_audio_cache_key_for_backend(
        media_path,
        options,
        input,
        v2_landmark_artifact_kind(input),
        &spectral_backend.backend_id,
    )?;
    // Cancellation after extraction must never publish a partially trusted warm artifact.
    check_cancelled(cancel_flag)?;
    let artifact = V2MediaArtifact {
        pcm: None,
        landmarks: landmarks.clone(),
        coarse_fingerprint: coarse_fingerprint.clone(),
        fine_features: None,
        spectral_backend: spectral_backend.clone(),
        presentation_bounds,
    };
    // Persist the bounded coarse payload for episode-sized targets too. The disk envelope never
    // stores PCM or fine features, so warm 1×N runs can reuse target landmarks while selected
    // candidates still receive fresh bounded fine evidence.
    let (persistent_cache_stored, cache_persistence_error) =
        match write_persistent_v2_coarse_artifact(&cache_key, &artifact) {
            Ok(()) => (true, None),
            Err(error) => (false, Some(error)),
        };
    let mut cache = v2_landmark_cache()
        .lock()
        .map_err(|_| "Alignment V2 landmark 缓存锁已损坏。".to_string())?;
    let insertion = cache.insert(cache_key.clone(), artifact, cancel_flag)?;
    for _ in 0..insertion.eviction_count {
        benchmark_cache_event(
            BenchmarkCacheKind::V2Landmarks,
            BenchmarkCacheEvent::Eviction,
        );
    }
    if insertion.stored && insertion.new_entry {
        benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Write);
    }
    Ok(CachedV2Landmarks {
        landmarks,
        coarse_fingerprint,
        pcm: None,
        fine_features: None,
        cache_key,
        cache_hit: false,
        cache_origin: if persistent_cache_stored {
            V2ArtifactCacheOrigin::NewPersistent
        } else {
            V2ArtifactCacheOrigin::NewMemoryOnly
        },
        cache_persistence_error,
        spectral_backend,
        presentation_bounds,
        identity_guard,
    })
}

#[cfg(test)]
fn create_v2_audio_cache_key(
    media_path: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    artifact: &str,
) -> Result<String, String> {
    let request = &options.spectral_backend_request;
    let backend_id = if request.planned_backend_id != crate::cuda_fft_backend::CUDA_FFT_BACKEND_ID {
        STREAMING_CPU_SPECTRAL_BACKEND_ID.to_string()
    } else {
        request.planned_backend_id.clone()
    };
    create_v2_audio_cache_key_for_backend(media_path, options, input, artifact, &backend_id)
}

fn create_v2_audio_cache_key_for_backend(
    media_path: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    artifact: &str,
    spectral_backend_id: &str,
) -> Result<String, String> {
    let legacy_identity = create_audio_feature_cache_key(media_path, options, input)?;
    let timeline = input.decode_timeline.as_ref();
    Ok(format!(
        "engine={ALIGNMENT_V2_ENGINE_VERSION}|feature={ALIGNMENT_V2_FEATURE_VERSION}|artifact={artifact}|requestedSpectralBackend={}|spectralBackend={spectral_backend_id}|ptsOrigin={}|streamPtsOffset={}|firstDecodedPts={:?}|ptsDiscontinuities={}|maxPtsGap={:?}|skipSamples={}|discardPadding={}|normalizedPcmOrigin={}|{legacy_identity}",
        options.spectral_backend_request.requested_backend,
        input.presentation_origin_ms,
        input.stream.timeline_offset_ms,
        timeline.and_then(|item| item.first_decoded_pts_ms),
        timeline.map(|item| item.pts_discontinuity_count).unwrap_or(0),
        timeline.and_then(|item| item.max_pts_gap_ms),
        timeline.map(|item| item.skip_samples).unwrap_or(0),
        timeline.map(|item| item.discard_padding).unwrap_or(0),
        timeline
            .map(|item| item.normalized_pcm_origin_ms)
            .unwrap_or(0),
    ))
}

fn verify_v2_spectral_backend_policy(
    execution: &SpectralBackendExecution,
    request: &SpectralBackendRequest,
) -> Result<(), String> {
    if execution.requested_backend != request.requested_backend {
        return Err(
            "blocked:spectral-backend-policy-mismatch：V2 声谱制品与本次请求的 CPU/GPU 策略不一致。"
                .to_string(),
        );
    }
    Ok(())
}

fn decode_v2_audio(
    media_path: &str,
    label: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    landmark_artifact: &CachedV2Landmarks,
    cancel_flag: Option<&AtomicBool>,
) -> Result<DecodedV2Audio, String> {
    check_v2_duration_limit(input, label)?;
    check_cancelled(cancel_flag)?;
    verify_v2_spectral_backend_policy(
        &landmark_artifact.spectral_backend,
        &options.spectral_backend_request,
    )?;
    let expected_cache_key = create_v2_audio_cache_key_for_backend(
        media_path,
        options,
        input,
        v2_landmark_artifact_kind(input),
        &landmark_artifact.spectral_backend.backend_id,
    )?;
    if landmark_artifact.cache_key != expected_cache_key {
        return Err(format!(
            "blocked:media-identity-changed：{label}粗定位制品与当前内容身份、音轨、PTS 或算法参数不一致。"
        ));
    }
    // Cache hits never replace the run-level final identity gate. Recheck before the
    // retained PCM is consumed so stale bytes cannot drive expensive DP work.
    verify_media_content_identity_after_tool_output_or_pinned(
        landmark_artifact.identity_guard.as_deref(),
        media_path,
        input.content_identity.as_ref(),
        cancel_flag,
        "V2 PCM/细特征复用",
    )?;
    if let Some(fine_features) = landmark_artifact.fine_features.clone() {
        if fine_features.is_empty() {
            return Err(format!("{label}没有可用的 50 ms 细粒度音频特征。"));
        }
        let pcm = landmark_artifact.pcm.clone().ok_or_else(|| {
            "blocked:artifact-missing：细特征制品缺少对应的完整 PCM。".to_string()
        })?;
        // Short-media preparation computes coarse landmarks and fine features in one physical
        // extraction. The fine execution receipt still uses the same canonical lock identity as
        // separately materialized fine windows, so evidence is independent of this cache shape.
        let fine_backend_request =
            lock_fine_spectral_backend_request(&landmark_artifact.spectral_backend)?;
        return Ok(DecodedV2Audio {
            pcm,
            fine_features,
            fine_spectral_backend: SpectralBackendExecution {
                backend_id: fine_backend_request.planned_backend_id,
                requested_backend: fine_backend_request.requested_backend,
                backend_detail: fine_backend_request.backend_detail,
                fallback_reason: fine_backend_request.fallback_reason,
            },
            presentation_offset_ms: landmark_artifact.presentation_bounds.start_ms,
        });
    }

    let pcm = match landmark_artifact.pcm.clone() {
        Some(pcm) => pcm,
        None => Arc::new(decode_v2_pcm(
            media_path,
            label,
            options,
            input,
            cancel_flag,
            landmark_artifact.identity_guard.as_deref(),
        )?),
    };
    let fine_backend_request =
        lock_fine_spectral_backend_request(&landmark_artifact.spectral_backend)?;
    let fine_extraction = extract_fine_features_with_backend_request(
        &pcm,
        &FineFeatureConfig {
            sample_rate: ALIGNMENT_V2_SAMPLE_RATE,
            presentation_offset_ms: landmark_artifact.presentation_bounds.start_ms,
            window_ms: 50,
            hop_ms: ALIGNMENT_V2_FINE_HOP_MS,
        },
        cancel_flag,
        &fine_backend_request,
    )?;
    ensure_v2_fine_spectral_backend_continuity(
        &landmark_artifact.spectral_backend,
        &fine_extraction.spectral_backend,
    )?;
    let fine_features = Arc::new(fine_extraction.fine_features);
    if fine_features.is_empty() {
        return Err(format!("{label}没有可用的 50 ms 细粒度音频特征。"));
    }
    // As with landmark extraction, do not let cancellation race a cache publication.
    check_cancelled(cancel_flag)?;
    let artifact = V2MediaArtifact {
        pcm: Some(pcm.clone()),
        landmarks: landmark_artifact.landmarks.clone(),
        coarse_fingerprint: landmark_artifact.coarse_fingerprint.clone(),
        fine_features: Some(fine_features.clone()),
        // The cache key and persisted coarse artifact are bound to the coarse backend. Fine may
        // use the locked compatible CPU backend after streaming CPU coarse, so retaining the
        // fine backend here would make the next coarse lookup self-inconsistent.
        spectral_backend: landmark_artifact.spectral_backend.clone(),
        presentation_bounds: landmark_artifact.presentation_bounds,
    };
    let insertion = v2_landmark_cache()
        .lock()
        .map_err(|_| "Alignment V2 landmark 缓存锁已损坏。".to_string())?
        .insert(expected_cache_key, artifact, cancel_flag)?;
    for _ in 0..insertion.eviction_count {
        benchmark_cache_event(
            BenchmarkCacheKind::V2Landmarks,
            BenchmarkCacheEvent::Eviction,
        );
    }
    // Enriching an existing landmark/PCM entry with fine features is an in-place cache
    // upgrade, not another benchmark write. If the entry was evicted meanwhile, its
    // reintroduction is correctly observable as a new write.
    if insertion.stored && insertion.new_entry {
        benchmark_cache_event(BenchmarkCacheKind::V2Landmarks, BenchmarkCacheEvent::Write);
    }
    Ok(DecodedV2Audio {
        pcm,
        fine_features,
        fine_spectral_backend: fine_extraction.spectral_backend,
        presentation_offset_ms: landmark_artifact.presentation_bounds.start_ms,
    })
}

fn ensure_v2_fine_spectral_backend_continuity(
    coarse_backend: &SpectralBackendExecution,
    fine_backend: &SpectralBackendExecution,
) -> Result<(), String> {
    let locked = lock_fine_spectral_backend_request(coarse_backend)?;
    if fine_backend.backend_id != locked.planned_backend_id {
        return Err(format!(
            "blocked:spectral-backend-continuity：coarse 后端 {} 锁定 fine 后端 {}，实际却由 {} 完成。",
            coarse_backend.backend_id, locked.planned_backend_id, fine_backend.backend_id
        ));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct V2SelectedFineDecodePlan {
    windows: AffineFineDecodeWindows,
    adaptive_guard_ms: i64,
}

fn plan_v2_selected_fine_decode(
    pair: &V2TrackPairCandidate,
    source_artifact: &CachedV2Landmarks,
    target_artifact: &CachedV2Landmarks,
) -> Result<Option<V2SelectedFineDecodePlan>, String> {
    let source_requires_window = should_stream_v2_coarse_only(&pair.source_input);
    let target_requires_window = should_stream_v2_coarse_only(&pair.target_input);
    if !source_requires_window && !target_requires_window {
        return Ok(None);
    }

    let target_query = v2_selected_candidate_target_query(
        pair,
        source_artifact.presentation_bounds,
        target_artifact.presentation_bounds,
    )?;

    // Spend the remaining one-hour decode budget on context rather than fixing every candidate
    // to exactly ±31 s. The helper also unions the complete coarse source support, so internal
    // source-only edits wider than the guard cannot be clipped. If even the mandatory DP/boundary
    // context does not fit, fail closed instead of silently truncating the map.
    let mut guard_ms = 5 * 60_000_i64;
    let mut selected = None;
    while guard_ms >= ALIGNMENT_V2_FINE_WINDOW_GUARD_MS {
        let windows = derive_affine_fine_decode_windows(
            &pair.hypothesis,
            &AffineFineWindowRequest {
                source_bounds: source_artifact.presentation_bounds,
                target_bounds: target_artifact.presentation_bounds,
                target_query,
                source_guard_ms: guard_ms,
                target_guard_ms: guard_ms,
            },
        )?;
        let source_window_duration = v2_presentation_range_duration_ms(windows.source)?;
        let target_window_duration = v2_presentation_range_duration_ms(windows.target)?;
        if source_window_duration <= ALIGNMENT_V2_MAX_DURATION_MS
            && target_window_duration <= ALIGNMENT_V2_MAX_DURATION_MS
        {
            selected = Some(V2SelectedFineDecodePlan {
                windows,
                adaptive_guard_ms: guard_ms,
            });
            break;
        }
        guard_ms = guard_ms.saturating_sub(1_000);
    }
    selected.ok_or_else(|| {
        "blocked:resource-limit：完整候选逆投影、全部 coarse inlier support 与 edit-aware DP 必需上下文无法同时装入 60 分钟精解码窗口；未截断成功。"
            .to_string()
    })
    .map(Some)
}

fn derive_v2_selected_candidate_content_intervals(
    pair: &V2TrackPairCandidate,
    source_artifact: &CachedV2Landmarks,
    target_artifact: &CachedV2Landmarks,
) -> Result<AffineFineDecodeWindows, String> {
    let target_query = v2_selected_candidate_target_query(
        pair,
        source_artifact.presentation_bounds,
        target_artifact.presentation_bounds,
    )?;
    derive_affine_fine_decode_windows(
        &pair.hypothesis,
        &AffineFineWindowRequest {
            source_bounds: source_artifact.presentation_bounds,
            target_bounds: target_artifact.presentation_bounds,
            target_query,
            source_guard_ms: 0,
            target_guard_ms: 0,
        },
    )
}

fn v2_selected_candidate_target_query(
    pair: &V2TrackPairCandidate,
    source_bounds: PresentationRangeMs,
    target_bounds: PresentationRangeMs,
) -> Result<PresentationRangeMs, String> {
    let source_duration_ms = v2_presentation_range_duration_ms(source_bounds)?;
    let target_duration_ms = v2_presentation_range_duration_ms(target_bounds)?;
    if target_duration_ms <= ALIGNMENT_V2_MAX_DURATION_MS {
        // Product direction is source=Bilibili reference -> target=original. When the original
        // is episode-sized, consume its complete presentation interval.
        Ok(target_bounds)
    } else if source_duration_ms <= ALIGNMENT_V2_MAX_DURATION_MS {
        // Symmetric long-target case: project the complete short source interval.
        project_v2_source_range_to_target(source_bounds, &pair.hypothesis)
    } else {
        Err(
            "blocked:window-evidence-insufficient：粗定位两侧都超过 60 分钟，且没有一条完整 episode-sized 轴可定义精对齐查询；系统不会把局部 inlier support 冒充完整时间图。"
                .to_string(),
        )
    }
}

fn project_v2_source_range_to_target(
    source: PresentationRangeMs,
    hypothesis: &AffineHypothesis,
) -> Result<PresentationRangeMs, String> {
    if !hypothesis.scale.is_finite() || hypothesis.scale <= 0.0 {
        return Err("粗定位 affine scale 必须是有限正数。".to_string());
    }
    let projected_start = hypothesis.scale * source.start_ms as f64 + hypothesis.offset_ms as f64;
    let projected_end = hypothesis.scale * source.end_ms as f64 + hypothesis.offset_ms as f64;
    if !projected_start.is_finite() || !projected_end.is_finite() {
        return Err("粗定位 affine 正向投影产生了非有限时间。".to_string());
    }
    let start_ms = v2_checked_f64_milliseconds(projected_start.min(projected_end), f64::floor)?;
    let end_ms = v2_checked_f64_milliseconds(projected_start.max(projected_end), f64::ceil)?;
    if end_ms <= start_ms {
        return Err("粗定位 affine 正向投影没有形成非空目标区间。".to_string());
    }
    Ok(PresentationRangeMs { start_ms, end_ms })
}

fn v2_checked_f64_milliseconds(value: f64, round: fn(f64) -> f64) -> Result<i64, String> {
    let rounded = round(value);
    if !rounded.is_finite() || rounded < i64::MIN as f64 || rounded > i64::MAX as f64 {
        return Err("粗定位 affine 投影毫秒值超出 i64 范围。".to_string());
    }
    Ok(rounded as i64)
}

fn decode_v2_audio_for_selected_window(
    media_path: &str,
    label: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    landmark_artifact: &CachedV2Landmarks,
    requested_window: Option<PresentationRangeMs>,
    cancel_flag: Option<&AtomicBool>,
) -> Result<DecodedV2Audio, String> {
    if !should_stream_v2_coarse_only(input) {
        return decode_v2_audio(
            media_path,
            label,
            options,
            input,
            landmark_artifact,
            cancel_flag,
        );
    }
    let window = requested_window.ok_or_else(|| {
        format!(
            "blocked:window-evidence-insufficient：{label}只有流式粗定位制品，但没有经过 affine 证明的精解码窗口。"
        )
    })?;
    if window.start_ms < landmark_artifact.presentation_bounds.start_ms
        || window.end_ms > landmark_artifact.presentation_bounds.end_ms
    {
        return Err(format!(
            "blocked:window-evidence-insufficient：{label}精解码窗口超出已完整消费的流式 presentation 边界。"
        ));
    }
    let expected_cache_key = create_v2_audio_cache_key_for_backend(
        media_path,
        options,
        input,
        v2_landmark_artifact_kind(input),
        &landmark_artifact.spectral_backend.backend_id,
    )?;
    if landmark_artifact.cache_key != expected_cache_key {
        return Err(format!(
            "blocked:media-identity-changed：{label}粗定位制品与当前内容身份、音轨、PTS 或算法参数不一致。"
        ));
    }
    let pcm = Arc::new(decode_v2_pcm_window(
        media_path,
        label,
        options,
        input,
        landmark_artifact.presentation_bounds,
        window,
        cancel_flag,
        landmark_artifact.identity_guard.as_deref(),
    )?);
    let fine_backend_request =
        lock_fine_spectral_backend_request(&landmark_artifact.spectral_backend)?;
    let fine_extraction = extract_fine_features_with_backend_request(
        &pcm,
        &FineFeatureConfig {
            sample_rate: ALIGNMENT_V2_SAMPLE_RATE,
            // FFmpeg rebases the input-side seek to zero. Reattach every fine frame to the
            // absolute presentation axis here; downstream DP and TimeMap never see seek time.
            presentation_offset_ms: window.start_ms,
            window_ms: 50,
            hop_ms: ALIGNMENT_V2_FINE_HOP_MS,
        },
        cancel_flag,
        &fine_backend_request,
    )?;
    ensure_v2_fine_spectral_backend_continuity(
        &landmark_artifact.spectral_backend,
        &fine_extraction.spectral_backend,
    )?;
    let fine_features = Arc::new(fine_extraction.fine_features);
    if fine_features.is_empty() {
        return Err(format!(
            "{label}精解码窗口没有可用的 50 ms 细粒度音频特征。"
        ));
    }
    Ok(DecodedV2Audio {
        pcm,
        fine_features,
        fine_spectral_backend: fine_extraction.spectral_backend,
        presentation_offset_ms: window.start_ms,
    })
}

// A fine-window decode is a trust boundary: media bounds, the selected window and the pinned
// identity guard must remain explicit instead of being hidden in a loosely reusable context.
#[allow(clippy::too_many_arguments)]
fn decode_v2_pcm_window(
    media_path: &str,
    label: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    media_bounds: PresentationRangeMs,
    window: PresentationRangeMs,
    cancel_flag: Option<&AtomicBool>,
    identity_guard: Option<&PinnedMediaIdentityGuard>,
) -> Result<Vec<i16>, String> {
    check_cancelled(cancel_flag)?;
    let duration_ms = v2_presentation_range_duration_ms(window)?;
    let decode_budget = v2_fine_window_pcm_decode_budget(window)?;
    let seek_ms = window
        .start_ms
        .checked_sub(media_bounds.start_ms)
        .and_then(|value| u64::try_from(value).ok())
        .ok_or_else(|| {
            format!("blocked:window-evidence-insufficient：{label}精解码 seek 早于媒体 PCM 起点。")
        })?;
    verify_media_content_identity_before_tool_input_or_pinned(
        identity_guard,
        media_path,
        input.content_identity.as_ref(),
        cancel_flag,
        "V2 affine 窗口精解码",
    )?;
    let output_result = run_supervised_ffmpeg_output(
        &options.ffmpeg_path,
        create_v2_fine_window_audio_decode_args(media_path, input, seek_ms, duration_ms),
        "FFmpeg V2 affine 窗口精解码",
        decode_budget.stdout_hard_limit_bytes,
        cancel_flag,
    );
    // As in streaming coarse, identity/cleanup failure invalidates every decoded byte and takes
    // precedence over an ordinary codec failure.
    verify_media_content_identity_after_tool_output_or_pinned(
        identity_guard,
        media_path,
        input.content_identity.as_ref(),
        cancel_flag,
        "V2 affine 窗口精解码",
    )?;
    let output = output_result?;
    if !output.status.success() {
        return Err(format_media_tool_nonzero_exit(
            &format!("FFmpeg 提取 {label} V2 affine 窗口 PCM"),
            output.status.code(),
            &output.stderr,
        ));
    }
    let mut pcm = parse_v2_pcm_output(&output.stdout, label, cancel_flag)?;
    let actual_duration_ms =
        v2_presentation_range_duration_ms(v2_presentation_bounds_for_samples(
            window.start_ms,
            u64::try_from(pcm.len())
                .map_err(|_| "blocked:resource-limit：精解码 PCM 样本数无法表示。".to_string())?,
        )?)?;
    if actual_duration_ms.saturating_add(ALIGNMENT_V2_FINE_WINDOW_DECODE_TOLERANCE_MS) < duration_ms
    {
        return Err(format!(
            "blocked:decode-window-short：{label}请求 {duration_ms} ms 精解码窗口，但受监督 FFmpeg 只返回 {actual_duration_ms} ms；不会用缺失尾部生成时间图。"
        ));
    }
    let maximum_samples = usize::try_from(
        (u128::from(duration_ms) * u128::from(ALIGNMENT_V2_SAMPLE_RATE)).div_ceil(1_000),
    )
    .map_err(|_| "blocked:resource-limit：精解码样本上限无法表示。".to_string())?;
    pcm.truncate(maximum_samples);
    check_cancelled(cancel_flag)?;
    Ok(pcm)
}

fn create_v2_fine_window_audio_decode_args(
    media_path: &str,
    input: &AlignmentAudioInput,
    seek_ms: u64,
    duration_ms: u64,
) -> Vec<String> {
    vec![
        "-nostdin".to_string(),
        "-v".to_string(),
        "error".to_string(),
        // Input-side accurate seeking prevents a 20-hour compilation from being decoded from
        // byte zero. FFmpeg rebases the selected interval; absolute presentation time is restored
        // on FineFeatureConfig and BoundaryRefinementConfig, not inferred from stdout.
        "-ss".to_string(),
        format!("{:.3}", seek_ms as f64 / 1_000.0),
        "-accurate_seek".to_string(),
        "-i".to_string(),
        media_path.to_string(),
        "-map".to_string(),
        format!("0:{}", input.stream.stream_index),
        "-vn".to_string(),
        "-ac".to_string(),
        "1".to_string(),
        "-af".to_string(),
        format!("aresample={ALIGNMENT_V2_SAMPLE_RATE}:async=1:first_pts=0"),
        // Output-side -t and the independent stdout hard limit are both required. Neither can be
        // removed without reintroducing whole-file PCM risk for unknown-duration media.
        "-t".to_string(),
        format!("{:.3}", duration_ms as f64 / 1_000.0),
        "-f".to_string(),
        "s16le".to_string(),
        "pipe:1".to_string(),
    ]
}

struct V2S16LeLandmarkStream {
    extractor: StreamingLandmarkExtractor,
    pending_low_byte: Option<u8>,
    sample_buffer: Vec<i16>,
    decoded_samples: u64,
}

impl V2S16LeLandmarkStream {
    #[cfg(test)]
    fn new(config: LandmarkConfig) -> Result<Self, String> {
        Self::from_extractor(StreamingLandmarkExtractor::new(config)?)
    }

    fn new_with_backend_request(
        config: LandmarkConfig,
        backend_request: &SpectralBackendRequest,
    ) -> Result<Self, String> {
        Self::from_extractor(StreamingLandmarkExtractor::new_with_backend_request(
            config,
            backend_request,
        )?)
    }

    fn from_extractor(extractor: StreamingLandmarkExtractor) -> Result<Self, String> {
        let mut sample_buffer = Vec::new();
        sample_buffer
            .try_reserve_exact(ALIGNMENT_V2_COARSE_STDOUT_CHUNK_BYTES / 2 + 1)
            .map_err(|_| "blocked:resource-limit：无法为流式 PCM 小块保留工作内存。".to_string())?;
        Ok(Self {
            extractor,
            pending_low_byte: None,
            sample_buffer,
            decoded_samples: 0,
        })
    }

    fn consume_chunk(
        &mut self,
        bytes: &[u8],
        cancel_flag: Option<&AtomicBool>,
    ) -> Result<(), String> {
        check_cancelled(cancel_flag)?;
        if bytes.len() > ALIGNMENT_V2_COARSE_STDOUT_CHUNK_BYTES {
            return Err(
                "blocked:resource-limit：流式 PCM reader 返回了超过约定上限的数据块。".to_string(),
            );
        }
        self.sample_buffer.clear();
        let mut offset = 0usize;
        if let Some(low) = self.pending_low_byte.take() {
            let Some(high) = bytes.first().copied() else {
                self.pending_low_byte = Some(low);
                return Ok(());
            };
            self.sample_buffer.push(i16::from_le_bytes([low, high]));
            offset = 1;
        }
        let paired_end = offset + (bytes.len() - offset) / 2 * 2;
        self.sample_buffer.extend(
            bytes[offset..paired_end]
                .chunks_exact(2)
                .map(|sample| i16::from_le_bytes([sample[0], sample[1]])),
        );
        if paired_end < bytes.len() {
            self.pending_low_byte = Some(bytes[paired_end]);
        }
        if self.sample_buffer.is_empty() {
            return Ok(());
        }
        self.decoded_samples = self
            .decoded_samples
            .checked_add(self.sample_buffer.len() as u64)
            .ok_or_else(|| "blocked:resource-limit：流式 PCM 样本计数溢出。".to_string())?;
        self.extractor
            .push_pcm_with_cancel(&self.sample_buffer, cancel_flag)
            .map_err(map_v2_streaming_algorithm_error)
    }

    fn finish(
        self,
        stdout_bytes: usize,
        label: &str,
        cancel_flag: Option<&AtomicBool>,
    ) -> Result<DecodedV2CoarseLandmarks, String> {
        check_cancelled(cancel_flag)?;
        if self.pending_low_byte.is_some() {
            return Err(format!(
                "blocked:decode-format：{label}流式 V2 PCM 在 EOF 留下未配对字节。"
            ));
        }
        let decoded_bytes = self
            .decoded_samples
            .checked_mul(2)
            .ok_or_else(|| "blocked:resource-limit：流式 PCM 字节计数溢出。".to_string())?;
        let observed_bytes = u64::try_from(stdout_bytes)
            .map_err(|_| "blocked:resource-limit：流式 stdout 字节计数无法表示。".to_string())?;
        if decoded_bytes != observed_bytes {
            return Err(format!(
                "blocked:decode-format：{label}流式 V2 PCM 样本数与 stdout 字节数不一致。"
            ));
        }
        let decoded_sample_count = self.decoded_samples;
        let extraction = self
            .extractor
            .finish_with_backend_and_cancel(cancel_flag)
            .map_err(map_v2_streaming_algorithm_error)?;
        Ok(DecodedV2CoarseLandmarks {
            index: extraction.index,
            coarse_fingerprint: extraction.coarse_fingerprint,
            decoded_sample_count,
            spectral_backend: extraction.spectral_backend,
        })
    }
}

fn map_v2_streaming_algorithm_error(error: String) -> String {
    if error.starts_with("blocked:") {
        error
    } else if error.contains("已取消") {
        AUDIO_ALIGNMENT_CANCELLED.to_string()
    } else if error.contains("上限") || error.contains("保留内存") || error.contains("溢出")
    {
        format!("blocked:resource-limit：流式粗定位算法拒绝了不可控工作量：{error}")
    } else {
        format!("流式粗定位算法失败：{error}")
    }
}

fn decode_v2_coarse_landmarks_streaming(
    media_path: &str,
    label: &str,
    options: &AudioAlignmentOptions,
    input: &AlignmentAudioInput,
    backend_request: &SpectralBackendRequest,
    cancel_flag: Option<&AtomicBool>,
    identity_guard: Option<&PinnedMediaIdentityGuard>,
) -> Result<DecodedV2CoarseLandmarks, String> {
    check_cancelled(cancel_flag)?;
    verify_media_content_identity_before_tool_input_or_pinned(
        identity_guard,
        media_path,
        input.content_identity.as_ref(),
        cancel_flag,
        "V2 流式粗定位解码",
    )?;
    let stdout_duration_budget_ms = v2_coarse_stdout_duration_budget_ms(input)?;
    let stdout_hard_limit = v2_pcm_bytes_for_duration_ms(stdout_duration_budget_ms)
        .ok_or_else(|| "blocked:resource-limit：流式粗定位 stdout 上限无法表示。".to_string())?;
    let presentation_offset_ms = input
        .decode_timeline
        .as_ref()
        .map(|item| item.normalized_pcm_origin_ms)
        .unwrap_or(0);
    let mut consumer = V2S16LeLandmarkStream::new_with_backend_request(
        LandmarkConfig {
            sample_rate: ALIGNMENT_V2_SAMPLE_RATE,
            presentation_offset_ms,
            window_ms: 50,
            hop_ms: ALIGNMENT_V2_LANDMARK_HOP_MS,
            max_hash_occurrences: 64,
            ..LandmarkConfig::default()
        },
        backend_request,
    )?;
    let mut consumer_error = None;
    let output_result = run_supervised_ffmpeg_streaming(
        &options.ffmpeg_path,
        create_v2_coarse_audio_decode_args(media_path, input),
        "FFmpeg V2 流式粗定位解码",
        stdout_hard_limit,
        cancel_flag,
        |chunk| match consumer.consume_chunk(chunk, cancel_flag) {
            Ok(()) => Ok(()),
            Err(error) => {
                consumer_error = Some(error);
                Err("streaming PCM consumer rejected a chunk".to_string())
            }
        },
    );
    // Recheck even when the tool or consumer failed. Identity/cleanup failures invalidate every
    // byte already consumed and take precedence over an ordinary decode error.
    verify_media_content_identity_after_tool_output_or_pinned(
        identity_guard,
        media_path,
        input.content_identity.as_ref(),
        cancel_flag,
        "V2 流式粗定位解码",
    )?;
    if let Some(error) = consumer_error {
        return Err(error);
    }
    let output = output_result?;
    if !output.status.success() {
        return Err(format_media_tool_nonzero_exit(
            &format!("FFmpeg 提取 {label} V2 流式粗定位 PCM"),
            output.status.code(),
            &output.stderr,
        ));
    }
    consumer.finish(output.stdout_bytes, label, cancel_flag)
}

fn v2_coarse_stdout_duration_budget_ms(input: &AlignmentAudioInput) -> Result<u64, String> {
    let Some(media_duration_ms) = input.media_duration_ms else {
        // Unknown-duration media are decoded through EOF with no FFmpeg `-t`; the stdout hard
        // limit becomes the fail-closed 24-hour boundary instead of silently truncating success.
        return Ok(ALIGNMENT_V2_COARSE_MAX_DURATION_MS);
    };
    if media_duration_ms > ALIGNMENT_V2_COARSE_MAX_DURATION_MS {
        return Err(format!(
            "blocked:resource-limit：流式粗定位当前最多接受 {} 小时媒体。",
            ALIGNMENT_V2_COARSE_MAX_DURATION_MS / (60 * 60 * 1_000)
        ));
    }
    media_duration_ms
        .checked_add(ALIGNMENT_V2_COARSE_DURATION_SLACK_MS)
        .ok_or_else(|| "blocked:resource-limit：流式粗定位时长上限溢出。".to_string())
}

