    #[test]
    fn v2_no_range_block_omits_time_map_but_affine_block_is_valid_ambiguous_map() {
        let without_range =
            create_blocked_v2_proposal("没有共同音轨。", None, None, None, Vec::new(), Vec::new());
        assert!(without_range.time_map.is_none());
        assert!(without_range.match_range.is_none());

        let mut pair = v2_test_pair_candidate();
        pair.temporal_coverage = 0.91;
        pair.hypothesis.unique_source_coverage = 0.93;
        let with_affine = create_blocked_v2_affine_proposal(
            "Top1/Top2 歧义。",
            &pair,
            0.02,
            vec![v2_alternative_track_score(&pair)],
            Vec::new(),
        );
        let time_map = with_affine.time_map.as_ref().unwrap();
        assert_eq!(time_map.quality.level, "blocked");
        assert!(time_map.quality.probability.is_none());
        assert_eq!(time_map.quality.coverage, Some(0.0));
        assert_eq!(time_map.quality.unique_content_coverage, Some(0.0));
        assert_eq!(time_map.quality.p50_residual_ms, None);
        assert_eq!(time_map.quality.p95_residual_ms, None);
        assert_eq!(time_map.quality.p99_residual_ms, None);
        assert_eq!(time_map.quality.max_residual_ms, None);
        assert_eq!(time_map.spans.len(), 1);
        assert_eq!(time_map.spans[0].kind, AudioTimeMapSpanKind::Ambiguous);
        assert_eq!(time_map.spans[0].quality.coverage, Some(0.0));
        assert!(time_map.source_end_ms > time_map.source_start_ms);
        assert!(time_map.target_end_ms > time_map.target_start_ms);
        validate_v2_time_map_spans(&time_map.spans).unwrap();
        assert_eq!(with_affine.match_range.as_ref().unwrap().coverage, 0.0);
        assert!(time_map
            .quality
            .reasons
            .iter()
            .any(|reason| reason.contains("不会回退 coarse affine")));
        assert!(with_affine
            .diagnostics
            .iter()
            .any(|line| line.contains("未使用 coarse residual fallback")));
    }

    #[test]
    fn supervised_ffmpeg_streaming_coarse_uses_real_media_and_identity_gates() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过 V2 流式 coarse 集成测试：ffmpeg/ffprobe 不可用。");
            return;
        }
        let directory = std::env::temp_dir().join(format!(
            "alignment-v2-streaming-coarse-{}-{}",
            std::process::id(),
            current_time_ms()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let media_path = directory.join("streaming-coarse.mka");
        generate_v2_ffmpeg_fixture(&media_path, "[0:a]anull[main]", "0", "440");
        let path_text = media_path.to_string_lossy().to_string();
        let snapshot = probe_media_timeline_with_ffprobe(&path_text, Path::new("ffprobe")).unwrap();
        let timelines =
            probe_audio_decode_timelines_with_ffprobe(&path_text, Path::new("ffprobe")).unwrap();
        let stream = snapshot.audio_streams[0].clone();
        let timeline = timelines.get(&stream.stream_index).cloned();
        let input = alignment_audio_input_from_snapshot(&snapshot, stream, true, timeline);
        let options = test_options();
        let backend_request = &options.spectral_backend_request;

        let coarse = decode_v2_coarse_landmarks_streaming(
            &path_text,
            "真实 fixture",
            &options,
            &input,
            backend_request,
            None,
            None,
        )
        .unwrap();
        assert!(!coarse.index.landmarks.is_empty());
        assert!(
            coarse.index.observed_landmark_count >= coarse.index.retained_landmark_count as u64
        );
        assert!(coarse.index.retained_landmark_count <= ALIGNMENT_V2_COARSE_MAX_LANDMARKS);
        assert!(coarse.decoded_sample_count > 0);

        let mut synthetic_long_input = input.clone();
        synthetic_long_input.media_duration_ms = Some(ALIGNMENT_V2_MAX_DURATION_MS + 1);
        let coarse_artifact = get_v2_landmarks(
            &path_text,
            "真实 fixture",
            &test_options(),
            &synthetic_long_input,
            V2LandmarkExtractionContext {
                cancel_flag: None,
                shared_backend_request: None,
                cache_plan: None,
                retained_artifact_bytes: 0,
                identity_guard: None,
            },
        )
        .unwrap();
        assert!(coarse_artifact.pcm.is_none());
        assert!(coarse_artifact.fine_features.is_none());
        assert!(coarse_artifact
            .cache_key
            .contains("artifact=landmark-streaming-coarse"));
        let fine_error = decode_v2_audio(
            &path_text,
            "真实 fixture",
            &test_options(),
            &synthetic_long_input,
            &coarse_artifact,
            None,
        )
        .unwrap_err();
        assert!(fine_error.starts_with("blocked:resource-limit"));

        let fine_window = PresentationRangeMs {
            start_ms: 2_000,
            end_ms: 6_000,
        };
        let window_audio = decode_v2_audio_for_selected_window(
            &path_text,
            "真实 fixture",
            &test_options(),
            &synthetic_long_input,
            &coarse_artifact,
            Some(fine_window),
            None,
        )
        .unwrap();
        assert_eq!(window_audio.presentation_offset_ms, 2_000);
        assert_eq!(
            window_audio.fine_spectral_backend.backend_id,
            lock_fine_spectral_backend_request(&coarse_artifact.spectral_backend)
                .unwrap()
                .planned_backend_id
        );
        assert_eq!(
            window_audio.fine_features.first().unwrap().time_ms,
            2_025,
            "windowed fine features must return to absolute presentation time"
        );
        assert!(window_audio.pcm.len() <= ALIGNMENT_V2_SAMPLE_RATE as usize * 4);
        assert!(window_audio.pcm.len() >= ALIGNMENT_V2_SAMPLE_RATE as usize * 4 - 16);

        let mut stale = input.clone();
        let mut stale_identity = stale.content_identity.clone().unwrap();
        stale_identity.first_sample_digest = "b".repeat(64);
        stale_identity.middle_sample_digest = stale_identity.first_sample_digest.clone();
        stale_identity.last_sample_digest = stale_identity.first_sample_digest.clone();
        stale.content_identity = Some(stale_identity);
        let mut must_not_spawn = test_options();
        must_not_spawn.ffmpeg_path = r"C:\Users\alice\private\must-not-run.exe".to_string();
        let identity_error = decode_v2_coarse_landmarks_streaming(
            &path_text,
            "真实 fixture",
            &must_not_spawn,
            &stale,
            backend_request,
            None,
            None,
        )
        .unwrap_err();
        assert!(identity_error.starts_with("blocked:media-identity-changed"));
        assert!(!identity_error.contains("alice"));
        assert!(!identity_error.contains("must-not-run"));

        let mut stale_long = synthetic_long_input.clone();
        stale_long.content_identity = stale.content_identity.clone();
        let window_identity_error = decode_v2_audio_for_selected_window(
            &path_text,
            "真实 fixture",
            &must_not_spawn,
            &stale_long,
            &coarse_artifact,
            Some(fine_window),
            None,
        )
        .unwrap_err();
        assert!(window_identity_error.starts_with("blocked:media-identity-changed"));
        assert!(!window_identity_error.contains("alice"));
        assert!(!window_identity_error.contains("must-not-run"));

        let cancelled = AtomicBool::new(true);
        let cancel_error = decode_v2_coarse_landmarks_streaming(
            &path_text,
            "真实 fixture",
            &test_options(),
            &input,
            backend_request,
            Some(&cancelled),
            None,
        )
        .unwrap_err();
        assert_eq!(cancel_error, AUDIO_ALIGNMENT_CANCELLED);
        let _ = std::fs::remove_dir_all(directory);
    }

    #[test]
    fn supervised_ffmpeg_streaming_propagates_live_cancellation() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过 V2 流式取消测试：ffmpeg/ffprobe 不可用。");
            return;
        }
        let cancelled = AtomicBool::new(false);
        let mut chunk_count = 0usize;
        let error = run_supervised_ffmpeg_streaming(
            "ffmpeg",
            [
                "-nostdin",
                "-v",
                "error",
                "-f",
                "lavfi",
                "-i",
                "anullsrc=r=16000:cl=mono",
                "-f",
                "s16le",
                "pipe:1",
            ],
            "FFmpeg V2 流式取消测试",
            v2_pcm_bytes_for_duration_ms(ALIGNMENT_V2_COARSE_MAX_DURATION_MS).unwrap(),
            Some(&cancelled),
            |_| {
                chunk_count += 1;
                cancelled.store(true, Ordering::Release);
                Ok(())
            },
        )
        .unwrap_err();

        assert_eq!(error, AUDIO_ALIGNMENT_CANCELLED);
        assert!(chunk_count > 0);
    }

    #[test]
    fn ffmpeg_v2_integration_keeps_pts_avoids_commentary_and_models_bilateral_edits() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过 Alignment V2 FFmpeg 集成测试：ffmpeg/ffprobe 不可用。");
            return;
        }
        let directory = std::env::temp_dir().join(format!(
            "alignment-v2-ffmpeg-{}-{}",
            std::process::id(),
            current_time_ms()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let source_path = directory.join("source-negative-pts.mka");
        let target_path = directory.join("target-positive-pts.mka");
        generate_v2_ffmpeg_fixture(
            &source_path,
            "[0:a]asplit=2[x0][x1];[x0]atrim=start=0:end=5,asetpts=PTS-STARTPTS[a0];[x1]atrim=start=6:end=16,asetpts=PTS-STARTPTS[a1];[a0][a1]concat=n=2:v=0:a=1[main]",
            "-0.25",
            "440",
        );
        generate_v2_ffmpeg_fixture(
            &target_path,
            "[0:a]asplit=2[x0][x1];[x0]atrim=start=0:end=11,asetpts=PTS-STARTPTS[a0];[x1]atrim=start=12:end=16,asetpts=PTS-STARTPTS[a1];[a0][a1]concat=n=2:v=0:a=1,atempo=0.980392[main]",
            "0.5",
            "660",
        );
        let request = || AudioAlignmentRequest {
            complete_path: target_path.to_string_lossy().to_string(),
            source_path: source_path.to_string_lossy().to_string(),
            ffmpeg_path: Some("ffmpeg".to_string()),
            ffprobe_path: Some("ffprobe".to_string()),
            complete_audio_stream_index: None,
            source_audio_stream_index: None,
            complete_video_stream_index: None,
            source_video_stream_index: None,
            spectral_backend: Some(SpectralBackendPreference::Cpu),
            sample_rate: None,
            window_ms: None,
            match_threshold: None,
            min_gap_ms: None,
            max_cells: Some(ALIGNMENT_V2_MAX_DP_CELLS),
            enable_visual_evidence: Some(false),
            visual_sample_interval_ms: None,
            localization_mode: Some(true),
        };
        reset_test_v2_pcm_decode_invocations();
        let proposal = align_audio_files_inner(request()).unwrap();
        assert_eq!(
            test_v2_pcm_decode_invocations(),
            2,
            "两个所选主音轨应各只解码一次；粗定位后不得为细对齐再次调用 FFmpeg"
        );
        let time_map = proposal.time_map.as_ref().unwrap_or_else(|| {
            panic!(
                "V2 应输出合法时间图；diagnostics={:?}",
                proposal.diagnostics
            )
        });

        assert_eq!(time_map.engine_version, ALIGNMENT_V2_ENGINE_VERSION);
        assert_eq!(time_map.feature_version, ALIGNMENT_V2_FEATURE_VERSION);
        assert_ne!(time_map.quality.level, "verified");
        assert!(time_map.quality.probability.is_none());
        assert_eq!(time_map.source_stream.as_ref().unwrap().index, 0);
        assert_eq!(time_map.target_stream.as_ref().unwrap().index, 0);
        assert_eq!(
            time_map.source_stream.as_ref().unwrap().start_ms,
            Some(-250)
        );
        assert_eq!(time_map.target_stream.as_ref().unwrap().start_ms, Some(500));
        assert_eq!(
            time_map.source_stream.as_ref().unwrap().timeline_offset_ms,
            Some(0)
        );
        assert_v2_bilateral_edit_gold(time_map);
        assert!(time_map.evidence.selected_track_reason.contains("音轨 #0"));
        assert!((time_map.evidence.alternative_track_scores[0].scale - 1.02).abs() < 0.01);
        let expected_backend = if std::env::var("C137_REQUIRE_CUDA_FFT").as_deref() == Ok("1")
            || std::env::var("C137_SPECTRAL_BACKEND").as_deref() == Ok("cuda")
        {
            crate::cuda_fft_backend::CUDA_FFT_BACKEND_ID
        } else {
            crate::alignment_v2::CPU_SPECTRAL_BACKEND_ID
        };
        assert!(proposal.diagnostics.join("\n").contains(expected_backend));

        let cached_proposal = align_audio_files_inner(request()).unwrap();
        assert_eq!(
            test_v2_pcm_decode_invocations(),
            2,
            "第二次对齐必须复用按实际声谱后端隔离的制品"
        );
        let cached_diagnostics = cached_proposal.diagnostics.join("\n");
        assert!(cached_diagnostics.contains("缓存命中"));
        assert!(cached_diagnostics.contains(expected_backend));
        let _ = std::fs::remove_dir_all(directory);
    }

    #[test]
    fn public_ffmpeg_batch_pins_tools_deduplicates_hardlink_alias_and_returns_time_map() {
        if !ffmpeg_test_tools_available() {
            eprintln!("跳过真实普通 batch 集成测试：ffmpeg/ffprobe 不可用。");
            return;
        }
        let directory = std::env::temp_dir().join(format!(
            "alignment-v2-public-batch-{}-{}",
            std::process::id(),
            current_time_ms()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let source_path = directory.join("source.mka");
        let source_alias_path = directory.join("source-hardlink-alias.mka");
        let target_path = directory.join("target.mka");
        generate_v2_ffmpeg_fixture(&source_path, "[0:a]anull[main]", "0", "440");
        generate_v2_ffmpeg_fixture(&target_path, "[0:a]anull[main]", "0.5", "660");
        std::fs::hard_link(&source_path, &source_alias_path).unwrap();

        let request = AudioAlignmentBatchRequest {
            schema_version: AUDIO_ALIGNMENT_BATCH_SCHEMA_VERSION,
            sources: vec![
                AudioAlignmentBatchMediaRequest {
                    media_id: "source-primary".to_string(),
                    path: source_path.to_string_lossy().into_owned(),
                    audio_stream_index: None,
                    video_stream_index: None,
                },
                AudioAlignmentBatchMediaRequest {
                    media_id: "source-alias".to_string(),
                    path: source_alias_path.to_string_lossy().into_owned(),
                    audio_stream_index: None,
                    video_stream_index: None,
                },
                AudioAlignmentBatchMediaRequest {
                    media_id: "source-alias-invalid-stream".to_string(),
                    path: source_alias_path.to_string_lossy().into_owned(),
                    audio_stream_index: Some(999),
                    video_stream_index: None,
                },
            ],
            version_reuse_groups: Vec::new(),
            targets: vec![AudioAlignmentBatchMediaRequest {
                media_id: "target".to_string(),
                path: target_path.to_string_lossy().into_owned(),
                audio_stream_index: None,
                video_stream_index: None,
            }],
            pairs: Some(vec![
                AudioAlignmentBatchPairRequest {
                    source_media_id: "source-primary".to_string(),
                    target_media_id: "target".to_string(),
                },
                AudioAlignmentBatchPairRequest {
                    source_media_id: "source-alias".to_string(),
                    target_media_id: "target".to_string(),
                },
                AudioAlignmentBatchPairRequest {
                    source_media_id: "source-alias-invalid-stream".to_string(),
                    target_media_id: "target".to_string(),
                },
            ]),
            ffmpeg_path: Some("ffmpeg".to_string()),
            ffprobe_path: Some("ffprobe".to_string()),
            spectral_backend: Some(SpectralBackendPreference::Cpu),
            sample_rate: None,
            window_ms: None,
            match_threshold: None,
            min_gap_ms: None,
            max_cells: Some(ALIGNMENT_V2_MAX_DP_CELLS),
            enable_visual_evidence: Some(false),
            visual_sample_interval_ms: None,
            localization_mode: Some(true),
        };

        let mut alias_plan = plan_audio_alignment_batch(request.clone()).unwrap();
        let (options, toolchain) =
            create_pinned_audio_alignment_options(&alias_plan.pairs[0].request).unwrap();
        let prepared = prepare_audio_alignment_batch_media(
            &alias_plan,
            &options,
            &AtomicBool::new(false),
            None,
        )
        .unwrap();
        let PreparedAudioAlignmentBatchMediaState::Ready(first_source) = &prepared[0] else {
            panic!("primary source preparation failed");
        };
        let PreparedAudioAlignmentBatchMediaState::Ready(alias_source) = &prepared[1] else {
            panic!("hard-link source alias preparation failed");
        };
        let PreparedAudioAlignmentBatchMediaState::Failed {
            physical_group_index: Some(failed_alias_group),
            ..
        } = &prepared[2]
        else {
            panic!("invalid-stream hard-link alias must retain its physical group");
        };
        assert!(
            Arc::ptr_eq(first_source, alias_source),
            "同一 physical file + stream 的逻辑别名必须复用一次 FFprobe/FFT 制品"
        );
        bind_audio_alignment_batch_physical_groups(&mut alias_plan, &prepared).unwrap();
        assert_eq!(
            alias_plan.pairs[0].source_physical_media_index,
            alias_plan.pairs[1].source_physical_media_index
        );
        assert_eq!(
            alias_plan.pairs[0].source_physical_media_index,
            *failed_alias_group
        );
        assert_eq!(
            alias_plan.pairs[0].source_physical_media_index,
            alias_plan.pairs[2].source_physical_media_index
        );
        let mut invalid_version_group_request = request.clone();
        invalid_version_group_request.version_reuse_groups =
            vec![AudioAlignmentBatchVersionReuseGroupRequest {
                group_id: "aliased-source-versions".to_string(),
                side: AudioAlignmentBatchVersionGroupSide::Source,
                media_ids: vec!["source-primary".to_string(), "source-alias".to_string()],
            }];
        let mut invalid_version_group_plan =
            plan_audio_alignment_batch(invalid_version_group_request).unwrap();
        let alias_error =
            bind_audio_alignment_batch_physical_groups(&mut invalid_version_group_plan, &prepared)
                .expect_err("hard-link aliases cannot masquerade as distinct versions");
        assert!(alias_error.starts_with("blocked:version-reuse-alias"));
        drop(prepared);
        toolchain.verify_at_finalization().unwrap();
        drop(toolchain);

        let mut public_request = request;
        public_request.sources.truncate(1);
        public_request.pairs = Some(vec![AudioAlignmentBatchPairRequest {
            source_media_id: "source-primary".to_string(),
            target_media_id: "target".to_string(),
        }]);
        let plan = plan_audio_alignment_batch(public_request).unwrap();
        let job_id = format!("test-public-ffmpeg-batch-{}", current_time_ms());
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag.clone()).unwrap();
        run_audio_alignment_batch_job(job_id.clone(), cancel_flag, plan);
        let terminal = get_audio_alignment_batch_job(job_id).unwrap();
        assert_eq!(
            terminal.status,
            AudioAlignmentJobStatus::Completed,
            "batch error={:?}; pair error={:?}; pair message={}",
            terminal.error,
            terminal.pairs[0].error,
            terminal.pairs[0].message
        );
        assert_eq!(terminal.failed_pair_count, 0);
        let proposal = terminal.pairs[0]
            .proposal
            .as_ref()
            .expect("普通 batch 必须返回可复核 proposal");
        let fine_execution = terminal.pairs[0]
            .fine_execution_evidence
            .as_ref()
            .unwrap_or_else(|| {
                panic!(
                    "真实短媒体 batch 必须绑定 fine execution evidence；proposal diagnostics={:?}",
                    proposal.diagnostics
                )
            });
        for (coarse, fine) in [
            (
                &fine_execution.source_coarse_backend,
                &fine_execution.source_fine_backend,
            ),
            (
                &fine_execution.target_coarse_backend,
                &fine_execution.target_fine_backend,
            ),
        ] {
            validate_audio_alignment_batch_fine_backend_continuity(coarse, fine).unwrap();
            let locked = lock_fine_spectral_backend_request(&SpectralBackendExecution {
                backend_id: coarse.backend_id.clone(),
                requested_backend: coarse.requested_backend.clone(),
                backend_detail: coarse.backend_detail.clone(),
                fallback_reason: coarse.fallback_reason.clone(),
            })
            .unwrap();
            assert_eq!(fine.backend_id, locked.planned_backend_id);
            assert_eq!(fine.requested_backend, locked.requested_backend);
            assert_eq!(fine.backend_detail, locked.backend_detail);
            assert_eq!(fine.fallback_reason, locked.fallback_reason);
        }
        let time_map = proposal
            .time_map
            .as_ref()
            .expect("真实相同主音轨应由普通 batch 返回 timeMap");
        assert_eq!(time_map.feature_version, ALIGNMENT_V2_FEATURE_VERSION);
        assert_ne!(time_map.quality.level, "verified");
        assert!(time_map.quality.probability.is_none());
        let _ = std::fs::remove_dir_all(directory);
    }

