    #[test]
    fn audio_alignment_batch_worker_isolates_missing_paths_and_continues() {
        let suffix = format!("{}-{}", std::process::id(), current_time_ms());
        let valid_source = std::env::temp_dir().join(format!("batch-valid-source-{suffix}.mkv"));
        let valid_target = std::env::temp_dir().join(format!("batch-valid-target-{suffix}.mkv"));
        let missing_source =
            std::env::temp_dir().join(format!("batch-missing-source-{suffix}.mkv"));
        std::fs::write(&valid_source, b"source").unwrap();
        std::fs::write(&valid_target, b"target").unwrap();

        let mut request = test_audio_alignment_batch_request(Some(vec![
            ("source-1", "target-1"),
            ("source-2", "target-2"),
        ]));
        request.sources[0].path = missing_source.to_string_lossy().into_owned();
        request.sources[1].path = valid_source.to_string_lossy().into_owned();
        request.targets[0].path = valid_target.to_string_lossy().into_owned();
        request.targets[1].path = valid_target.to_string_lossy().into_owned();
        let plan = test_plan_with_selected_global_evidence(
            plan_audio_alignment_batch(request)
                .expect("缺失的本地文件应在 pair worker 内失败，而不是阻止批次规划"),
        );
        let job_id = format!("test-audio-batch-path-isolation-{suffix}");
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag.clone()).unwrap();
        let mut executed_source_paths = Vec::new();

        run_audio_alignment_batch_job_with_pair_executor(
            job_id.clone(),
            cancel_flag,
            plan,
            |_job_id, _pair_index, pair, _cancel_flag| {
                executed_source_paths.push(pair.request.source_path.clone());
                validate_media_input(&pair.request.complete_path, "目标原片")?;
                validate_media_input(&pair.request.source_path, "B 站参考")?;
                Ok(test_audio_alignment_batch_proposal("valid-pair"))
            },
        );

        let terminal = get_audio_alignment_batch_job(job_id).unwrap();
        assert_eq!(executed_source_paths.len(), 2);
        assert_eq!(terminal.status, AudioAlignmentJobStatus::Completed);
        assert_eq!(terminal.failed_pair_count, 1);
        assert_eq!(terminal.pairs[0].status, AudioAlignmentJobStatus::Failed);
        assert!(terminal.pairs[0].proposal.is_none());
        assert_eq!(
            terminal.pairs[0].global_selection.state,
            AudioAlignmentBatchGlobalSelectionState::Failed
        );
        assert_eq!(
            terminal.pairs[0].relation_ranking.state,
            AudioAlignmentBatchRelationRankingState::Ranked,
            "fine/worker failure must retain the pre-assignment coarse relation fact"
        );
        assert_eq!(terminal.pairs[0].relation_ranking.score, Some(0.8));
        assert!(!terminal.pairs[0].global_selection.selected);
        assert!(terminal.pairs[0]
            .global_selection
            .top_k
            .iter()
            .all(|candidate| !candidate.global_selected));
        assert_eq!(terminal.pairs[1].status, AudioAlignmentJobStatus::Completed);
        assert!(terminal.pairs[1].proposal.is_some());
        assert_eq!(
            terminal.pairs[1].global_selection.state,
            AudioAlignmentBatchGlobalSelectionState::Selected
        );

        std::fs::remove_file(valid_source).unwrap();
        std::fs::remove_file(valid_target).unwrap();
    }

    #[test]
    fn audio_alignment_batch_cancel_discards_pre_proof_staged_pairs() {
        let plan = test_plan_with_selected_global_evidence(
            plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![
                ("source-1", "target-1"),
                ("source-2", "target-2"),
            ])))
            .unwrap(),
        );
        let job_id = format!("test-audio-batch-cancel-{}", current_time_ms());
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag.clone()).unwrap();
        let mut cancellation_verifier_called = false;
        run_audio_alignment_batch_job_with_pair_executor_and_finalizer(
            job_id.clone(),
            cancel_flag.clone(),
            plan,
            |running_job_id, pair_index, _pair, _cancel_flag| {
                if pair_index == 0 {
                    return Ok(test_audio_alignment_batch_proposal(
                        "completed-before-cancel",
                    ));
                }
                let before_cancel =
                    get_audio_alignment_batch_job(running_job_id.to_string()).unwrap();
                assert!(before_cancel.pairs[0].proposal.is_none());
                assert_ne!(
                    before_cancel.pairs[0].status,
                    AudioAlignmentJobStatus::Completed
                );
                let requested =
                    cancel_audio_alignment_batch_job(running_job_id.to_string()).unwrap();
                assert!(requested.message.contains("正在取消"));
                Err(AUDIO_ALIGNMENT_CANCELLED.to_string())
            },
            |completed_pair_indices, ignore_cancel| {
                cancellation_verifier_called = true;
                assert!(ignore_cancel);
                assert_eq!(completed_pair_indices, &[0]);
                Ok(())
            },
        );
        assert!(cancellation_verifier_called);
        assert!(cancel_flag.load(Ordering::Acquire));
        let terminal = get_audio_alignment_batch_job(job_id).unwrap();
        assert_eq!(terminal.status, AudioAlignmentJobStatus::Cancelled);
        assert_eq!(terminal.processed_pair_count, 0);
        assert_eq!(terminal.pairs[0].status, AudioAlignmentJobStatus::Cancelled);
        assert!(terminal.pairs[0].proposal.is_none());
        assert_eq!(
            terminal.pairs[0].global_selection.state,
            AudioAlignmentBatchGlobalSelectionState::Cancelled
        );
        assert_eq!(terminal.pairs[1].status, AudioAlignmentJobStatus::Cancelled);
        assert!(terminal.pairs[1].proposal.is_none());
        assert_eq!(
            terminal.pairs[1].global_selection.state,
            AudioAlignmentBatchGlobalSelectionState::Cancelled
        );
        assert!(!terminal.pairs[1].global_selection.selected);
    }

    #[test]
    fn audio_alignment_batch_cancel_discards_staging_when_final_identity_verification_fails() {
        let plan = test_plan_with_selected_global_evidence(
            plan_audio_alignment_batch(test_audio_alignment_batch_request(Some(vec![
                ("source-1", "target-1"),
                ("source-2", "target-2"),
            ])))
            .unwrap(),
        );
        let job_id = format!("test-audio-batch-cancel-identity-{}", current_time_ms());
        let cancel_flag = Arc::new(AtomicBool::new(false));
        insert_audio_alignment_batch_job(&job_id, &plan, cancel_flag.clone()).unwrap();

        run_audio_alignment_batch_job_with_pair_executor_and_finalizer(
            job_id.clone(),
            cancel_flag,
            plan,
            |running_job_id, pair_index, _pair, _cancel_flag| {
                if pair_index == 0 {
                    return Ok(test_audio_alignment_batch_proposal(
                        "must-not-survive-cancel",
                    ));
                }
                cancel_audio_alignment_batch_job(running_job_id.to_string()).unwrap();
                Err(AUDIO_ALIGNMENT_CANCELLED.to_string())
            },
            |completed_pair_indices, ignore_cancel| {
                assert!(ignore_cancel);
                assert_eq!(completed_pair_indices, &[0]);
                Err("blocked:media-identity-changed：cancel fixture".to_string())
            },
        );

        let terminal = get_audio_alignment_batch_job(job_id).unwrap();
        assert_eq!(terminal.status, AudioAlignmentJobStatus::Failed);
        assert_eq!(terminal.failed_pair_count, terminal.total_pair_count);
        assert!(terminal.pairs.iter().all(|pair| pair.proposal.is_none()));
        assert!(terminal
            .pairs
            .iter()
            .all(|pair| pair.status == AudioAlignmentJobStatus::Failed));
        assert!(terminal.pairs.iter().all(|pair| {
            pair.global_selection.state == AudioAlignmentBatchGlobalSelectionState::Failed
                && !pair.global_selection.selected
                && pair.global_selection.top_k.is_empty()
        }));
    }

